(window.JCPA_DATA=window.JCPA_DATA||{})["income"]={"id":"income","name":"قانون ضريبة الدخل","full":"قانون ضريبة الدخل رقم (34) لسنة 2014 وتعديلاته","icon":"🧾","articles":[{"n":"1","chapter":"","notes":[],"source":"يسمى هذا القانون (قانون ضريبة الدخل لسنة ٢٠١٤) ويعمل به اعتباراً من ٢٠١٥/١/١.","title":"اسم القانون وبدء العمل به","memo":"⭐ قانون ضريبة الدخل لسنة ٢٠١٤، ويعمل به اعتباراً من ٢٠١٥/١/١","qs":[{"q":"يُعمل بقانون ضريبة الدخل لسنة ٢٠١٤ اعتباراً من:","o":["٢٠١٥/١/١","٢٠١٤/١/١","٢٠١٤/١٢/٣١","٢٠١٩/١/١"],"a":0}]},{"n":"2","chapter":"","notes":["نشر القانون الأصلي في عدد الجريدة الرسمية ٥٣٢٠ تاريخ ٢٠١٤/١٢/٣١ وطرأ عليه تعديل بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨ المنشور في عدد الجريدة الرسمية ٥٥٤٧ تاريخ ٢٠١٨/١٢/٢.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"يكون للكلمات والعبارات التالية حيثما وردت في هذا القانون المعاني المخصصة لها أدناه، ما لم تدل القرينة على غير ذلك:\nالوزير : وزير المالية.\nالدائرة : دائرة ضريبة الدخل والمبيعات.\nالضريبة : ضريبة الدخل.\nالمدير : مدير عام الدائرة.\nالمكلف : كل شخص ملزم بدفع الضريبة أو اقتطاعها أو توريدها وفق أحكام هذا القانون.\nالدخل من الوظيفة : الرواتب والأجور والعلاوات والمكافآت والبدلات وأي امتيازات نقدية أو عينية أخرى تتأتى للموظف من الوظيفة سواء كانت في القطاع العام أو الخاص.\nنشاط الأعمال : النشاط الذي يمارسه الشخص بقصد تحقيق ربح أو مكسب بما في ذلك النشاط التجاري أو الصناعي أو الزراعي أو المهني أو الخدمي أو الحرفي.\nالدخل من الاستثمار : أي دخل متحقق خلاف الدخل من الوظيفة أو الدخل من نشاط الأعمال.\nالدخل الإجمالي : دخل المكلف القائم من جميع مصادر الدخل الخاضعة للضريبة.\nالدخل الصافي : ما يتبقى من الدخل الإجمالي من كل مصدر خاضع للضريبة بعد تنزيل المصاريف المقبولة.\nالدخل المعفى : الدخل الذي لا يدخل ضمن الدخل الإجمالي للمكلف بموجب أحكام هذا القانون.\nالمصاريف المقبولة : المصاريف والنفقات التي أنفقت أو استحقت كلياً وحصرياً خلال الفترة الضريبية لغايات إنتاج دخل خاضع للضريبة التي يجوز تنزيلها من الدخل الإجمالي وفق أحكام هذا القانون.\nالدخل الخاضع للضريبة : ما يتبقى من الدخل الصافي أو مجموع الدخول الصافية بعد تنزيل الخسارة المدورة من فترات ضريبية سابقة والإعفاءات الشخصية والتبرعات على التوالي.\nالضريبة المستحقة : مقدار الضريبة المستحقة وفق أحكام هذا القانون.\nرصيد الضريبة المستحقة : مقدار الضريبة المستحقة بعد إجراء التقاص وفق ما تقتضيه أحكام هذا القانون وطرح دفعات الضريبة المقدمة والضرائب المقتطعة من المصدر ما لم تكن قطعية.\nالأصول الرأسمالية : الأصول التي يتم شراؤها أو المستأجرة تمويلياً أو تلك التي بحوزة المكلف على سبيل التملك حالاً أو مآلاً لغايات الاحتفاظ بها لأكثر من سنة والتي لا تباع ولا تشترى ضمن النشاط الاعتيادي للمكلف.\nالربح الرأسمالي : الربح الناجم عن بيع الأصول الرأسمالية أو تبديلها.\nالخسارة الرأسمالية : الخسارة الناجمة عن بيع أو تبديل الأصول الرأسمالية.\nالسنة المالية : الفترة المكونة من اثني عشر شهراً متتالياً والتي يغلق الشخص حساباته في نهايتها.\nالفترة الضريبية : الفترة التي تحتسب الضريبة على أساسها وفق أحكام هذا القانون.\nالإقرار الضريبي : تصريح بالدخل والمصاريف والإعفاءات والضريبة المستحقة يقدمه الشخص وفق النموذج المعتمد من الدائرة.\nالمدقق : موظف الدائرة الذي يتولى تدقيق الإقرارات الضريبية وتقدير الضريبة واحتساب أي مبالغ أخرى مترتبة على المكلف والقيام بأي مهام وواجبات أخرى منوطة به وفق أحكام هذا القانون.\nالشخص : الشخص الطبيعي أو الاعتباري.\nالشخص المقيم : الشخص الطبيعي المقيم أو الشخص الاعتباري المقيم.\nالشخص الطبيعي المقيم : من أقام فعلياً في المملكة لمدة لا تقل عن (١٨٣) يوماً خلال الفترة الضريبية سواء كانت إقامته متصلة أو متقطعة أو الموظف الأردني الذي يعمل فعلياً لأي مدة خلال الفترة الضريبية لدى الحكومة أو أي من المؤسسات الرسمية العامة أو المؤسسات العامة داخل المملكة أو خارجها.\nالشخص الاعتباري المقيم : الشخص الاعتباري الذي:\n١-تم تأسيسه أو تسجيله وفق أحكام التشريعات الأردنية وكان له في المملكة مركز أو فرع يمارس الإدارة والرقابة على عمله فيها، أو\n٢-مركز إدارته الرئيسي أو الفعلي في المملكة، أو\n٣-تملك الحكومة أو أي من المؤسسات الرسمية العامة أو المؤسسات العامة نسبة تزيد على (٥٠%) من رأسماله.\nالشخص ذو العلاقة:\n١-الشخص الطبيعي الذي يمتلك هو أو أي من أقاربه حتى الدرجة الثانية نسبة تتجاوز (٥٠%) من رأسمال شخص اعتباري آخر.\n٢-الشخص الاعتباري الذي يمتلك نسبة تتجاوز (٥٠%) من رأسمال شخص اعتباري آخر أو يمتلك حق السيطرة في اتخاذ القرارات.\n٣-الشخص الطبيعي المرتبط بشخص طبيعي آخر إذا كان زوجاً أو ذا قرابة حتى الدرجة الأولى.\nالتهرب الضريبي : استعمال أساليب احتيالية تنطوي على غش أو خداع أو تزوير أو إخفاء البيانات أو تقديم بيانات وهمية أو المشاركة في أي منها قصداً بهدف عدم دفع الضريبة أو التصريح عنها، كلياً أو جزئياً أو تخفيضها وفق ما هو محدد في هذا القانون.\nالمعال : زوج المكلف أو أولاده أو أصوله أو أقاربه حتى الدرجة الثانية الذين يتولى المكلف الإنفاق عليهم.\nالبنك : الشركة المرخصة لممارسة الأعمال المصرفية في المملكة وفق أحكام قانون البنوك.\nالشركة المالية : الشركة المالية المعرفة وفقا لقانون البنوك بما في ذلك شركة الصرافة وشركة التمويل.\nتعدين المواد الأساسية : استكشاف واستخراج واستغلال خامات الفوسفات والبوتاس واليورانيوم ومشتقات أي منها وأي خامات طبيعية أخرى تحدد بقرار من مجلس الوزراء وتستثنى من ذلك صناعة الأسمدة والاسمنت.\nشركات الاتصالات الأساسية : شركات الاتصالات الحاصلة على رخص اتصالات فردية وفق أحكام قانون الاتصالات.\nالإتاوة : المبالغ المتحققة أيا كان نوعها مقابل استعمال أو الحق في استعمال حقوق النشر الخاصة بعمل أدبي أو فني أو علمي وأي براءة اختراع أو علامة تجارية أو تصميم أو نموذج أو خلطة أو تركيبة أو مقابل استعمال أو الحق في استعمال معدات صناعية أو تجارية أو علمية أو معلومات متعلقة بالخبرة الصناعية أو التجارية أو العلمية.\nهيئة الاعتراض : هيئة الاعتراض المشكلة بمقتضى أحكام هذا القانون.\nالمحكمة : المحكمة المختصة وفق أحكام هذا القانون.","title":"التعاريف","memo":"⭐ الشخص الطبيعي المقيم: أقام فعلياً (١٨٣) يوماً على الأقل خلال الفترة الضريبية متصلة أو متقطعة، أو الموظف الأردني لدى الحكومة أو المؤسسات العامة داخل المملكة أو خارجها لأي مدة\n⭐ الشخص الاعتباري المقيم: مؤسس وفق التشريعات الأردنية وله مركز/فرع إدارة ورقابة، أو مركز إدارته الرئيسي أو الفعلي في المملكة، أو تملك الحكومة أكثر من (٥٠%) من رأسماله\n⭐ ذو العلاقة: ملكية تتجاوز (٥٠%) (للشخص أو أقاربه حتى الدرجة الثانية)، أو زوج/قريب حتى الدرجة الأولى؛ المعال: الزوج والأولاد والأصول والأقارب حتى الدرجة الثانية\n⭐ الأصول الرأسمالية: يحتفظ بها لأكثر من سنة ولا تباع ضمن النشاط الاعتيادي؛ تعدين المواد الأساسية يستثني صناعة الأسمدة والاسمنت؛ الدخل الخاضع = الصافي بعد تنزيل الخسارة المدورة ثم الإعفاءات الشخصية ثم التبرعات","qs":[{"q":"يُعد الشخص الطبيعي مقيماً إذا أقام فعلياً في المملكة خلال الفترة الضريبية مدة لا تقل عن:","o":["(١٨٣) يوماً متصلة أو متقطعة","(١٨٣) يوماً متصلة فقط","(١٨٠) يوماً متصلة أو متقطعة","(٩٠) يوماً متصلة"],"a":0},{"q":"يُعد الشخص الاعتباري مقيماً إذا كانت الحكومة أو المؤسسات العامة تملك من رأسماله نسبة تزيد على:","o":["(٥٠%)","(٢٥%)","(٤٠%)","(٧٥%)"],"a":0},{"q":"يُعد الشخص الطبيعي ذا علاقة بشخص طبيعي آخر إذا كان زوجاً له أو ذا قرابة منه حتى الدرجة:","o":["الأولى","الثانية","الثالثة","الرابعة"],"a":0},{"q":"أي مما يلي لا يدخل ضمن تعريف (تعدين المواد الأساسية)؟","o":["صناعة الأسمدة","استخراج خامات الفوسفات","استغلال خامات البوتاس","استكشاف خامات اليورانيوم"],"a":0}]},{"n":"3","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-يخضع للضريبة أي دخل يتأتى في المملكة لأي شخص أو يجنيه منها بغض النظر عن مكان الوفاء بما في ذلك الدخول التالية:\n١-الدخل المتأتي من نشاط الأعمال.\n٢-الفوائد والعمولات والخصميات وفروقات العملة وأرباح الودائع والأرباح المتأتية من البنوك وغيرها من الأشخاص الاعتبارية المقيمة.\n٣-الإتاوات.\n٤-الدخل من بيع البضائع.\n٥-الدخل من بيع أو تأجير منقولات واقعة في المملكة.\n٦-الدخل من تأجير عقارات واقعة في المملكة والدخل من الخلو والمفتاحية.\n٧-الدخل من بيع أو تأجير الأصول المعنوية الموجودة في المملكة بما في ذلك الشهرة.\n٨-الدخل من أقساط التأمين المستحقة بموجب اتفاقات التأمين وإعادة التأمين للأخطار داخل المملكة.\n٩-الدخل من خدمات الاتصالات بجميع صورها بما في ذلك الاتصالات الدولية.\n١٠-الدخل من النقل داخل المملكة وبين المملكة وأي دولة أخرى.\n١١-الدخل الناجم عن إعادة التصدير.\n١٢-بدل الخدمة الذي يجنيه الشخص غير المقيم من المملكة والناشئ عن خدمة قدمها لأي شخص إذا تمت مزاولة العمل أو النشاط المتعلق بذلك البدل في المملكة أو إذا تم استخدام مخرجات هذه الخدمة داخلها.\n١٣-الدخل من أرباح الجوائز واليانصيب إذا زاد مقدار أو قيمة كل منها على ألف دينار سواء كانت نقدية أو عينية.\n١٤-الدخل الناجم عن أي عقد في المملكة كأرباح الوكالات التجارية وما ماثلها سواء كان مصدره داخل المملكة أو خارجها.\n١٥-أي دخل آخر لم يتم إعفاؤه بمقتضى أحكام هذا القانون.\nب-لغايات هذا القانون يتم احتساب قيمة الدخل العيني حسب سعر السوق في تاريخ الاستحقاق لذلك الدخل.\nج-يخضع للضريبة:\n١-الدخل الصافي الذي يتحقق للشخص المقيم من أي مصدر خارج المملكة شريطة أن يكون قد نشأ عن أموال أو ودائع من المملكة.\n٢-مجموع الدخول الصافية التي يحققها فرع الشركة الأردنية العاملة خارج المملكة والمعلن في بياناتها المالية الختامية المصادق عليها من محاسب قانوني خارجي.\n٣-يعتبر الدخل الصافي المشار إليه في البندين (١) و (٢) من هذه الفقرة دخلاً خاضعاً للضريبة وتفرض الضريبة عليه بنسبة (١٠%) ولا يجوز السماح بتنزيل أي مبلغ أو جزء منه لأي سبب من الأسباب.\nد-يخضع للضريبة الدخل الناجم عن التجارة الالكترونية للسلع والخدمات.","title":"الدخول الخاضعة للضريبة","memo":"⭐ يخضع أي دخل يتأتى في المملكة أو يُجنى منها بغض النظر عن مكان الوفاء\n⭐ الجوائز واليانصيب تخضع إذا زادت قيمة كل منها على ألف دينار نقدية أو عينية؛ والدخل العيني يُقوَّم بسعر السوق في تاريخ الاستحقاق\n⭐ دخل المقيم من الخارج الناشئ عن أموال أو ودائع من المملكة، ودخل فرع الشركة الأردنية بالخارج: ضريبة (١٠%) دون أي تنزيل\n⭐ يخضع دخل التجارة الالكترونية للسلع والخدمات","qs":[{"q":"يخضع للضريبة الدخل من أرباح الجوائز واليانصيب إذا زاد مقدار أو قيمة كل منها على:","o":["ألف دينار","خمسمائة دينار","ألفي دينار","خمسة آلاف دينار"],"a":0},{"q":"تُفرض الضريبة على الدخل الصافي لفرع شركة أردنية عاملة خارج المملكة والمعلن في بياناتها المالية بنسبة:","o":["(١٠%) دون السماح بتنزيل أي مبلغ منه","(٢٠%) بعد تنزيل المصاريف المقبولة","(٥%) دون السماح بتنزيل أي مبلغ منه","(١٥%) بعد تنزيل الخسائر المدورة"],"a":0},{"q":"يُحتسب قيمة الدخل العيني لغايات قانون ضريبة الدخل حسب:","o":["سعر السوق في تاريخ الاستحقاق","التكلفة التاريخية للمال","سعر السوق في تاريخ تقديم الإقرار","القيمة التي يقدرها المدقق"],"a":0}]},{"n":"4","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-يعفى من الضريبة:\n١-الملك.\n٢-دخل المؤسسات الرسمية العامة والمؤسسات العامة والبلديات من داخل المملكة باستثناء دخلها من بدلات الإيجار والخلو والمفتاحية وربح أي نشاط استثماري أو فائض الإيراد السنوي الذي يقرر مجلس الوزراء بناء على تنسيب الوزير إخضاعه للضريبة.\n٣-أرباح الشركة الأجنبية غير العاملة في المملكة مثل شركة المقر ومكتب التمثيل الواردة إليها عن أعمالها في الخارج.\n٤-دخل الأوقاف الخيرية ودخل مؤسسة تنمية أموال الأيتام.\n٥-الأرباح الرأسمالية المتحققة من داخل المملكة باستثناء الأرباح المتحققة على الأصول الخاضعة لأحكام الاستهلاك الواردة في هذا القانون وأرباح بيع الحصص على الشخص الاعتباري وأرباح شركات ومؤسسات تكنولوجيا المعلومات بعد انتهاء المدة المحددة في البند (٧) من هذه الفقرة.\n٦-الدخل المتأتي لشركات رأس المال المغامر المعرفة والمسجلة وفق قانون الشركات.\n٧-الأرباح الرأسمالية الناشئة عن بيع أسهم أو حصص شركات ومؤسسات تكنولوجيا المعلومات التي تتولى إنشاء المعلومات ومعالجتها وتخزينها باستخدام وسائل الكترونية وبرمجياتها وذلك لأول مرة لمدة لا تتجاوز خمس عشرة سنة من تاريخ تسجيلها أو من تاريخ نفاذ أحكام هذا القانون المعدل أيهما أسبق ويتم تمديدها لأي مدة أخرى بقرار من مجلس الوزراء بناء على تنسيب الوزير وتحدد أحكام وشروط الإعفاء بموجب نظام يصدر لهذه الغاية.\n٨-أرباح الحصص والأسهم التي توزعها كل من الشركات ذات المسؤولية المحدودة وشركات التوصية البسيطة وشركات التضامن والشركات المساهمة العامة والخاصة المقيمة في المملكة باستثناء التوزيعات المتأتية للبنوك وشركات الاتصالات الأساسية وشركات تعدين المواد الأساسية وشركات التأمين وشركات إعادة التأمين وشركات الوساطة المالية والشركات المالية والأشخاص الاعتباريين الذين يمارسون أنشطة التأجير التمويلي.\n٩-الدخل الذي يحققه المستثمر غير الأردني المقيم من مصادر خارج المملكة والناشئة من استثمار رأسماله الأجنبي والعوائد والأرباح وحصيلة تصفية استثماراته أو بيع مشروعه أو حصصه أو أسهمه بعد إخراجها من المملكة وفق أحكام قانون الاستثمار أو أي قانون آخر يحل محله.\n١٠-التعويضات التي تدفعها جهات التأمين باستثناء ما يدفع بدل فقدان الدخل من الوظيفة أو من نشاط الأعمال.\n١١-الدخل من الوظيفة المدفوع لأعضاء السلك الدبلوماسي أو القنصلي غير الأردنيين الممثلين للدول الأخرى في المملكة شريطة المعاملة بالمثل.\n١٢-الدخل المتحقق من توزيع التركات للورثة والموصى لهم وفق أحكام التشريعات النافذة.\n١٣-مكافأة نهاية الخدمة المستحقة للموظف عند إنهاء أو انتهاء خدمته عن خدماته بمقتضى التشريعات النافذة أو أي ترتيبات جماعية تمت بموافقة الوزير وذلك:\nأ-بنسبة (١٠٠%) عن خدمات الموظف السابقة لتاريخ ٢٠٠٩/١٢/٣١.\nب-بنسبة (٥٠%) عن خدمات الموظف من تاريخ ٢٠١٠/١/١ ولغاية ٢٠١٤/١٢/٣١.\nج-لأول (١٥٠٠٠) خمسة عشر ألف دينار عن خدمات الموظف من تاريخ ٢٠١٥/١/١.\nد-المبالغ التي تزيد عما ورد في (ب، ج) من هذا البند تفرض عليها ضريبة بمقدار ٩%.\n١٤-أول (٢٥٠٠) دينار من إجمالي الراتب التقاعدي الشهري بما فيه المعلولية.\n١٥-دخل الأعمى ودخل المصاب بعجز كلي من الوظيفة.\n١٦-ما يتحقق للبنوك والشركات المالية غير العاملة في المملكة من البنوك العاملة في المملكة من فوائد الودائع والعمولات وأرباح الودائع المشاركة في استثمار البنوك والشركات المالية التي لا تتعاطى بالفائدة.\n١٧-أرباح شركات إعادة التأمين غير العاملة في المملكة الناجمة عن عقود التأمين التي تبرمها معها شركات التأمين العاملة في المملكة.\n١٨-الدخل الذي تشمله اتفاقات منع الازدواج الضريبي التي تعقدها الحكومة وبالقدر الذي تنص عليه هذه الاتفاقات.\n١٩-الأموال الموزعة من صناديق تكافل النقابات لأعضائها وورثتهم في حال الوفاة.\n٢٠-مبلغ (٢٠٠٠) ألفي دينار لكل شخص من ذوي الإعاقة المستمرة والدائمة.\nب-يعفى من الضريبة الدخل من الوظيفة المتأتي مما يلي:\n١-المخصصات والعلاوات الإضافية التي تدفع بحكم العمل في الخارج لأعضاء السلك الدبلوماسي والقنصلي الأردني وفقا لأحكام نظام السلك الدبلوماسي ولموظفي الحكومة والمؤسسات الرسمية العامة والمؤسسات العامة والعاملين في أي منها.\n٢-وجبات الطعام المقدمة للموظفين في موقع العمل.\n٣-خدمات الإيواء المقدمة للموظفين في موقع العمل.\n٤-المعدات والألبسة الضرورية لأداء العمل والتي يقدمها صاحب العمل للموظف.\nج-يُعفى من الضريبة دخل كل من الأشخاص والجهات التالية على أن تحدد الأحكام والشروط المتعلقة بهذا الإعفاء بمقتضى نظام يصدر لهذه الغاية:\n١-الأحزاب والنقابات والهيئات المهنية بما فيها الغرف التجارية والصناعية والجمعيات التعاونية والجمعيات الأخرى المسجلة والمرخصة قانوناً من عمل لا يستهدف الربح.\n٢-المؤسسات الدينية أو الخيرية أو الثقافية أو التربوية أو الرياضية أو الصحية التي لا تستهدف الربح.\n٣-الشركة المعفاة المسجلة بموجب قانون الشركات والمتأتي لها من مزاولة أعمالها خارج المملكة باستثناء الدخول المتأتية لها من مصادر الدخل الخاضعة للضريبة بموجب أحكام هذا القانون.\n٤-الشركة التي لا تهدف إلى تحقيق الربح المسجلة بموجب قانون الشركات.\nد-لا يخضع للضريبة دخل صناديق التقاعد العامة أو صناديق التقاعد الخاصة وصناديق الادخار والتوفير وغيرها من الصناديق الموافق عليها من الوزير من مساهمات المشتركين وأصحاب العمل.\nهـ-يجوز إعفاء أرباح أنواع محددة من صادرات السلع والخدمات ذات المنشأ المحلي لخارج المملكة من الضريبة كلياً أو جزئياً على أن يتم تحديد أسس الإعفاء وأنواع السلع والخدمات المشمولة بهذا الإعفاء ونسبته ومدته بموجب نظام يصدر لهذه الغاية.\nو-مع مراعاة البند (١٨) من الفقرة (أ) من هذه المادة، لا تسري الإعفاءات الواردة في هذه المادة على الدخل الخاضع للضريبة وفق أحكام الفقرة (ج) من المادة (٣) من هذا القانون.","title":"الإعفاءات من الضريبة","memo":"⭐ مكافأة نهاية الخدمة: (١٠٠%) عن الخدمة قبل ٢٠٠٩/١٢/٣١، (٥٠%) من ٢٠١٠/١/١ حتى ٢٠١٤/١٢/٣١، أول (١٥٠٠٠) دينار عن الخدمة من ٢٠١٥/١/١، والزائد ضريبة (٩%)\n⭐ يعفى أول (٢٥٠٠) دينار من إجمالي الراتب التقاعدي الشهري، ومبلغ (٢٠٠٠) دينار لكل شخص من ذوي الإعاقة المستمرة والدائمة، ودخل الأعمى والمصاب بعجز كلي من الوظيفة\n⭐ أرباح بيع أسهم شركات تكنولوجيا المعلومات معفاة لمدة لا تتجاوز خمس عشرة سنة (تمدد بقرار مجلس الوزراء بتنسيب الوزير)\n⭐ توزيعات أرباح الشركات المقيمة معفاة باستثناء ما يتأتى للبنوك والاتصالات الأساسية والتعدين والتأمين وإعادة التأمين والوساطة المالية والشركات المالية والتأجير التمويلي","qs":[{"q":"موظف استحق مكافأة نهاية خدمة عن خدماته اللاحقة لتاريخ ٢٠١٥/١/١، يعفى منها:","o":["أول (١٥٠٠٠) دينار والزائد تفرض عليه ضريبة (٩%)","كامل المكافأة بنسبة (١٠٠%)","(٥٠%) من المكافأة والباقي يخضع للنسب العامة","أول (٢٥٠٠٠) دينار والزائد تفرض عليه ضريبة (٩%)"],"a":0},{"q":"يُعفى من الضريبة من الراتب التقاعدي:","o":["أول (٢٥٠٠) دينار من إجمالي الراتب التقاعدي الشهري بما فيه المعلولية","أول (٢٠٠٠) دينار من إجمالي الراتب التقاعدي الشهري","أول (٢٥٠٠) دينار من إجمالي الراتب التقاعدي السنوي","كامل الراتب التقاعدي دون حد أعلى"],"a":0},{"q":"تُعفى الأرباح الرأسمالية الناشئة عن بيع أسهم شركات تكنولوجيا المعلومات لأول مرة لمدة لا تتجاوز:","o":["خمس عشرة سنة","عشر سنوات","خمس سنوات","عشرين سنة"],"a":0},{"q":"تُعفى أرباح الأسهم التي توزعها الشركات المقيمة في المملكة باستثناء التوزيعات المتأتية إلى:","o":["شركات التأمين","الأشخاص الطبيعيين","الشركات الصناعية","الشركات التجارية ذات المسؤولية المحدودة"],"a":0}]},{"n":"5","chapter":"","notes":[],"source":"أ-يعفى من الضريبة أول (١٠٠٠٠٠٠) مليون دينار من مبيعات الشخص الطبيعي المتأتية من نشاط زراعي داخل المملكة.\nب-يعفى من الضريبة أول (٥٠٠٠٠) خمسين ألف دينار من الدخل الصافي للشخص الاعتباري المتأتي داخل المملكة من النشاط الزراعي.\nج-لغايات هذه المادة، يعني النشاط الزراعي ما يلي:\n١-إنتاج المحاصيل والحبوب والخضراوات والفواكه والنباتات والزهور والأشجار.\n٢-تربية المواشي والأسماك والطيور والنحل بما في ذلك إنتاج البيض والعسل.","title":"إعفاء النشاط الزراعي","memo":"⭐ الشخص الطبيعي: يعفى أول (١٠٠٠٠٠٠) مليون دينار من المبيعات الزراعية داخل المملكة\n⭐ الشخص الاعتباري: يعفى أول (٥٠٠٠٠) دينار من الدخل الصافي الزراعي داخل المملكة\n⭐ النشاط الزراعي: إنتاج المحاصيل والخضراوات والفواكه والزهور والأشجار، وتربية المواشي والأسماك والطيور والنحل بما فيها إنتاج البيض والعسل","qs":[{"q":"يُعفى من الضريبة للشخص الطبيعي من نشاطه الزراعي داخل المملكة:","o":["أول مليون دينار من مبيعاته","أول (٥٠٠٠٠) دينار من مبيعاته","أول مليون دينار من دخله الصافي","أول (٥٠٠٠٠) دينار من دخله الصافي"],"a":0},{"q":"يُعفى من الضريبة للشخص الاعتباري من النشاط الزراعي داخل المملكة:","o":["أول (٥٠٠٠٠) دينار من دخله الصافي","أول مليون دينار من مبيعاته","أول (١٠٠٠٠٠) دينار من دخله الصافي","أول (٥٠٠٠٠) دينار من مبيعاته"],"a":0},{"q":"أي مما يلي لا يُعد نشاطاً زراعياً لغايات الإعفاء الوارد في القانون؟","o":["تعليب المنتجات الزراعية وتصنيعها","تربية النحل وإنتاج العسل","تربية الأسماك","إنتاج الزهور والأشجار"],"a":0}]},{"n":"6","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"تنزل للمكلف المصاريف المقبولة بما في ذلك المصاريف المبينة تالياً على أن يحدد النظام أحكام هذا التنزيل وإجراءاته:\nأ-ضريبة الدخل الأجنبية المدفوعة عن دخله المتأتي من مصادر خارج المملكة والذي خضع للضريبة فيها وفق أحكام هذا القانون في حال عدم وجود اتفاقية لتجنب الازدواج الضريبي، أما في حال وجود تلك الاتفاقية يتم تطبيق الأحكام المتعلقة بطرق تجنب الازدواج الضريبي الواردة فيها.\nب-1\n١-الفوائد وأرباح المرابحة المدفوعة أو المستحقة لغير الأشخاص ذوي العلاقة.\n٢-الفوائد وأرباح المرابحة المدفوعة أو المستحقة للأشخاص ذوي العلاقة على أن لا يتجاوز المبلغ الجائز تنزيله بنسبة ثلاثة إلى واحد (٣:١) لإجمالي الدين إلى رأس المال المدفوع أو متوسط حقوق الملكية أيهما أكبر، ولا يجوز تنزيل أو تدوير ما زاد من الفائدة أو المرابحة عن الحد المسموح به في الفترة الضريبية بما فيها الفوائد أو المرابحة المرسملة على الأصول وفق أحكام هذا البند.\nج-مخصصات البنوك وفق أحكام قانون البنوك مع مراعاة ما يلي:\n١-يلتزم البنك بتخفيض المخصص الخاص المرصود مقابل الائتمان غير العامل في أي من الحالات التالية:\nأ.تحويل الائتمان غير العامل إلى ائتمان عامل وفق أحكام قانون البنوك.\nب.تحصيل قيمة الائتمان غير العامل.\nج.شطب قيمة الائتمان باعتباره ديناً هالكاً.\nد.أي حالة أخرى يحددها البنك المركزي.\n٢-في حال تخفيض المخصص الخاص للائتمان غير العامل يلتزم البنك بإظهار قيمة التخفيض الذي سبق قبوله ضريبياً في دخله الإجمالي وذلك في الفترة الضريبية التي جرى فيها التخفيض.\nد-مخصصات شركات التأمين المتعلقة بالأقساط غير المكتسبة ومخصص الادعاءات المبلغة تحت التسوية والمخصص الحسابي من دخلها الإجمالي على أن يضاف إلى هذا الدخل ما تم تنزيله من تلك المخصصات خلال الفترة الضريبية السابقة مباشرة وذلك بعد خصم حصة معيدي التأمين وفق الأحكام والإجراءات التي يحددها نظام يصدر لهذه الغاية.\nهـ-مخصصات الديون المشكوك فيها للمكلفين والشركات عدا الواردة في الفقرة (ج) من هذه المادة والذين يلتزمون بتنظيم السجلات والمستندات والبيانات المالية المعدة وفق معايير المحاسبة الدولية والمدققة من محاسب قانوني.\nو-الديون الهالكة التي سبق احتسابها ضمن دخله الإجمالي وفي حال تحصيل الدين الهالك أو أي جزء منه بعد تنزيله يُضاف المبلغ الذي تم تحصيله إلى الدخل الإجمالي في الفترة الضريبية التي تم تحصيله فيها.\nز-المبالغ المدفوعة لتأمين الأخطار المتعلقة بنشاطه الخاضع للضريبة.\nح-استهلاك الأصول الرأسمالية وإطفاء الأصول المعنوية بما فيها الشهرة المستعملة لغايات إنتاج الدخل الخاضع للضريبة ومصاريف التنقيب عن المصادر الطبيعية وفق الأحكام التالية:\n١-لا يجوز للمكلف استهلاك قيمة الأرض وأي أصول أخرى لا تفقد قيمتها مع مرور الزمن.\n٢-يحدد استهلاك أو إطفاء الأصول بنسب مئوية من تكلفتها الأصلية على أن تحدد طرق الاستهلاك والإطفاء والأحكام والنسب والإجراءات المتعلقة بذلك بموجب نظام يصدر لهذه الغاية.\nط-الضرائب والرسوم المدفوعة على أنشطته الخاضعة للضريبة.\nي-المبالغ المدفوعة تعويضاً مدنياً بمقتضى عقود أبرمها المكلف لغايات ممارسة أنشطته الخاضعة للضريبة.\nك-المبالغ التي يدفعها صاحب العمل عن موظفيه للمؤسسة العامة للضمان الاجتماعي، ومساهمته في أي صندوق تقاعد أو ادخار أو أي صندوق آخر يؤسسه صاحب العمل بموافقة الوزير لمصلحة موظفيه.\nل-نفقات الضيافة والسفر التي يتكبدها المكلف.\nم-نفقات معالجة الموظفين ووجبات طعامهم في موقع العمل وسفرهم وتنقلهم والتأمين على حياتهم ضد إصابات العمل أو الوفاة والتأمين الصحي الذي يدفعه صاحب العمل عن الموظفين أو مُعاليهم.\nن-نفقات التسويق والبحث العلمي والتطوير والتدريب.\nس-نفقات الفترات الضريبية السابقة التي لم تكن محددة ونهائية.","title":"المصاريف المقبولة للتنزيل","memo":"⭐ فوائد ومرابحة ذوي العلاقة تنزل بحد نسبة (٣:١) لإجمالي الدين إلى رأس المال المدفوع أو متوسط حقوق الملكية أيهما أكبر، والزائد لا يُنزل ولا يُدوّر\n⭐ مخصصات الديون المشكوك فيها (لغير البنوك) تنزل لمن ينظم سجلات وفق معايير المحاسبة الدولية مدققة من محاسب قانوني\n⭐ الدين الهالك المحصّل بعد تنزيله يضاف للدخل الإجمالي في فترة تحصيله؛ ولا تستهلك الأرض والأصول التي لا تفقد قيمتها، ونسب الاستهلاك بنظام\n⭐ تنزل: الضرائب والرسوم، التأمين، الضمان الاجتماعي، الضيافة والسفر، علاج الموظفين، التسويق والبحث والتدريب، ونفقات فترات سابقة لم تكن محددة ونهائية","qs":[{"q":"يُشترط لتنزيل الفوائد المدفوعة للأشخاص ذوي العلاقة ألا يتجاوز إجمالي الدين إلى رأس المال المدفوع أو متوسط حقوق الملكية أيهما أكبر نسبة:","o":["(٣:١)","(٢:١)","(٤:١)","(١:١)"],"a":0},{"q":"تُنزّل مخصصات الديون المشكوك فيها لغير البنوك شريطة:","o":["التزام المكلف بسجلات وبيانات مالية وفق معايير المحاسبة الدولية مدققة من محاسب قانوني","حصول المكلف على موافقة خطية مسبقة من المدير","ألا تتجاوز (٥%) من الدخل الخاضع للضريبة","صدور حكم قضائي بإعسار المدين"],"a":0},{"q":"حالة عملية: نزّل مكلف ديناً هالكاً سبق احتسابه في دخله الإجمالي، ثم حصّل جزءاً منه لاحقاً. يُعامل المبلغ المحصّل بأن:","o":["يضاف إلى الدخل الإجمالي في الفترة الضريبية التي تم تحصيله فيها","يعاد احتساب ضريبة الفترة التي نُزّل فيها الدين","لا يضاف إلى الدخل لسبق تنزيله","يوزع على الفترات الضريبية الخمس اللاحقة"],"a":0},{"q":"أي من الأصول التالية لا يجوز للمكلف استهلاكه؟","o":["الأرض","المباني","الآلات والمعدات","الشهرة"],"a":0}]},{"n":"7","chapter":"","notes":[],"source":"لا يجوز للمكلف تنزيل ما يلي:\nأ-الضريبة والغرامات والمبالغ الأخرى المترتبة بمقتضى أحكام هذا القانون.\nب-الغرامات الجزائية والغرامات المدفوعة تعويضاً مدنياً بموجب أحكام هذا القانون.\nج-تكلفة الأصول الرأسمالية وتركيبها وتكلفة الأصول المعنوية مع مراعاة ما ورد في الفقرة (ح) من المادة (٦) من هذا القانون.\nد-المصاريف المتعلقة بالدخل الخاضع للضريبة القطعية أو الدخل المعفى من الضريبة على أن تحدد التعليمات التنفيذية كيفية احتساب هذه المصاريف.\nهـ-ما زاد على (٥%) خمسة بالمائة من الدخل الخاضع للضريبة لفرع الشخص الاعتباري الأجنبي الخاضع للضريبة فيما يتعلق بحصته من نفقات المركز الرئيسي الموجود خارج المملكة.\nو-المخصصات والاحتياطيات التي لم يرد في هذا القانون نص صريح على تنزيلها.\nز-المبالغ المدفوعة الجائز استردادها بموجب بوليصة تأمين أو عقد.\nح-المصاريف المنزلية أو الشخصية أو الخاصة.","title":"المصاريف غير المقبولة","memo":"⭐ لا ينزل: الضريبة وغراماتها، الغرامات الجزائية، تكلفة الأصول الرأسمالية (عدا الاستهلاك)، مصاريف الدخل المعفى أو الخاضع لضريبة قطعية\n⭐ لا ينزل ما زاد على (٥%) من الدخل الخاضع لفرع الشخص الاعتباري الأجنبي من حصته في نفقات المركز الرئيسي\n⭐ لا تنزل المخصصات والاحتياطيات إلا بنص صريح، ولا المبالغ القابلة للاسترداد بموجب بوليصة تأمين، ولا المصاريف المنزلية أو الشخصية","qs":[{"q":"لا يجوز لفرع الشخص الاعتباري الأجنبي تنزيل ما زاد من حصته في نفقات المركز الرئيسي على نسبة من دخله الخاضع للضريبة مقدارها:","o":["(٥%)","(١٠%)","(٢٥%)","(٣%)"],"a":0},{"q":"أي مما يلي لا يجوز للمكلف تنزيله؟","o":["الغرامات الجزائية","الضرائب والرسوم المدفوعة على أنشطته الخاضعة للضريبة","نفقات التسويق والتدريب","المبالغ المدفوعة لتأمين أخطار نشاطه الخاضع"],"a":0},{"q":"لا يجوز تنزيل المخصصات والاحتياطيات ما لم:","o":["يرد في القانون نص صريح على تنزيلها","يوافق عليها المدير خطياً","يصادق عليها محاسب قانوني","تقرها الهيئة العامة للشركة"],"a":0}]},{"n":"8","chapter":"","notes":[],"source":"أ-\n١-إذا لحقت خسارة بالشخص في أي من أنشطة الأعمال الخاضعة للضريبة داخل المملكة فيتم تنزيلها من أرباح مصادر الدخل الأخرى في الفترة الضريبية ذاتها.\n٢-إذا بلغت الخسارة مقداراً لا يمكن تنزيله بالكامل فيدور رصيدها للفترات الضريبية اللاحقة للفترة الضريبية التي وقعت فيها وبحد أعلى لا يتجاوز خمس سنوات لاكتسابها الصفة القطعية.\nب-تدور خسائر نشاط الأعمال المتحققة خارج المملكة لتنزل من أرباح النشاط ذاته المتحققة خارجها.\nج-لا يجوز أن يشمل مبلغ الخسائر المدورة أي مبالغ تتعلق بالتبرعات أو الإعفاءات الشخصية.\nد-لا يجوز تنزيل الخسارة أو تدويرها والتي لو كانت ربحاً لما خضع للضريبة وفق أحكام هذا القانون.\nهـ-لا يجوز تنزيل الخسارة أو تدويرها إلا إذا أبرز المكلف حسابات أصولية وصحيحة وفق أحكام هذا القانون والأنظمة والتعليمات التنفيذية الصادرة بمقتضاه.","title":"تنزيل الخسائر وتدويرها","memo":"⭐ خسارة نشاط الأعمال داخل المملكة تنزل من أرباح المصادر الأخرى في الفترة ذاتها، والباقي يدوّر بحد أعلى خمس سنوات\n⭐ خسائر النشاط خارج المملكة تنزل فقط من أرباح النشاط ذاته المتحققة خارجها\n⭐ لا تشمل الخسارة المدورة التبرعات أو الإعفاءات الشخصية، ولا تُدوّر خسارة لو كانت ربحاً لما خضعت، ولا تدوير إلا بحسابات أصولية وصحيحة","qs":[{"q":"تُدوّر الخسارة التي لا يمكن تنزيلها بالكامل للفترات الضريبية اللاحقة بحد أعلى لا يتجاوز:","o":["خمس سنوات","ثلاث سنوات","أربع سنوات","سبع سنوات"],"a":0},{"q":"تُدوّر خسائر نشاط الأعمال المتحققة خارج المملكة لتُنزّل من:","o":["أرباح النشاط ذاته المتحققة خارج المملكة","أرباح أي نشاط داخل المملكة","الدخل الإجمالي للمكلف من جميع المصادر","الدخل من الوظيفة للمكلف"],"a":0},{"q":"لا يجوز تنزيل الخسارة أو تدويرها إلا إذا:","o":["أبرز المكلف حسابات أصولية وصحيحة وفق أحكام القانون","وافق المدير خطياً على تدويرها","لم تتجاوز الخسارة (٥٠%) من رأس المال","قدم المكلف كفالة بنكية بقيمتها"],"a":0}]},{"n":"9","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-للتوصل إلى الدخل الخاضع للضريبة تُنزل للشخص الطبيعي المقيم المكلف المبالغ التالية:\n١-عشرة آلاف دينار إعفاء شخصياً لسنة (٢٠١٩)، وتسعة آلاف دينار لسنة (٢٠٢٠) وما يليها.\n٢-عشرة آلاف دينار عن المعالين مهما كان عددهم لسنة (٢٠١٩) وتسعة آلاف دينار لسنة (٢٠٢٠) وما يليها.\n٣-يمنح الشخص الطبيعي والمعالون إعفاءات مقابل نفقات العلاج والتعليم والإيجار وفوائد قروض الإسكان والمرابحة على النحو التالي:\nأ.ألف دينار للمكلف تبدأ من سنة (٢٠٢٠ وما تلاها).\nب.ألف دينار لزوج المكلف تبدأ من سنة (٢٠٢٠ وما تلاها).\nج.ألف دينار لكل ولد وبحد أقصى (ثلاثة آلاف) دينار.\nب-\n١-في حال تقديم إقرارات ضريبية مشتركة أو منفصلة من قبل الأزواج، أو في حال قرارات التقدير المشتركة أو المنفصلة لهم، لا يجوز أن يتجاوز الإعفاء المسموح به للمكلف ولمن يعيلهم بموجب أحكام الفقرة (أ) من هذه المادة (٢٣٠٠٠) دينار.\n٢-لا يجوز تقديم الإقرار الضريبي المشترك أو إصدار قرار التقدير المشترك إلا بموافقة الأزواج.\nج-للمكلف أو لزوجه الاستفادة من فرق الإعفاء الممنوح بمقتضى أحكام الفقرة (أ) من هذه المادة على أن لا يتجاوز الإعفاء الممنوح في الأحوال جميعها (٢٣٠٠٠) دينار.\nد-للشخص الطبيعي الأردني غير المقيم الاستفادة من الإعفاءات الخاصة بالمعالين المقيمين في المملكة إذا كان يتولى إعالتهم.\nهـ-للمكلف المرأة المعيلة الحق في الحصول على الإعفاء للمعالين المنصوص عليه في الفقرة (أ) من هذه المادة وفي حال التقدم للاستفادة من هذا الإعفاء من أكثر من مكلف معيل يتم تقاسمها حسب نسبة الإعالة شريطة تقديم فواتير أو مستندات معززة لذلك وإلا فإنه يتم تقاسمها بالتساوي بين المعيلين.","title":"الإعفاءات الشخصية والعائلية","memo":"⭐ الإعفاء الشخصي (٩٠٠٠) دينار وللمعالين (٩٠٠٠) دينار مهما كان عددهم لسنة ٢٠٢٠ وما يليها (كانت (١٠٠٠٠) لكل منهما لسنة ٢٠١٩)\n⭐ إعفاء نفقات العلاج والتعليم والإيجار وفوائد قروض الإسكان: ألف للمكلف، ألف لزوجه، ألف لكل ولد بحد أقصى (٣٠٠٠) دينار\n⭐ الحد الأقصى للإعفاءات (٢٣٠٠٠) دينار في جميع الأحوال؛ ولا إقرار مشترك إلا بموافقة الأزواج\n⭐ الأردني غير المقيم يستفيد من إعفاء المعالين المقيمين؛ وللمرأة المعيلة حق إعفاء المعالين ويقسم بين المعيلين حسب نسبة الإعالة وإلا بالتساوي","qs":[{"q":"يبلغ الإعفاء الشخصي للشخص الطبيعي المقيم لسنة ٢٠٢٠ وما يليها:","o":["تسعة آلاف دينار","عشرة آلاف دينار","اثنا عشر ألف دينار","ثلاثة وعشرون ألف دينار"],"a":0},{"q":"لا يجوز أن يتجاوز مجموع الإعفاءات الممنوحة للمكلف ولمن يعيلهم في الأحوال جميعها:","o":["(٢٣٠٠٠) دينار","(٢٠٠٠٠) دينار","(١٨٠٠٠) دينار","(٢٨٠٠٠) دينار"],"a":0},{"q":"حالة عملية: مكلف مقيم متزوج وله ولدان، قدّم فواتير تغطي إعفاءات العلاج والتعليم كاملة عن سنة ٢٠٢٢. مجموع إعفاءاته:","o":["(٢٢٠٠٠) دينار","(٢٣٠٠٠) دينار","(٢٠٠٠٠) دينار","(١٨٠٠٠) دينار"],"a":0},{"q":"لا يجوز تقديم الإقرار الضريبي المشترك أو إصدار قرار التقدير المشترك إلا:","o":["بموافقة الأزواج","بموافقة المدير","بطلب من الزوج وحده","بقرار من المدقق"],"a":0}]},{"n":"10","chapter":"","notes":[],"source":"أ-يجوز للشخص تنزيل أي مبلغ دفع خلال الفترة الضريبية باعتباره تبرعاً دون نفع شخصي لأي من الدوائر الحكومية أو المؤسسات الرسمية العامة أو المؤسسات العامة أو البلديات من الدخل الإجمالي في الفترة التي تم فيها الدفع.\nب-يسمح لأي شخص تنزيل الاشتراكات والتبرعات المدفوعة في المملكة دون نفع شخصي بمقاصد دينية أو خيرية أو إنسانية أو علمية أو بيئية أو ثقافية أو رياضية أو مهنية إذا أقر مجلس الوزراء لها هذه الصفة والاشتراكات والتبرعات المدفوعة للأحزاب على أن لا تزيد المبالغ المدفوعة عما يسمح به قانون الأحزاب السياسية ويشترط أن لا يتجاوز ما يُنزل بمقتضى أحكام هذه الفقرة عن (٢٥%) من الدخل الخاضع للضريبة بعد إجراء التنزيل المنصوص عليه في الفقرة (أ) من هذه المادة قبل إجراء هذا التنزيل.","title":"تنزيل التبرعات","memo":"⭐ التبرع دون نفع شخصي للدوائر الحكومية والمؤسسات العامة والبلديات ينزل من الدخل الإجمالي في فترة الدفع دون سقف\n⭐ التبرعات لمقاصد دينية أو خيرية أو إنسانية أو علمية أو بيئية أو ثقافية أو رياضية أو مهنية تنزل إذا أقر لها مجلس الوزراء هذه الصفة\n⭐ سقف التبرعات غير الحكومية (٢٥%) من الدخل الخاضع للضريبة؛ وتبرعات الأحزاب في حدود قانون الأحزاب السياسية","qs":[{"q":"حالة عملية: تبرع مكلف دون نفع شخصي لإحدى البلديات. يُعامل هذا التبرع بأن:","o":["يُنزّل من الدخل الإجمالي في الفترة التي تم فيها الدفع","يُنزّل بما لا يتجاوز (٢٥%) من الدخل الخاضع للضريبة","لا يُنزّل لأنه دفع لجهة حكومية","يُنزّل على خمس فترات ضريبية"],"a":0},{"q":"لا يجوز أن يتجاوز ما ينزل من التبرعات لمقاصد خيرية أو إنسانية أو ثقافية نسبة من الدخل الخاضع للضريبة مقدارها:","o":["(٢٥%)","(١٠%)","(٥٠%)","(٢٠%)"],"a":0},{"q":"يُشترط لتنزيل التبرعات المدفوعة لمقاصد خيرية أو علمية أو رياضية أن يقر لها هذه الصفة:","o":["مجلس الوزراء","وزير المالية","مدير عام الدائرة","هيئة الاعتراض"],"a":0}]},{"n":"11","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-تستوفى الضريبة للشخص الطبيعي من الدخل الخاضع للضريبة وفقاً للنسب التالية كما يلي:\n١-(٥%) خمسة بالمائة عن كل دينار من الخمسة آلاف دينار الأولى.\n٢-(١٠%) عشرة بالمائة عن كل دينار من الخمسة آلاف دينار التالية.\n٣-(١٥%) خمسة عشر بالمائة عن كل دينار من الخمسة آلاف دينار التالية.\n٤-(٢٠%) عشرون بالمائة عن كل دينار من الخمسة آلاف دينار التالية.\n٥-(٢٥%) خمسة وعشرون بالمائة عن كل دينار مما تلاها ولغاية مليون دينار.\n٦-(٣٠%) ثلاثون بالمائة عن كل دينار من الدخل الخاضع للضريبة للمكلف الذي يزيد على (١٠٠٠٠٠٠) مليون دينار.\nب-تستوفى الضريبة عن الدخل الخاضع للضريبة للشخص الاعتباري حسب النسب التالية:\n١-(٢٠%) عشرون بالمائة لجميع الأشخاص الاعتباريين باستثناء ما ورد في البندين (٢) و(٣) من هذه الفقرة.\n٢-(٢٤%) أربعة وعشرون بالمائة عن كل دينار لشركات الاتصالات الأساسية وشركات توزيع وتوليد الكهرباء وشركات تعدين المواد الأساسية وشركات التأمين وشركات إعادة التأمين وشركات الوساطة المالية والشركات المالية والأشخاص الاعتباريين الذين يمارسون أنشطة التأجير التمويلي.\n٣-(٣٥%) خمسة وثلاثون بالمائة للبنوك.\nج-تخفض النسب المبينة أدناه ولمدة لا تتجاوز خمس سنوات من تاريخ نفاذ أحكام هذا القانون المعدل من الضريبة المستحقة على النشاط الصناعي ووفقا لما يلي:\n١-الأنشطة الصناعية باستثناء صناعة الأدوية والملابس:\nالسنة : النسبة\n٢٠١٩ : ٢٥%\n٢٠٢٠ : ٢٠%\n٢٠٢١ : ١٥%\n٢٠٢٢ : ١٠%\n٢٠٢٣ : ٥%\n٢-صناعة الأدوية والملابس:\nالسنة : النسبة\n٢٠١٩ : ٥٠%\n٢٠٢٠ : ٣٠%\n٢٠٢١ : ٢٠%\n٢٠٢٢ : ١٠%\n٢٠٢٣ : ٥%\nد-تحدد الأنشطة الصناعية المشمولة بأحكام البند (١) من الفقرة (ج) من هذه المادة وإجراءات تطبيق تلك الفقرة وشروطها بموجب نظام يصدر لهذه الغاية.\nهـ-عند احتساب الدخل الخاضع للضريبة أو الضريبة المستحقة يُخفض المبلغ الناتج لأقرب دينار.\nو-١-ينشأ لدى الدائرة حساب يسمى (حساب المساهمة الوطنية) وعلى الوزير رصد موجودات هذا الحساب في الموازنة العامة لسداد الدين العام، وتتكون إيرادات هذا الحساب مما يلي:\nأ.٣% من الدخل الخاضع للضريبة للبنوك وشركات توزيع وتوليد الكهرباء.\nب.٧% من الدخل الخاضع للضريبة لشركات تعدين المواد الأساسية.\nج.٤% من الدخل الخاضع للضريبة لشركات الوساطة المالية والشركات المالية والأشخاص الاعتباريين الذين يمارسون أنشطة التأجير التمويلي.\nد.٢% من الدخل الخاضع للضريبة لشركات الاتصالات الأساسية والتأمين وإعادة التأمين.\nهـ.١% من الدخل الخاضع للضريبة لباقي الأشخاص الاعتباريين.\nو.١% من الدخل الخاضع للضريبة مما يزيد عن (٢٠٠٠٠٠) مائتي ألف دينار للشخص الطبيعي.\nز.التبرعات والهبات.\n٢-تتولى الدائرة فرض وتحصيل قيمة هذه المساهمة وفقاً لأحكام هذه الفقرة وتطبق عليها الأحكام المتعلقة بالضريبة بما في ذلك إجراءات التدقيق والتقدير والتحصيل ومراحل الطعن وغرامة تأخير الدفع.\nز-يتوقف الاقتطاع للفقرة (و) من هذه المادة في حال بلوغ الدين العام النسبة المسموح بها بموجب قانون الدين العام وإدارته الساري المفعول.\nح-في حال لم تلتزم شركات التضامن والتوصية البسيطة المسجلة في المملكة والتي تمارس أي نشاط أو استثمار يخضع دخله للضريبة بتنظيم السجلات والبيانات المالية وفق قانون الشركات وتقديمها للدائرة يجب أن لا يقل الحد الأدنى للضريبة المستحقة عليها عن خمسمائة دينار في السنة.\nط-على الرغم مما ورد في الفقرة (ب) من المادة (٧٨) من هذا القانون والمواد (١١) و(١٤) و(٤٤) من قانون الاستثمار رقم (٣٠) لسنة ٢٠١٤:\n١-تفرض الضريبة على دخل المؤسسة المسجلة في المناطق التنموية الناشئة عن أنشطة الصناعات التحويلية التي لا تقل القيمة المحلية المضافة فيها عن (٣٠%) بنسبة (٥%).\n٢-تفرض الضريبة على دخل المؤسسة المسجلة في المناطق التنموية لباقي المشاريع والأنشطة بنسبة (١٠%).\n٣-لمجلس الوزراء بناء على تنسيب مجلس الاستثمار تخفيض هذه النسبة، سواء للأنشطة والمشاريع المسجلة قبل نفاذ أحكام هذا القانون المعدل أو بعده وفقاً للنشاط الاقتصادي والأسس المحددة بذلك بما فيها المنطقة والعمالة والقيمة المضافة وعلى أن تحدد بنظام يصدر لهذه الغاية.\n٤-تفرض الضريبة على الدخل المتأتي للمؤسسة المسجلة في المناطق الحرة التي تمارس نشاطاً صناعياً أو أي نشاط آخر من البيع أو التنازل أو التوريد للسلع والخدمات داخل حدود هذه المناطق بنسبة الضريبة المحددة وفقاً للنشاط الاقتصادي أو الشخص في الفقرتين (أ) و(ب) من هذه المادة.\nي-في حال تملك إحدى الشركات كلياً أو جزئياً نسبة لا تقل عن (١٠%) من رأسمال شركة أخرى فلا يجوز تقاضي الضريبة عن أرباح الشركة المالكة للشركة المملوكة بنسبة تزيد على (١٠%) من مقدار أرباحها في تلك الأرباح.","title":"نسب الضريبة والمساهمة الوطنية","memo":"⭐ الشخص الطبيعي: شرائح (٥%، ١٠%، ١٥%، ٢٠%) لكل خمسة آلاف، ثم (٢٥%) حتى مليون، و(٣٠%) لما زاد على مليون دينار\n⭐ الشخص الاعتباري: (٢٠%) عام، (٢٤%) للاتصالات الأساسية والكهرباء والتعدين والتأمين والوساطة والمالية والتأجير التمويلي، (٣٥%) للبنوك\n⭐ المساهمة الوطنية: ٣% بنوك وكهرباء، ٧% تعدين، ٤% وساطة ومالية وتأجير تمويلي، ٢% اتصالات وتأمين، ١% باقي الاعتباريين، ١% مما يزيد على (٢٠٠٠٠٠) للطبيعي\n⭐ حد أدنى (٥٠٠) دينار للتضامن والتوصية غير الملتزمة بالسجلات؛ المناطق التنموية (٥%) للصناعات التحويلية بقيمة مضافة ≥(٣٠%) و(١٠%) لغيرها؛ التقريب لأقرب دينار","qs":[{"q":"تبلغ نسبة الضريبة على الدخل الخاضع للضريبة للشخص الطبيعي فيما يزيد على مليون دينار:","o":["(٣٠%)","(٢٥%)","(٣٥%)","(٢٠%)"],"a":0},{"q":"تُستوفى الضريبة عن الدخل الخاضع للضريبة للبنوك بنسبة:","o":["(٣٥%)","(٢٤%)","(٢٠%)","(٣٠%)"],"a":0},{"q":"تبلغ نسبة المساهمة الوطنية من الدخل الخاضع للضريبة لشركات تعدين المواد الأساسية:","o":["(٧%)","(٣%)","(٤%)","(٢%)"],"a":0},{"q":"شركة تضامن مسجلة لم تلتزم بتنظيم السجلات والبيانات المالية وفق قانون الشركات. الحد الأدنى للضريبة المستحقة عليها سنوياً:","o":["خمسمائة دينار","ألف دينار","مائتان وخمسون ديناراً","ألفا دينار"],"a":0}]},{"n":"12","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-يتم اقتطاع الضريبة فيما يتعلق بالدخول المبينة تالياً من المصدر ممن يدفعها وفقاً لما يلي:\n١-(٥%) من أي مبالغ مدفوعة من شخص اعتباري مقيم كأتعاب أو أجور أو ما ماثل ذلك لأي شخص مقيم من الأطباء والمحامين والمهندسين ومدققي الحسابات والخبراء والمستشارين والمفوضين عن المكلفين ووكلاء ووسطاء التأمين وإعادة التأمين والمحكمين والسماسرة والوكلاء والوسطاء بالعمولة والوسطاء الماليين ووسطاء الشحن بالعمولة وغيرهم من الأشخاص الذين يتم تحديدهم بموجب تعليمات تنفيذية تصدر لهذه الغاية.\n٢-ما يخضع للضريبة من الدخل المتحقق من فوائد الودائع والعمولات وأرباح الودائع المشاركة في استثمار البنوك والشركات المالية التي لا تتعاطى بالفائدة والمدفوع لأي شخص من البنوك والشركات المالية في المملكة بنسبة (٥%) للشخص الطبيعي و(٧%) للشخص الاعتباري على أن تعتبر هذه المبالغ المقتطعة ضريبة قطعية بالنسبة للشخص الطبيعي والشخص الاعتباري غير المقيم، وتستثنى من أحكام هذا البند فوائد وأرباح الودائع والعمولات المترتبة للبنوك لدى البنوك الأخرى والفوائد والأرباح المستحقة لأي جهات أخرى تحددها التعليمات التنفيذية.\n٣-الدخل من أرباح الجوائز واليانصيب الذي يتجاوز مقدار أو قيمة أي منها ألف دينار وبنسبة (١٥%) ويعتبر المبلغ المقتطع في هذه الحالة ضريبة قطعية.\n٤-الدخل من الوظيفة المتأتي لشخص طبيعي وفق الإجراءات ونسب الاقتطاع التي تحددها التعليمات التنفيذية.\nب-\n١-يترتب على كل شخص استحق لديه أو دفع دخلاً غير معفى من الضريبة لشخص غير مقيم مباشرة أو بالوساطة أن يقتطع من هذا الدخل بتاريخ الاستحقاق أو الدفع أيهما أسبق ما نسبته (١٠%) وأن يعد بياناً يوضح فيه مقدار الدخل والمبلغ المقتطع وأن يزود كلا من الدائرة والمستفيد بنسخة من هذا البيان.\n٢-يجوز بموجب تعليمات تنفيذية اعتبار أي مبلغ مقتطع وفق أحكام البند (١) من هذه الفقرة ضريبة قطعية.\nج-لا يدخل في الدخل الإجمالي للمكلف الدخل الخاضع للاقتطاع من المصدر في حال كان المبلغ المقتطع ضريبة قطعية، وفي غير هذه الحالات تعتبر المبالغ المقتطعة دفعة على حساب الضريبة.\nد-يجري تقاص المبالغ المقتطعة الموردة للدائرة وفق أحكام هذه المادة والتي تعتبر دفعة على حساب الضريبة، من الضريبة المستحقة على المكلف عن الفترة الضريبية التي دفعت فيها أو عن أي فترة ضريبية لاحقة على أن لا تتجاوز أربع سنوات تلي الفترة الضريبية التي يتوجب فيها توريدها للدائرة.\nهـ-على الشخص الملزم بالاقتطاع وفق أحكام هذه المادة أن يورد المبالغ المقتطعة والمحصلة للدائرة خلال ثلاثين يوماً من تاريخ دفعها وفي حال التخلف عن الاقتطاع والتوريد وفق أحكام هذه المادة تُحصل منه وكأنها ضريبة مستحقة عليه اعتباراً من التاريخ المحدد لتوريدها.\nو-تصدر التعليمات التنفيذية اللازمة لتنظيم أحكام وإجراءات تطبيق هذه المادة.","title":"الاقتطاع من المصدر","memo":"⭐ (٥%) من أتعاب المهنيين (أطباء، محامون، مهندسون، مدققون، خبراء، وسطاء...) المدفوعة من شخص اعتباري مقيم لشخص مقيم\n⭐ فوائد الودائع: (٥%) للطبيعي و(٧%) للاعتباري، وتعتبر قطعية للطبيعي وللاعتباري غير المقيم؛ الجوائز واليانصيب فوق ألف دينار (١٥%) قطعية\n⭐ غير المقيم: يقتطع (١٠%) بتاريخ الاستحقاق أو الدفع أيهما أسبق\n⭐ التوريد خلال ثلاثين يوماً من الدفع؛ وتقاص المقتطع غير القطعي خلال أربع سنوات تلي فترة التوريد","qs":[{"q":"يقتطع الشخص الاعتباري المقيم من الأتعاب التي يدفعها لمحامٍ مقيم نسبة:","o":["(٥%)","(٧%)","(١٠%)","(١٥%)"],"a":0},{"q":"تقتطع البنوك من فوائد الودائع المدفوعة لشخص اعتباري نسبة:","o":["(٧%)","(٥%)","(١٠%)","(١٥%)"],"a":0},{"q":"يقتطع الشخص الذي يدفع دخلاً غير معفى لشخص غير مقيم من هذا الدخل نسبة:","o":["(١٠%) بتاريخ الاستحقاق أو الدفع أيهما أسبق","(١٠%) بتاريخ الدفع فقط","(٥%) بتاريخ الاستحقاق أو الدفع أيهما أسبق","(١٥%) بتاريخ تقديم الإقرار"],"a":0},{"q":"على الشخص الملزم بالاقتطاع أن يورد المبالغ المقتطعة للدائرة خلال:","o":["ثلاثين يوماً من تاريخ دفعها","خمسة عشر يوماً من تاريخ دفعها","تسعين يوماً من تاريخ دفعها","نهاية الشهر الرابع من الفترة التالية"],"a":0}]},{"n":"13","chapter":"","notes":[],"source":"أ-تحتسب الضريبة المستحقة على المكلف على أساس السنة الميلادية.\nب-يجوز للمكلف الذي يغلق حساباته في موعد مختلف عن نهاية السنة الميلادية أن يحتسب الضريبة على أساس سنته المالية شريطة إشعار الدائرة المسبق بذلك.\nج-\n١-يحتسب المكلف الذي بدأ بممارسة نشاطه خلال النصف الأول من السنة الميلادية الضريبة عن الفترة الواقعة بين بداية ممارسة النشاط ونهاية السنة الميلادية.\n٢-يجوز للمكلف الذي بدأ بممارسة نشاطه خلال النصف الثاني من السنة الميلادية أن يحتسب الضريبة عن الفترة الواقعة بين بداية ممارسة النشاط ونهاية السنة الميلادية التالية.\nد-للمدقق من تلقاء ذاته أو بناء على طلب المكلف أو من يمثله ووفقاً للتعليمات التنفيذية احتساب الضريبة على أي مكلف عند وفاته أو تصفيته أو فسخه أو شطبه أو انتهاء عمله أو كان على وشك مغادرة المملكة نهائياً قبل نهاية الفترة الضريبية وتقدير الضريبة المستحقة عليه وتدقيقها خلال عشرة أيام من تاريخ تبليغه مذكرة خطية بذلك.","title":"الفترة الضريبية","memo":"⭐ تحتسب الضريبة على أساس السنة الميلادية، ويجوز على أساس السنة المالية بشرط إشعار الدائرة المسبق\n⭐ من بدأ نشاطه في النصف الأول: حتى نهاية السنة الميلادية ذاتها؛ وفي النصف الثاني: يجوز حتى نهاية السنة الميلادية التالية\n⭐ عند الوفاة أو التصفية أو المغادرة النهائية: يقدر المدقق الضريبة خلال عشرة أيام من تبليغ المذكرة الخطية","qs":[{"q":"تُحتسب الضريبة المستحقة على المكلف أصلاً على أساس:","o":["السنة الميلادية","السنة المالية للمكلف","السنة الهجرية","الفترة التي يحددها المدير"],"a":0},{"q":"حالة عملية: بدأ مكلف ممارسة نشاطه في شهر أيلول. يجوز له أن يحتسب الضريبة عن الفترة من بداية النشاط حتى:","o":["نهاية السنة الميلادية التالية","نهاية السنة الميلادية ذاتها","انقضاء اثني عشر شهراً من بدء النشاط","نهاية الشهر الرابع من السنة التالية"],"a":0},{"q":"للمدقق احتساب الضريبة على المكلف الذي كان على وشك مغادرة المملكة نهائياً قبل نهاية الفترة الضريبية وتدقيقها خلال:","o":["عشرة أيام من تاريخ تبليغه مذكرة خطية","ثلاثين يوماً من تاريخ تبليغه مذكرة خطية","سبعة أيام من تاريخ المغادرة","تسعين يوماً من تاريخ تبليغه مذكرة خطية"],"a":0}]},{"n":"14","chapter":"","notes":[],"source":"أ-مع مراعاة أي نص آخر ورد في هذا القانون، يحتسب دخل المكلف لغايات الضريبة على أساس الاستحقاق المحاسبي.\nب-*يحق للشخص الطبيعي المتأتي دخله من المهنة أو الحرفة أن يحتسب الضريبة على الأساس النقدي وفقاً للتعليمات التنفيذية التي تصدر لهذه الغاية.\nج-للبنك أن يحتسب الضريبة على الفوائد والأرباح والعمولات المعلقة في سنة قبضها وذلك وفق التعليمات التنفيذية التي تصدر لهذه الغاية.","title":"أساس احتساب الدخل","memo":"⭐ الأصل احتساب الدخل على أساس الاستحقاق المحاسبي\n⭐ يحق للشخص الطبيعي المتأتي دخله من المهنة أو الحرفة الاحتساب على الأساس النقدي\n⭐ للبنك احتساب الضريبة على الفوائد والأرباح والعمولات المعلقة في سنة قبضها","qs":[{"q":"يُحتسب دخل المكلف لغايات الضريبة كقاعدة عامة على أساس:","o":["الاستحقاق المحاسبي","الأساس النقدي","الأساس المختلط","التقدير الإداري"],"a":0},{"q":"يحق الاحتساب على الأساس النقدي وفق التعليمات التنفيذية لـ:","o":["الشخص الطبيعي المتأتي دخله من المهنة أو الحرفة","البنوك","شركات التأمين","جميع الأشخاص الاعتباريين"],"a":0},{"q":"للبنك أن يحتسب الضريبة على الفوائد والعمولات المعلقة في:","o":["سنة قبضها","سنة استحقاقها","سنة تعليقها","السنة التي يحددها البنك المركزي"],"a":0}]},{"n":"15","chapter":"","notes":[],"source":"أ-يتم احتساب الدخل والمصروفات القابلة للتنزيل بالنسبة للمكلفين الذين يستخدمون أساس الاستحقاق المحاسبي والمتعلقة بالعقود طويلة المدى باعتماد نسبة الإنجاز الفعلي للعقد خلال الفترة الضريبية وفق الأحكام والإجراءات التي تحددها التعليمات التنفيذية.\nب-لغايات الفقرة (أ) من هذه المادة، تعني العقود طويلة المدى عقود التصنيع أو التركيب أو البناء أو تقديم الخدمات المتعلقة بها التي لا تنجز خلال الفترة الضريبية الواحدة وتمت المباشرة بتنفيذ العقد خلالها، ولا يشمل ذلك العقود التي تنجز خلال ستة أشهر من بداية تنفيذ العقد.","title":"العقود طويلة المدى","memo":"⭐ يحتسب دخل ومصروفات العقود طويلة المدى (لمن يستخدم أساس الاستحقاق) بنسبة الإنجاز الفعلي خلال الفترة\n⭐ العقود طويلة المدى: تصنيع أو تركيب أو بناء أو خدمات متعلقة لا تنجز في فترة ضريبية واحدة، ولا يشمل ما ينجز خلال ستة أشهر من بدء التنفيذ","qs":[{"q":"يُحتسب الدخل المتعلق بالعقود طويلة المدى للمكلف الذي يستخدم أساس الاستحقاق باعتماد:","o":["نسبة الإنجاز الفعلي للعقد خلال الفترة الضريبية","العقد المنجز عند تسليمه","المبالغ المقبوضة فعلاً خلال الفترة","قيمة العقد مقسومة على مدته"],"a":0},{"q":"لا تُعد من العقود طويلة المدى العقود التي تنجز خلال:","o":["ستة أشهر من بداية تنفيذ العقد","سنة من بداية تنفيذ العقد","ثلاثة أشهر من توقيع العقد","تسعة أشهر من بداية تنفيذ العقد"],"a":0}]},{"n":"16","chapter":"","notes":[],"source":"لغايات هذا القانون، يُعامل المستأجر تمويلياً بما في ذلك المستأجر المنتهي إيجاره بالتملك على أنه مالك المال وفق الأحكام والإجراءات التي تحددها التعليمات التنفيذية وتعتبر دفعات الإيجار التي يؤديها بمثابة أقساط قرض أو أقساط تأجير منته بالتملك حسب مقتضى الحال.","title":"التأجير التمويلي","memo":"⭐ يعامل المستأجر تمويلياً (بما فيه المنتهي بالتملك) على أنه مالك المال\n⭐ دفعات الإيجار تعتبر أقساط قرض أو أقساط تأجير منته بالتملك حسب مقتضى الحال","qs":[{"q":"يُعامل المستأجر تمويلياً لغايات قانون ضريبة الدخل على أنه:","o":["مالك المال","مستأجر تشغيلي","وكيل عن المؤجر","مقترض لا يملك المال"],"a":0},{"q":"تُعتبر دفعات الإيجار التي يؤديها المستأجر تمويلياً بمثابة:","o":["أقساط قرض أو أقساط تأجير منته بالتملك","مصروف إيجار ينزل بالكامل في فترة دفعه","دخل خاضع للضريبة للمستأجر","أرباح رأسمالية للمؤجر"],"a":0}]},{"n":"17","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-يلتزم كل شخص له مصدر دخل أو أكثر خاضع للضريبة بتقديم الإقرار الضريبي وفق النموذج المعتمد لدى الدائرة حتى نهاية الشهر الرابع التالي لانتهاء الفترة الضريبية.\nب-يلتزم الورثة أو من يمثلهم بتقديم إقرار ضريبي عن المتوفى خلال تسعين يوماً من تاريخ الوفاة.\nج-يلتزم الولي والوصي والقيم والمصفي ووكيل التفليسة بتقديم الإقرار الضريبي عمن يمثله.\nد-يجوز للأزواج ممن لهم مصادر دخل خاضعة للضريبة أن يقدموا إقراراً ضريبياً مشتركاً بموافقتهم.\nهـ-يتم إعفاء فئات معينة من تقديم الإقرارات الضريبية وفق نظام يصدر لهذه الغاية.","title":"تقديم الإقرار الضريبي","memo":"⭐ يقدم الإقرار حتى نهاية الشهر الرابع التالي لانتهاء الفترة الضريبية\n⭐ الورثة يقدمون إقرار المتوفى خلال تسعين يوماً من الوفاة؛ ويقدم الولي والوصي والقيم والمصفي ووكيل التفليسة الإقرار عمن يمثلونه\n⭐ للأزواج تقديم إقرار مشترك بموافقتهم؛ وتعفى فئات معينة من تقديم الإقرار بنظام","qs":[{"q":"يلتزم المكلف بتقديم الإقرار الضريبي حتى:","o":["نهاية الشهر الرابع التالي لانتهاء الفترة الضريبية","نهاية الشهر الثالث التالي لانتهاء الفترة الضريبية","نهاية الشهر السادس التالي لانتهاء الفترة الضريبية","ثلاثين يوماً من انتهاء الفترة الضريبية"],"a":0},{"q":"يلتزم الورثة أو من يمثلهم بتقديم إقرار ضريبي عن المتوفى خلال:","o":["تسعين يوماً من تاريخ الوفاة","ثلاثين يوماً من تاريخ الوفاة","ستين يوماً من تاريخ الوفاة","سنة من تاريخ الوفاة"],"a":0},{"q":"يجوز للأزواج ممن لهم مصادر دخل خاضعة للضريبة أن يقدموا إقراراً ضريبياً مشتركاً:","o":["بموافقتهم","بموافقة المدير","بقرار من المدقق","إذا لم يتجاوز دخلهما مليون دينار"],"a":0}]},{"n":"18","chapter":"","notes":[],"source":"أ-مع مراعاة أي مواعيد أخرى نص عليها هذا القانون، يلتزم المكلف بدفع رصيد الضريبة المستحقة قبل نهاية الشهر الرابع من الفترة التالية من الفترة الضريبية.\nب-للتوصل إلى رصيد الضريبة المستحقة يجري تقاص ما نسبته (١٠٠%) من ضريبة الأبنية والأراضي داخل مناطق أمانة عمان والبلديات التي يدفعها المكلف في أي سنة عن العقارات المؤجرة التي تأتى له منها دخل من ضريبة الدخل المستحقة عليه بمقتضى أحكام هذا القانون، على أن لا يتجاوز التقاص المسموح به مقدار الضريبة المستحقة على هذا الدخل عن تلك السنة ومع مراعاة نسبة هذا الدخل إلى الدخل الإجمالي للمكلف.","title":"دفع رصيد الضريبة وتقاص ضريبة الأبنية","memo":"⭐ يدفع رصيد الضريبة المستحقة قبل نهاية الشهر الرابع من الفترة التالية\n⭐ يقاص (١٠٠%) من ضريبة الأبنية والأراضي عن العقارات المؤجرة، بما لا يتجاوز ضريبة الدخل المستحقة على هذا الدخل عن تلك السنة","qs":[{"q":"يلتزم المكلف بدفع رصيد الضريبة المستحقة:","o":["قبل نهاية الشهر الرابع من الفترة التالية للفترة الضريبية","قبل نهاية الشهر الثالث من الفترة التالية للفترة الضريبية","خلال ثلاثين يوماً من انتهاء الفترة الضريبية","عند صدور قرار التدقيق"],"a":0},{"q":"يجري تقاص ضريبة الأبنية والأراضي التي يدفعها المكلف عن عقاراته المؤجرة من ضريبة الدخل بنسبة:","o":["(١٠٠%)","(٥٠%)","(٢٥%)","(٧٥%)"],"a":0},{"q":"لا يجوز أن يتجاوز تقاص ضريبة الأبنية والأراضي عن العقارات المؤجرة:","o":["مقدار ضريبة الدخل المستحقة على دخل تلك العقارات عن تلك السنة","مقدار ضريبة الدخل المستحقة على كامل دخل المكلف","(٢٥%) من الدخل الخاضع للضريبة","ألف دينار سنوياً"],"a":0}]},{"n":"19","chapter":"","notes":[],"source":"أ-يُلزم المستورد بأن يدفع على حساب الضريبة ما نسبته (٢%) من قيمة مستورداته على أن تستوفيها دائرة الجمارك وتوردها للدائرة، ولمجلس الوزراء بناء على تنسيب الوزير استثناء أنواع معينة من المستوردات أو فئات معينة من المكلفين من أحكام هذه الفقرة.\nب-يُلزم المكلف الذي يمارس أنشطة أعمال وتجاوز دخله الإجمالي من هذه الأنشطة في الفترة الضريبية السابقة (١,٠٠٠,٠٠٠) مليون دينار بتوريد الدفعات المقدمة الواردة في الفقرة (ج) من هذه المادة على حساب الضريبة المستحقة على الدخل المتأتي من تلك الأنشطة وفق المواعيد التالية ما لم تحدد التعليمات التنفيذية مدة أطول:\n١-عن الفترة التي تغطي النصف الأول من الفترة الضريبية خلال مدة لا تتجاوز ثلاثين يوماً من تاريخ انتهاء النصف الأول لتلك الفترة.\n٢-عن الفترة التي تغطي النصف الثاني من الفترة الضريبية خلال مدة لا تتجاوز ثلاثين يوماً من تاريخ انتهاء تلك الفترة.\nج-تحدد قيمة الدفعات المقدمة لغايات الفقرة (ب) من هذه المادة بما يعادل (٤٠%) من الضريبة المحتسبة استناداً إلى البيانات المالية المقدمة للدائرة عن الفترة المعنية، وفي حال عدم وجود بيانات مالية لتلك الفترة يتم اعتماد الضريبة الواردة في الإقرار الضريبي للفترة الضريبية السابقة مباشرة.\nد-يخصم المكلف ما تم دفعه على حساب الضريبة وفق أحكام الفقرة (أ) من هذه المادة من الدفعة المستحقة عليه وفق أحكام الفقرة (ب) منها.\nهـ-يجري تقاص المبالغ المدفوعة وفق أحكام الفقرة (أ) من هذه المادة من الضريبة المستحقة على المكلف عن الفترة الضريبية التي دفعت فيها أو عن أي فترة ضريبية لاحقة على أن لا تتجاوز أربع سنوات تلي الفترة الضريبية التي يتوجب فيها الدفع.","title":"الدفعات المقدمة على حساب الضريبة","memo":"⭐ المستورد يدفع (٢%) من قيمة مستورداته تستوفيها دائرة الجمارك؛ ولمجلس الوزراء بتنسيب الوزير استثناء مستوردات أو فئات\n⭐ الدفعات المقدمة على من تجاوز دخله الإجمالي من الأعمال (١,٠٠٠,٠٠٠) دينار في الفترة السابقة: نصف أول ونصف ثانٍ، كل منها خلال ثلاثين يوماً من انتهاء النصف\n⭐ قيمة الدفعة (٤٠%) من الضريبة المحتسبة؛ ويخصم منها المدفوع على المستوردات؛ والتقاص خلال أربع سنوات","qs":[{"q":"يُلزم المستورد بأن يدفع على حساب الضريبة نسبة من قيمة مستورداته تستوفيها دائرة الجمارك مقدارها:","o":["(٢%)","(١%)","(٥%)","(٤%)"],"a":0},{"q":"يُلزم بتوريد الدفعات المقدمة المكلف الذي يمارس أنشطة أعمال وتجاوز دخله الإجمالي منها في الفترة الضريبية السابقة:","o":["مليون دينار","خمسمائة ألف دينار","مائتي ألف دينار","مائة وخمسين ألف دينار"],"a":0},{"q":"تُحدد قيمة الدفعة المقدمة بما يعادل من الضريبة المحتسبة استناداً إلى البيانات المالية المقدمة عن الفترة المعنية نسبة:","o":["(٤٠%)","(٥٠%)","(٢٥%)","(٣٠%)"],"a":0},{"q":"تُورد الدفعة المقدمة عن النصف الأول من الفترة الضريبية خلال مدة لا تتجاوز:","o":["ثلاثين يوماً من تاريخ انتهاء النصف الأول","تسعين يوماً من تاريخ انتهاء النصف الأول","خمسة عشر يوماً من تاريخ انتهاء النصف الأول","نهاية الشهر الرابع من الفترة التالية"],"a":0}]},{"n":"20","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-لغايات هذه المادة، تعني عبارة (معاملة التصرف) وقف الأموال أو هبتها أو إجراء أي اتفاق أو ترتيب بشأن ريعها أو انتقال ملكيتها.\nب-إذا نشأ دخل من معاملة التصرف التي أجراها المكلف لصالح أي ممن يعيلهم ممن لم يكمل الثامنة عشرة من عمره عند بدء الفترة الضريبية التي تحقق فيها الدخل، يعتبر هذا الدخل لأغراض هذا القانون دخلاً للشخص الذي أجرى معاملة التصرف.\nج-إذا نشأ دخل من معاملة تصرف يصح الرجوع عنها فيبقى هذا الدخل دخلاً للشخص الذي أجرى معاملة التصرف وتعتبر معاملة التصرف معاملة يصح الرجوع عنها إذا تضمنت نصاً يمكّن من تحويل الدخل أو إعادة تحويله إلى الشخص الذي أجرى معاملة التصرف أو إذا مُكّن من السيطرة على الدخل أو الموجودات التي يتأتى منها الدخل بصورة مباشرة أو غير مباشرة.\nد-لغايات المعاملات الجارية بين الأشخاص المعنيين من ذوي العلاقة، تقوم الدائرة بالتحقق مما إذا كان أي شرط أو حكم وارد ضمن أي معاملة أو اتفاق أو ترتيب مختلفاً عن الشروط والأحكام والتي كان من الممكن الاتفاق عليها لو كان الأطراف في المعاملة مستقلين، ويُعدل الدخل والضريبة للأشخاص ذوي العلاقة ليعكس أي فرق في السعر بين ما تم استيفاؤه بين الأشخاص المعنيين وبين ما يتم استيفاؤه بين الأطراف المستقلين وأي ضريبة إضافية وفقا للمعايير الدولية.\nهـ-على الرغم مما ورد في الفقرة (د) من هذه المادة، يتم تجاهل المعاملات المصطنعة أو الوهمية التي لم تجر لأغراض نشاط الأعمال، وإنما جرت بغرض تخفيض الضريبة المستحقة أو نقل العبء الضريبي بشكل يخالف أحكام هذا القانون أو اتفاقات تجنب الازدواج الضريبي ومنع التهرب من الضرائب أو الاتفاقيات الدولية، ويتم تقدير الضريبة كأن لم تكن تلك المعاملة.\nو-لا يعتد بأي معاملة تصرف وهمية أو مصطنعة وتقدر الضريبة المستحقة على المكلف المعني كأنها لم تكن.","title":"معاملات التصرف وذوي العلاقة","memo":"⭐ معاملة التصرف: وقف الأموال أو هبتها أو أي اتفاق بشأن ريعها أو انتقال ملكيتها\n⭐ دخل التصرف لصالح معال لم يكمل الثامنة عشرة، ودخل التصرف القابل للرجوع، يبقى دخلاً لمن أجرى التصرف\n⭐ معاملات ذوي العلاقة تعدّل وفق سعر الأطراف المستقلين؛ والمعاملات الوهمية أو المصطنعة يتم تجاهلها وتقدر الضريبة كأنها لم تكن","qs":[{"q":"إذا نشأ دخل من معاملة تصرف أجراها المكلف لصالح أحد من يعيلهم ممن لم يكمل من عمره عند بدء الفترة الضريبية:","o":["الثامنة عشرة، فيعتبر الدخل دخلاً لمن أجرى التصرف","الحادية والعشرين، فيعتبر الدخل دخلاً لمن أجرى التصرف","الثامنة عشرة، فيعتبر الدخل دخلاً للمعال","السادسة عشرة، فيعتبر الدخل معفى"],"a":0},{"q":"إذا نشأ دخل من معاملة تصرف يصح الرجوع عنها فإن هذا الدخل:","o":["يبقى دخلاً للشخص الذي أجرى معاملة التصرف","يعتبر دخلاً للمتصرف إليه","يعتبر دخلاً معفى من الضريبة","يقسم مناصفة بين الطرفين"],"a":0},{"q":"يُعدّل الدخل والضريبة للأشخاص ذوي العلاقة ليعكس الفرق في السعر بين ما استوفي بينهم وبين:","o":["ما يتم استيفاؤه بين الأطراف المستقلين","سعر التكلفة لدى البائع","السعر الذي يحدده المدير بقرار","القيمة الدفترية للمال"],"a":0},{"q":"المعاملات المصطنعة أو الوهمية التي جرت بغرض تخفيض الضريبة المستحقة:","o":["يتم تجاهلها وتقدر الضريبة كأن لم تكن","تعتبر صحيحة إلى أن تبطلها المحكمة","يعاد تسعيرها وفق سعر الأطراف المستقلين فقط","تفرض عليها ضريبة مقطوعة"],"a":0}]},{"n":"21","chapter":"","notes":[],"source":"لغايات هذا القانون، يُعتبر المدير مدققاً ويمارس الصلاحيات التالية:\nأ-\n١-تشكيل لجنة لا تقل عن خمسة من شاغلي الوظائف القيادية في الدائرة لتعيين أي من موظفيها الحاصلين على الشهادة الجامعية الأولى حداً أدنى بموافقة المدير لتدقيق الإقرارات الضريبية وتقدير الضريبة واحتساب أي مبالغ أخرى مترتبة على المكلف والقيام بأي مهام وواجبات أخرى منوطة به وفق أحكام هذا القانون.\n٢-يتم تحديد شروط وأحكام التعيين والتخصصات الجامعية اللازمة لذلك بموجب تعليمات يصدرها المدير لهذه الغاية.\nب-تأليف لجنة من ثلاثة مدققين للقيام بأعمال التدقيق أو التقدير وللبت في أي مسائل يحيلها المدير إليها إذا رأى أن مصلحة العمل تقتضي ذلك وتصدر اللجنة قرارها بالأكثرية ويعتبر القرار الصادر عن اللجنة قراراً صادراً عن المدقق بمقتضى أحكام هذا القانون.\nج-اعتماد نماذج الإقرارات الضريبية والإشعارات والمذكرات وأي نماذج أخرى يراها ضرورية لتنفيذ أحكام هذا القانون.\nد-اتخاذ ما يراه مناسباً من قرارات وإجراءات لتنفيذ أحكام هذا القانون والأنظمة والتعليمات التنفيذية والتعليمات الصادرة بمقتضاه.","title":"صلاحيات المدير","memo":"⭐ يعتبر المدير مدققاً\n⭐ تعيين المدققين بلجنة لا تقل عن خمسة من شاغلي الوظائف القيادية وبموافقة المدير، والحد الأدنى الشهادة الجامعية الأولى\n⭐ للمدير تأليف لجنة من ثلاثة مدققين تقرر بالأكثرية، ويعتبر قرارها قراراً صادراً عن المدقق","qs":[{"q":"لغايات قانون ضريبة الدخل يُعتبر المدير:","o":["مدققاً","عضواً في هيئة الاعتراض","مدعياً عاماً ضريبياً","محاسباً قانونياً"],"a":0},{"q":"تُشكل اللجنة التي تتولى تعيين موظفي الدائرة لتدقيق الإقرارات من عدد من شاغلي الوظائف القيادية لا يقل عن:","o":["خمسة","ثلاثة","سبعة","ستة"],"a":0},{"q":"تصدر لجنة المدققين الثلاثة التي يؤلفها المدير قرارها:","o":["بالأكثرية ويعتبر قراراً صادراً عن المدقق","بالإجماع ويعتبر قراراً صادراً عن المدير","بالأكثرية ويخضع لمصادقة الوزير","بالإجماع ويعتبر قراراً صادراً عن هيئة الاعتراض"],"a":0}]},{"n":"22","chapter":"","notes":[],"source":"يلتزم الشخص المقيم الذي يخضع دخله للضريبة وفق أحكام المادة (٣) من هذا القانون بالتسجيل لدى الدائرة والحصول على رقم ضريبي قبل البدء بممارسة عمله أو نشاطه على أن تحدد التعليمات التنفيذية شروط التسجيل وجميع الإجراءات اللازمة له.","title":"التسجيل والرقم الضريبي","memo":"⭐ يلتزم الشخص المقيم الخاضع دخله للضريبة بالتسجيل لدى الدائرة والحصول على رقم ضريبي قبل البدء بممارسة عمله\n⭐ شروط التسجيل وإجراءاته تحددها التعليمات التنفيذية","qs":[{"q":"يلتزم الشخص المقيم الذي يخضع دخله للضريبة بالتسجيل لدى الدائرة والحصول على رقم ضريبي:","o":["قبل البدء بممارسة عمله أو نشاطه","خلال ثلاثين يوماً من بدء نشاطه","عند تقديم أول إقرار ضريبي","خلال ستة أشهر من بدء نشاطه"],"a":0},{"q":"تُحدد شروط التسجيل لدى الدائرة وجميع الإجراءات اللازمة له بموجب:","o":["التعليمات التنفيذية","نظام يصدره مجلس الوزراء","قرار من الوزير","قانون الشركات"],"a":0}]},{"n":"23","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-يلتزم المكلف بتنظيم السجلات والمستندات والبيانات المالية اللازمة لتحديد مقدار الضريبة المستحقة عليه شريطة أن تكون معدة وفق معايير المحاسبة الدولية ومدققة ومصادقاً عليها من محاسب قانوني وبالاحتفاظ بها لمدة أربع سنوات تبدأ من آخر أي من التواريخ التالية:\n١-تاريخ انتهاء الفترة الضريبية التي تم تنظيم السجلات والمستندات فيها.\n٢-تاريخ تقديم الإقرار الضريبي.\n٣-تاريخ تبليغ الإشعار بنتيجة قرار التقدير الإداري.\nب-يلتزم المكلف في حال وجود نزاع على مقدار الضريبة المستحقة أو على أي غرامات ومبالغ متعلقة بها بالاحتفاظ بالسجلات والمستندات إلى حين البت في النزاع أو صدور قرار قطعي من المحكمة وفي جميع الأحوال يجب أن لا تقل مدة الاحتفاظ عن المدة المحددة في الفقرة (أ) من هذه المادة.\nج-يجوز للمكلف أن ينظم ويمسك سجلاته ومستنداته باللغة الانجليزية على أن يقدم ترجمة عربية لها إذا طلبت الدائرة ذلك.\nد-تستثنى فئات معينة من المكلفين من تنظيم السجلات والمستندات والبيانات المالية المدققة كلياً أو جزئياً وفق الشروط والإجراءات المحددة في نظام يصدر لهذه الغاية على أن لا يشمل هذا النظام الأشخاص العاملين في مجال الاستشارات الطبية والهندسية والقانونية.\nهـ-في حال عدم تنظيم المكلف للسجلات والمستندات وفق الأصول، يحدد النظام الأرباح القائمة أو الصافية أو نسبة أي منها للبضائع أو السلع أو الخدمات التي تتعامل بها القطاعات التجارية والصناعية والخدمية.\nو-يلتزم الشخص بإصدار فاتورة أصولية لقاء تقديم أي خدمة أو بيع أي سلعة في المملكة ويتم تنظيم جميع الشؤون المتعلقة بأنظمة الفوترة وإصدارها والرقابة عليها والفئات المستثناة منها بمقتضى نظام يصدر لهذه الغاية.","title":"السجلات والمستندات والفوترة","memo":"⭐ سجلات وفق معايير المحاسبة الدولية مدققة من محاسب قانوني، تحفظ أربع سنوات من آخر: انتهاء الفترة، تقديم الإقرار، تبليغ قرار التقدير الإداري\n⭐ عند النزاع تحفظ حتى البت فيه أو صدور قرار قطعي، وبما لا يقل عن أربع سنوات\n⭐ يجوز مسكها بالإنجليزية مع ترجمة عربية عند الطلب؛ ونظام الاستثناء لا يشمل الاستشارات الطبية والهندسية والقانونية؛ وإصدار فاتورة أصولية إلزامي","qs":[{"q":"يلتزم المكلف بالاحتفاظ بالسجلات والمستندات والبيانات المالية لمدة:","o":["أربع سنوات تبدأ من آخر التواريخ المحددة في القانون","خمس سنوات تبدأ من تاريخ انتهاء الفترة الضريبية","سنتين تبدأ من تاريخ تقديم الإقرار","عشر سنوات تبدأ من تاريخ إنشاء السجلات"],"a":0},{"q":"يجوز للمكلف أن يمسك سجلاته ومستنداته باللغة الإنجليزية على أن:","o":["يقدم ترجمة عربية لها إذا طلبت الدائرة ذلك","يحصل على موافقة مسبقة من الوزير","تكون مصدقة من السفارة المختصة","يرفق ترجمة عربية مع كل إقرار"],"a":0},{"q":"لا يجوز أن يشمل النظام الذي يستثني فئات من تنظيم السجلات والبيانات المالية المدققة:","o":["العاملين في مجال الاستشارات الطبية والهندسية والقانونية","صغار التجار","أصحاب الحرف","المكلفين ذوي المبيعات المحدودة"],"a":0}]},{"n":"24","chapter":"","notes":[],"source":"للمكلف استخدام أجهزة الحاسوب في تنظيم سجلاته ومستنداته وبياناته المالية وتعتبر هذه السجلات والبيانات أصولية من الناحية المحاسبية إذا تم مراعاة ما يلي:\nأ-أن يحتفظ المكلف للمدة المقررة قانوناً بأصول المستندات والوثائق المعززة لها.\nب-أن يلتزم المكلف بأي شروط وإجراءات أخرى يحددها النظام الصادر لهذه الغاية.","title":"السجلات المحوسبة","memo":"⭐ تعتبر السجلات المحوسبة أصولية إذا احتفظ المكلف للمدة المقررة قانوناً بأصول المستندات المعززة لها\n⭐ والتزم بأي شروط وإجراءات أخرى يحددها النظام","qs":[{"q":"تُعتبر السجلات والبيانات المنظمة باستخدام الحاسوب أصولية إذا:","o":["احتفظ المكلف للمدة المقررة قانوناً بأصول المستندات والوثائق المعززة لها","صادق عليها المدير خطياً","طبعت ورقياً في نهاية كل شهر","سجل البرنامج المحاسبي لدى وزارة الاقتصاد الرقمي"],"a":0},{"q":"تُحدد الشروط والإجراءات الأخرى لاعتبار السجلات المحوسبة أصولية بموجب:","o":["النظام الصادر لهذه الغاية","تعليمات يصدرها المدقق","قرار من هيئة الاعتراض","معايير المحاسبة الدولية وحدها"],"a":0}]},{"n":"25","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"يترتب على الشخص المرخص له بمزاولة مهنة محاسب قانوني في المملكة أن يقدم للدائرة بياناً بأسماء عملائه وعناوينهم خلال مدة لا تتجاوز نهاية الشهر الثالث من السنة اللاحقة للسنة المالية.","title":"التزام المحاسب القانوني","memo":"⭐ يقدم المحاسب القانوني للدائرة بياناً بأسماء عملائه وعناوينهم خلال مدة لا تتجاوز نهاية الشهر الثالث من السنة اللاحقة للسنة المالية","qs":[{"q":"يلتزم المحاسب القانوني بتقديم بيان بأسماء عملائه وعناوينهم للدائرة خلال مدة لا تتجاوز:","o":["نهاية الشهر الثالث من السنة اللاحقة للسنة المالية","نهاية الشهر الرابع من السنة اللاحقة للسنة المالية","نهاية الشهر الأول من السنة اللاحقة للسنة المالية","ثلاثين يوماً من انتهاء السنة المالية"],"a":0},{"q":"يتضمن البيان الذي يقدمه المحاسب القانوني للدائرة:","o":["أسماء عملائه وعناوينهم","أرباح عملائه الصافية","قيمة أتعابه من كل عميل","البيانات المالية المدققة لعملائه"],"a":0}]},{"n":"26","chapter":"","notes":[],"source":"أ-يقدم الإقرار الضريبي إلى الدائرة من المكلف شخصياً أو من ينوب عنه أو بإحدى الوسائل التي توافق الدائرة على اعتمادها وفق الشروط والإجراءات التي يحددها النظام ومنها:\n١-البريد المسجل.\n٢-البنوك التي تعتمدها الدائرة.\n٣-أي شركة مرخصة للقيام بمهام مشغل البريد العام أو مشغل البريد الخاص يعتمدها مجلس الوزراء بناءً على تنسيب الوزير.\n٤-الوسائل الالكترونية.\nب-يعتبر تاريخ تقديم الإقرار الضريبي هو تاريخ تسلمه من الدائرة أو تاريخ ختم البريد أو تاريخ وصل الإيداع لدى البنك أو الشركة المرخصة المعتمدة أيها أسبق، وفي حال إرساله الكترونياً تحدد التعليمات التنفيذية التاريخ المعتمد لتقديمه.","title":"وسائل تقديم الإقرار وتاريخه","memo":"⭐ يقدم الإقرار شخصياً أو بالبريد المسجل أو البنوك المعتمدة أو شركة بريد مرخصة يعتمدها مجلس الوزراء بتنسيب الوزير أو الوسائل الالكترونية\n⭐ تاريخ التقديم: تاريخ التسلم أو ختم البريد أو وصل الإيداع أيها أسبق؛ والإلكتروني تحدده التعليمات التنفيذية","qs":[{"q":"يُعتبر تاريخ تقديم الإقرار الضريبي:","o":["تاريخ تسلمه من الدائرة أو ختم البريد أو وصل الإيداع أيها أسبق","تاريخ تسلمه من الدائرة فقط","تاريخ ختم البريد أو وصل الإيداع أيها أبعد","تاريخ تسجيله في حاسوب الدائرة"],"a":0},{"q":"تُعتمد شركة البريد المرخصة لاستلام الإقرارات الضريبية من قبل:","o":["مجلس الوزراء بناءً على تنسيب الوزير","المدير بناءً على تنسيب المدقق","الوزير بناءً على تنسيب المدير","هيئة تنظيم قطاع الاتصالات"],"a":0},{"q":"يُحدد التاريخ المعتمد لتقديم الإقرار الضريبي المرسل إلكترونياً بموجب:","o":["التعليمات التنفيذية","نظام يصدر لهذه الغاية","قرار من الوزير","اتفاق بين المكلف والدائرة"],"a":0}]},{"n":"27","chapter":"","notes":[],"source":"يجوز للمكلف تعديل إقراره الضريبي المقدم للدائرة خلال سنتين من تاريخ تقديمه بزيادة الدخل أو الضريبة أو تخفيض أي منهما، وفي هذه الحال يُلزم المكلف بدفع الضريبة وغرامة التأخير إن وجدت، باستثناء الإقرار الضريبي الذي صدرت بشأنه مذكرة تدقيق أو قرار بالقبول وفق أحكام المادة (٢٨) من هذا القانون أو الإقرار الضريبي الذي سبقت الدائرة المكلف في اكتشاف خطأ فيه ولا يعتبر المكلف في هذه الحالة مرتكباً لمخالفة أو جرم.","title":"تعديل الإقرار الضريبي","memo":"⭐ يجوز للمكلف تعديل إقراره خلال سنتين من تاريخ تقديمه بزيادة أو تخفيض الدخل أو الضريبة، مع دفع الضريبة وغرامة التأخير إن وجدت\n⭐ لا يجوز التعديل إذا صدرت مذكرة تدقيق أو قرار بالقبول، أو سبقت الدائرة المكلف في اكتشاف الخطأ\n⭐ لا يعتبر المكلف المعدِّل مرتكباً لمخالفة أو جرم","qs":[{"q":"يجوز للمكلف تعديل إقراره الضريبي المقدم للدائرة خلال:","o":["سنتين من تاريخ تقديمه","سنة من تاريخ تقديمه","أربع سنوات من تاريخ تقديمه","ستة أشهر من تاريخ تقديمه"],"a":0},{"q":"لا يجوز للمكلف تعديل إقراره الضريبي في حالة:","o":["صدور مذكرة تدقيق بشأنه","تخفيض الدخل المصرح به","زيادة الضريبة المصرح بها","مرور سنة على تقديمه"],"a":0},{"q":"حالة عملية: عدّل مكلف إقراره ضمن المدة القانونية بزيادة الدخل قبل صدور مذكرة تدقيق. يترتب على ذلك:","o":["دفع الضريبة وغرامة التأخير إن وجدت دون اعتباره مرتكباً لمخالفة","اعتباره مرتكباً لجرم التهرب الضريبي","رفض التعديل لأنه يزيد الضريبة","إحالته إلى هيئة الاعتراض"],"a":0}]},{"n":"28","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-\n١-تختار لجنة الإقرارات الضريبية التي يشكلها الوزير من ستة موظفين من الدائرة بالإضافة إلى المدير الإقرارات الضريبية الخاضعة للتدقيق وفق أسس اختيار عينات سنوية.\n٢-تعتبر الإقرارات الضريبية السنوية للمكلفين الذين لم ترد إقراراتهم ضمن العينات المختارة للتدقيق وفق الأسس المنصوص عليها في البند (١) من الفقرة (أ) من هذه المادة مقبولة قانوناً ويُبلغون ذلك.\n٣-على المدير أو المدقق الذي يفوضه المدير خطياً إعادة النظر بالإقرارات الضريبية المقبولة قانوناً بموجب البند (٢) من هذه الفقرة واتخاذ القرار المناسب بشأنها خلال سنتين من تاريخ تقديم الإقرار أو الإقرار المعدل وفقاً لأحكام هذا القانون، إذا وجد أي من الحالتين التاليتين:\nأ.وجود خطأ في تطبيق القانون.\nب.إغفال القرار السابق لحقيقة أو واقعة أو لوجود مصدر دخل لم يعالج في حينه.\nب-باستثناء الحالات التي يقرر فيها المدير خطياً تمديد مدة التدقيق إذا توافرت لدى الدائرة أدلة أو بيانات أو معلومات تستوجب التمديد، فعلى المدقق إصدار قرار التدقيق بخصوص الإقرار الضريبي الوارد ضمن العينات المختارة خلال سنة من تاريخ إصدار مذكرة التدقيق، وبخلاف ذلك، تعتبر مقبولة حكماً، وإذا ظهرت للمدقق أسباب تستدعي عدم قبوله كلياً أو جزئياً يصدر مذكرة تدقيق يدعو فيها المكلف لحضور جلسة لمناقشته على أن تتضمن:\n١-تاريخ المذكرة.\n٢-اسم المكلف ورقمه الضريبي.\n٣-الفترة أو الفترات الضريبية التي يشملها التدقيق.\n٤-مكان التدقيق وتاريخه ووقت إجرائه.\n٥-اسم المدقق وتوقيعه.\nج-للمدقق إجراء التدقيق في مركز عمل المكلف أو أي مكان آخر يتعلق بعمله وله بموافقة المدير الخطية إجراء التدقيق خارج أوقات العمل الرسمي.\nد-تسري أحكام الفقرة (ب) من هذه المادة على الإقرارات الضريبية التي تقدم بعد نفاذ أحكام هذا القانون المعدل.","title":"اختيار الإقرارات للتدقيق","memo":"⭐ لجنة الإقرارات يشكلها الوزير من ستة موظفين إضافة إلى المدير، وتختار العينات وفق أسس سنوية\n⭐ الإقرارات غير المختارة تعتبر مقبولة قانوناً، ويعيد المدير النظر فيها خلال سنتين عند الخطأ في تطبيق القانون أو إغفال واقعة أو مصدر دخل\n⭐ قرار التدقيق للإقرار المختار خلال سنة من مذكرة التدقيق وإلا اعتبر مقبولاً حكماً (ما لم يمدد المدير خطياً)؛ والتدقيق خارج أوقات الدوام بموافقة المدير الخطية","qs":[{"q":"تتشكل لجنة الإقرارات الضريبية التي تختار الإقرارات الخاضعة للتدقيق بقرار من:","o":["الوزير، من ستة موظفين من الدائرة بالإضافة إلى المدير","المدير، من خمسة مدققين","الوزير، من ثلاثة مدققين بالإضافة إلى المدير","مجلس الوزراء، من سبعة موظفين"],"a":0},{"q":"يعيد المدير النظر في الإقرارات المقبولة قانوناً (غير المختارة ضمن العينات) خلال:","o":["سنتين من تاريخ تقديم الإقرار أو الإقرار المعدل","أربع سنوات من تاريخ تقديم الإقرار","سنة من تاريخ تقديم الإقرار","ثلاثين يوماً من تاريخ تبليغ القبول"],"a":0},{"q":"يحق للمدقق إجراء التدقيق خارج أوقات العمل الرسمي:","o":["بموافقة المدير الخطية","بموافقة المكلف الخطية","بقرار من الوزير","دون الحاجة إلى أي موافقة"],"a":0}]},{"n":"29","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-يلتزم المدقق بإصدار قرار التدقيق خلال سنتين من تاريخ إصدار مذكرة التدقيق على أن يتضمن البيانات التالية:\n١-اسم المكلف ورقمه الضريبي.\n٢-الفترة أو الفترات الضريبية.\n٣-الأسس التي تم الاستناد إليها في التدقيق.\n٤-نتيجة التدقيق.\n٥-تحديد مقدار الضريبة وأية مبالغ أخرى مترتبة عليه وفق أحكام هذا القانون.\nب-إذا لم يتضمن قرار التدقيق تعديلاً يقوم المدقق بقبول هذا الإقرار، أما إذا تضمن قرار التدقيق تعديلاً في الإقرار الضريبي فللمكلف بعد الاطلاع على مضمونه القيام بأي مما يلي:\n١-التوقيع بالموافقة على نتيجة القرار.\n٢-التوقيع بعدم الموافقة على نتيجة القرار ويعتبر امتناعه عن التوقيع أو تخلفه عن الحضور بمثابة عدم موافقة ويصدر المدقق قراره بتقدير الدخل الخاضع للضريبة والضريبة المستحقة عليه وذلك في ضوء المعلومات المتوفرة لديه والمذكرة المنصوص عليها في الفقرة (أ) من هذه المادة معللاً كل بند من بنود قراره على حدة ومبيناً الأسباب التي دعت لعدم الأخذ بوجهة نظر المكلف وإلا اعتبر هذا البند موافقاً عليه في مرحلة الاعتراض ويكون هذا القرار في هذه الحالة قابلاً للاعتراض لدى هيئة الاعتراض.\nج-في جميع الأحوال يتم تبليغ المكلف إشعاراً خطياً بنتيجة قرار التدقيق والأسباب المبررة له.\nد-على الرغم من أي نص آخر، لا يجوز للمدقق إصدار الإشعار الخطي بنتيجة قرار التدقيق بعد مرور أربع سنوات من تاريخ تقديم الإقرار الضريبي المقدم بعد نفاذ أحكام هذا القانون، أو من تاريخ تعديله حسب مقتضى الحال ما لم تكن هناك بينة على وجود حالات تهرب ضريبي وفي هذه الحالة تتم مضاعفة المدة المشار إليها في هذه الفقرة.","title":"قرار التدقيق","memo":"⭐ يصدر المدقق قرار التدقيق خلال سنتين من تاريخ مذكرة التدقيق متضمناً الاسم والرقم الضريبي والفترة والأسس والنتيجة ومقدار الضريبة\n⭐ امتناع المكلف عن التوقيع أو تخلفه عن الحضور يعتبر عدم موافقة، ويكون القرار قابلاً للاعتراض لدى هيئة الاعتراض\n⭐ لا يصدر الإشعار بعد أربع سنوات من تقديم الإقرار أو تعديله، وتضاعف المدة عند وجود بينة تهرب ضريبي","qs":[{"q":"يلتزم المدقق بإصدار قرار التدقيق وفق المادة (٢٩) خلال:","o":["سنتين من تاريخ إصدار مذكرة التدقيق","أربع سنوات من تاريخ إصدار مذكرة التدقيق","تسعين يوماً من تاريخ إصدار مذكرة التدقيق","سنتين من تاريخ تقديم الإقرار"],"a":0},{"q":"يُعتبر امتناع المكلف عن التوقيع على قرار التدقيق المتضمن تعديلاً أو تخلفه عن الحضور:","o":["بمثابة عدم موافقة","بمثابة موافقة ضمنية","سبباً لإلغاء القرار","سبباً لإحالته إلى النيابة العامة"],"a":0},{"q":"حالة عملية: قدّم مكلف إقراره، وتوافرت بينة على وجود تهرب ضريبي. لا يجوز للمدقق إصدار الإشعار الخطي بنتيجة قرار التدقيق بعد مرور:","o":["ثماني سنوات من تاريخ تقديم الإقرار","أربع سنوات من تاريخ تقديم الإقرار","ست سنوات من تاريخ تقديم الإقرار","عشر سنوات من تاريخ تقديم الإقرار"],"a":0}]},{"n":"30","chapter":"","notes":[],"source":"أ-إذا تخلف المكلف عن تقديم الإقرار الضريبي خلال المدة المحددة في هذا القانون، تقوم الدائرة بإصدار قرار تقدير أولي تحدد فيه قيمة الضريبة المقدرة على المكلف عن الفترة أو الفترات الضريبية المعنية وأي غرامات ومبالغ أخرى متحققة عليه ويبلغ المكلف إشعاراً خطياً بنتيجة ذلك القرار.\nب-تكون المبالغ المطالب بها بموجب الإشعار المنصوص عليه في الفقرة (أ) من هذه المادة واجبة التحصيل بعد مرور ثلاثين يوماً من تاريخ تبليغه للمكلف ويعتبر أي مبلغ محصل منها دفعة على حساب الضريبة النهائية المستحقة عليه ولا يعتبر هذا القرار نهائياً لغايات الاعتراض أو الطعن القضائي.\nج-يعتبر قرار التقدير الأولي ملغى حكماً إذا قدم المكلف الإقرار الضريبي عن الفترة أو الفترات الضريبية المعنية ودفع الضريبة وأي غرامات أو مبالغ أخرى مترتبة عليه بموجب ذلك الإقرار على أن يتم ذلك قبل صدور قرار التقدير الإداري وفق أحكام المادة (٣١) من هذا القانون.\nد-لغايات هذه المادة، يصدر المدير تعليمات لتحديد أسس التقدير الأولي وإجراءاته.","title":"قرار التقدير الأولي","memo":"⭐ عند التخلف عن تقديم الإقرار تصدر الدائرة قرار تقدير أولي وتبلغ المكلف إشعاراً خطياً\n⭐ المبالغ واجبة التحصيل بعد ثلاثين يوماً من التبليغ وتعتبر دفعة على الحساب، والقرار غير نهائي لغايات الاعتراض أو الطعن\n⭐ يلغى حكماً إذا قدم المكلف الإقرار ودفع ما عليه قبل صدور قرار التقدير الإداري؛ وأسسه بتعليمات المدير","qs":[{"q":"تُصدر الدائرة قرار التقدير الأولي في حالة:","o":["تخلف المكلف عن تقديم الإقرار الضريبي خلال المدة المحددة","عدم موافقة المكلف على قرار التدقيق","رفض هيئة الاعتراض لاعتراض المكلف","طلب المكلف تقسيط الضريبة"],"a":0},{"q":"تكون المبالغ المطالب بها بموجب إشعار قرار التقدير الأولي واجبة التحصيل بعد مرور:","o":["ثلاثين يوماً من تاريخ تبليغه للمكلف","عشرة أيام من تاريخ تبليغه للمكلف","تسعين يوماً من تاريخ تبليغه للمكلف","ستين يوماً من تاريخ صدوره"],"a":0},{"q":"يُعتبر قرار التقدير الأولي ملغى حكماً إذا قدم المكلف الإقرار ودفع الضريبة والمبالغ المترتبة بموجبه:","o":["قبل صدور قرار التقدير الإداري","قبل انقضاء سنة على صدوره","خلال عشرة أيام من تبليغه","قبل صدور قرار هيئة الاعتراض"],"a":0}]},{"n":"31","chapter":"","notes":[],"source":"أ-إذا لم يقدم المكلف إقراراً ضريبياً بعد مرور ثلاثين يوماً من تاريخ تبلغه الإشعار الخطي بنتيجة قرار التقدير الأولي فيجوز للمدقق إصدار قرار تقدير إداري بالاستعانة بأي من مصادر المعلومات التي تحددها التعليمات التنفيذية.\nب-للمدير أو المدقق بناء على طلب خطي من المكلف إصدار قرار تقدير إداري وفق أحكام الفقرة (أ) من هذه المادة دون إصدار قرار تقدير أولي بموجب أحكام المادة (٣٠) من هذا القانون وفق تعليمات يصدرها المدير لهذه الغاية.\nج-يتم تبليغ المكلف إشعاراً خطياً بنتيجة قرار التقدير الإداري ويكون هذا القرار قابلاً للاعتراض لدى هيئة الاعتراض.\nد-يعتبر قرار التقدير الأولي ملغى حكماً بصدور قرار التقدير الإداري.","title":"قرار التقدير الإداري","memo":"⭐ إذا لم يقدم المكلف إقراره بعد ثلاثين يوماً من تبلغ إشعار التقدير الأولي يجوز للمدقق إصدار قرار تقدير إداري\n⭐ يجوز إصداره مباشرة دون تقدير أولي بناء على طلب خطي من المكلف\n⭐ قرار التقدير الإداري قابل للاعتراض لدى هيئة الاعتراض، ويلغي التقدير الأولي حكماً","qs":[{"q":"يجوز للمدقق إصدار قرار تقدير إداري إذا لم يقدم المكلف إقراراً ضريبياً بعد مرور:","o":["ثلاثين يوماً من تاريخ تبلغه إشعار قرار التقدير الأولي","تسعين يوماً من تاريخ تبلغه إشعار قرار التقدير الأولي","سنة من انتهاء الفترة الضريبية","عشرة أيام من تاريخ تبلغه إشعار قرار التقدير الأولي"],"a":0},{"q":"يكون قرار التقدير الإداري قابلاً للاعتراض لدى:","o":["هيئة الاعتراض","محكمة البداية الضريبية مباشرة","الوزير","لجنة الإقرارات الضريبية"],"a":0},{"q":"يجوز إصدار قرار تقدير إداري دون إصدار قرار تقدير أولي:","o":["بناءً على طلب خطي من المكلف","بقرار من الوزير","إذا تجاوزت الضريبة خمسة آلاف دينار","إذا كان المكلف غير مقيم"],"a":0}]},{"n":"32","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-في الحالات التي لا يزيد فيها مقدار الضريبة النهائية المقدرة على أي شخص طبيعي في أي سنة من السنوات على ألف دينار، يجوز للمدير أن يعتبر تلك الضريبة ضريبة أساسية مقطوعة عن كل سنة من السنوات التالية لتلك السنة على أن لا تزيد على خمس سنوات وعلى الشخص المذكور دفع الضريبة المقطوعة خلال ثلاثين يوماً من انقضاء كل سنة من السنوات التي تسري عليها تلك الضريبة.\nب-على الرغم مما ورد في أي نص مخالف يجوز للمدير أن يصدر قراراً يفرض بموجبه ضريبة دخل سنوية مقطوعة على الشخص الطبيعي الذي يقل دخله بالإجمالي عن مائة ألف دينار، ويحدد في القرار أنواع الدخول التي يفرض عليها تلك الضريبة والسنوات التي تسري خلالها، وللمدير تفويض صلاحياته هذه خطياً للمدقق.\nج-للمدير أن يصدر قراراً يفرض بموجبه ضريبة مقطوعة من قيمة مبيعات أو إيرادات أي شخص لا تزيد مبيعاته أو إيراداته على (١٥٠,٠٠٠) دينار وبما لا يقل عن نسبة (١%) من مقدار مبيعاته أو إيراداته في الفترة الضريبية إلا إذا رغب المكلف خلاف ذلك شريطة تقديم بيانات مالية وفق أحكام هذا القانون ويخضع قرار المدير المنصوص عليه في هذه الفقرة من هذه المادة لمصادقة الوزير.\nد-لأي شخص ينطبق عليه قرار الضريبة الأساسية المقطوعة بمقتضى أحكام الفقرات (أ) و(ب) و(ج) من هذه المادة أن يطلب من المدير إعادة النظر في القرار شريطة تقديم طلب خلال ثلاثين يوماً من انقضاء السنة التي تسري تلك الضريبة عليها أو من تاريخ تبليغه إشعار التقدير وللمدير أن يخفض الضريبة أو يلغيها وفي حال إلغائها يتم تقدير الضريبة وفقاً لأحكام هذا القانون.\nهـ-للمدير إلغاء أي من القرارات الصادرة استناداً لأحكام الفقرات (أ) و(ب) و(ج) من هذه المادة وأن يسري هذا القرار على السنوات اللاحقة لصدوره مع عدم الإخلال بأحكام المادة (٣٤) من هذا القانون.\nو-يعتبر القرار الصادر من المدير وفقاً لأحكام هذه المادة قابلاً للطعن لدى محكمة البداية الضريبية.\nز-تحدد شروط وأحكام وإجراءات تطبيق هذه المادة بمقتضى تعليمات تنفيذية تصدر لهذه الغاية.","title":"الضريبة المقطوعة","memo":"⭐ إذا لم تزد الضريبة النهائية لشخص طبيعي على ألف دينار يجوز اعتبارها مقطوعة لسنوات لا تزيد على خمس، تدفع خلال ثلاثين يوماً من انقضاء كل سنة\n⭐ للمدير فرض ضريبة سنوية مقطوعة على الشخص الطبيعي الذي يقل دخله الإجمالي عن مائة ألف دينار\n⭐ ضريبة مقطوعة على من لا تزيد مبيعاته على (١٥٠,٠٠٠) دينار بما لا يقل عن (١%) منها، بمصادقة الوزير\n⭐ طلب إعادة النظر خلال ثلاثين يوماً؛ وقرار المدير قابل للطعن لدى محكمة البداية الضريبية","qs":[{"q":"يجوز للمدير اعتبار الضريبة النهائية المقدرة على شخص طبيعي ضريبة أساسية مقطوعة للسنوات التالية إذا لم تزد على:","o":["ألف دينار، ولمدة لا تزيد على خمس سنوات","ألفي دينار، ولمدة لا تزيد على خمس سنوات","ألف دينار، ولمدة لا تزيد على ثلاث سنوات","خمسة آلاف دينار، ولمدة لا تزيد على أربع سنوات"],"a":0},{"q":"يجوز للمدير فرض ضريبة مقطوعة من قيمة مبيعات أي شخص لا تزيد مبيعاته على (١٥٠,٠٠٠) دينار بما لا يقل عن:","o":["(١%) من مبيعاته، ويخضع القرار لمصادقة الوزير","(٢%) من مبيعاته، ويخضع القرار لمصادقة الوزير","(١%) من مبيعاته، ويخضع القرار لمصادقة مجلس الوزراء","(٥%) من مبيعاته، دون حاجة لمصادقة"],"a":0},{"q":"يُعتبر القرار الصادر عن المدير وفق أحكام الضريبة المقطوعة قابلاً للطعن لدى:","o":["محكمة البداية الضريبية","هيئة الاعتراض","محكمة الاستئناف الضريبية","الوزير"],"a":0}]},{"n":"33","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-\n١-تُشكل بقرار من المدير هيئة إدارية واحدة أو أكثر تسمى (هيئة الاعتراض) للبت في الاعتراضات المقدمة وفق أحكام هذا القانون تتألف كل منها من ثلاثة مدققين من ذوي الخبرة والاختصاص، ويجوز إذا كان مقدار مبلغ الضريبة المعترض عليه لا يزيد على خمسة آلاف دينار أو إذا كان الدخل الصافي المعترض عليه خسارة لا تزيد على خمسين ألف دينار أن تؤلف هيئة الاعتراض من مدقق واحد.\n٢-تحدد إجراءات عمل هيئة الاعتراض وكيفية اتخاذ قراراتها بموجب نظام يصدر لهذه الغاية.\nب-يجوز للمكلف الاعتراض لدى هيئة الاعتراض على قرارات التدقيق الصادرة بمقتضى البند (٣) من الفقرة (أ) من المادة (٢٨) والبند (٢) من الفقرة (ب) من المادة (٢٩) من هذا القانون أو قرار التقدير الإداري الصادر بمقتضى المادة (٣١) من هذا القانون خلال مدة لا تزيد على ثلاثين يوماً من تاريخ تبليغه القرار.\nج-1\n١-في حال إصدار قرار بزيادة الدخل الخاضع للضريبة أو الضريبة المستحقة خلافاً لما أورده المكلف يقع عبء إثبات مصدر الدخل على الدائرة أثناء عملية التدقيق وفي مرحلة الاعتراض وبكافة طرق الإثبات القانونية.\n٢-فيما يتعلق بالشخص الاعتباري المكلف لا تسري أحكام البند (١) من هذه الفقرة إلا في حال قيامه بتقديم البيانات المالية الختامية المُعززة.\nد-\n١-يعتبر قرار التدقيق أو قرار التقدير الإداري قطعياً ونهائياً إذا لم يقدم الاعتراض الى هيئة الاعتراض خلال المدة المحددة في الفقرة (ب) من هذه المادة.\n٢-للهيئة تمديد مدة الاعتراض المنصوص عليها في البند (١) من هذه الفقرة لمدة لا تتجاوز سنتين من تاريخ تبليغ المعترض قرار التدقيق أو قرار التقدير الإداري إذا اقتنعت الهيئة أن المعترض لم يتمكن من تقديم اعتراضه خلال المدة المنصوص عليها في البند (١) من هذه الفقرة بسبب غيابه خارج المملكة أو مرضه أو لأي سبب معقول آخر.\nهـ-يلتزم المكلف بدفع الضريبة والغرامات والمبالغ الأخرى المسلم بها تحت طائلة رد الاعتراض شكلاً.\nو-تدعو هيئة الاعتراض المعترض إلى جلسة للنظر في اعتراضه، وللمعترض حق تقديم البينة على أسباب اعتراضه ولهيئة الاعتراض حق طلب المعلومات والتفاصيل الضرورية وطلب إبراز السجلات والمستندات المتعلقة بدخل المعترض كما لها الاستماع لأي شخص يعتقد أن لديه معلومات تتعلق بالقرار المعترض عليه.\nز-تصدر هيئة الاعتراض قراراً معللاً بشأن الاعتراض خلال تسعين يوماً من تاريخ تقديمه ولها تأييد القرار المعترض عليه أو تعديله سواءً بزيادة الضريبة أو تخفيضها أو إلغائها.\nح-للمكلف بعد الاطلاع على مضمون القرار الصادر بمقتضى الفقرة (ز) من هذه المادة، القيام بأي مما يلي:\n١-التوقيع بالموافقة على نتيجة القرار.\n٢-التوقيع بعدم الموافقة على نتيجة القرار ويعتبر امتناعه عن التوقيع أو تخلفه عن الحضور بمثابة عدم موافقة.\nط-تقوم الدائرة بتبليغ المكلف المعترض إشعاراً خطياً بنتيجة القرار الصادر بشأن الاعتراض وللمكلف المعترض في حال عدم الموافقة عليه الطعن به لدى المحكمة خلال ثلاثين يوماً من تاريخ تبليغه الإشعار.\nي-إذا لم تصدر هيئة الاعتراض قراراً بشأن الاعتراض خلال المدة المحددة في الفقرة (ز) من هذه المادة فلا تحسب أي غرامة تأخير عن هذه الفترة من تاريخ انقضاء المدة المذكورة ولحين صدور الإشعار المتضمن نتيجة القرار.","title":"هيئة الاعتراض","memo":"⭐ تشكل بقرار من المدير من ثلاثة مدققين، ويجوز من مدقق واحد إذا لم تزد الضريبة المعترض عليها على خمسة آلاف دينار أو الخسارة على خمسين ألف دينار\n⭐ الاعتراض خلال مدة لا تزيد على ثلاثين يوماً من التبليغ وإلا أصبح القرار قطعياً؛ ويجوز التمديد حتى سنتين لغياب أو مرض أو سبب معقول\n⭐ عبء إثبات مصدر الدخل على الدائرة (وللشخص الاعتباري بشرط تقديم بيانات مالية ختامية معززة)؛ ودفع المبالغ المسلم بها شرط وإلا رد الاعتراض شكلاً\n⭐ القرار خلال تسعين يوماً، والطعن لدى المحكمة خلال ثلاثين يوماً؛ وإذا تأخرت الهيئة لا تحسب غرامة تأخير عن مدة التأخير","qs":[{"q":"يجوز أن تؤلف هيئة الاعتراض من مدقق واحد إذا كان مقدار مبلغ الضريبة المعترض عليه لا يزيد على:","o":["خمسة آلاف دينار","ألف دينار","عشرة آلاف دينار","خمسين ألف دينار"],"a":0},{"q":"يجوز للمكلف الاعتراض لدى هيئة الاعتراض على قرار التقدير الإداري خلال مدة لا تزيد على:","o":["ثلاثين يوماً من تاريخ تبليغه القرار","تسعين يوماً من تاريخ تبليغه القرار","ستين يوماً من تاريخ صدور القرار","سنتين من تاريخ تبليغه القرار"],"a":0},{"q":"تُصدر هيئة الاعتراض قراراً معللاً بشأن الاعتراض خلال:","o":["تسعين يوماً من تاريخ تقديمه","ثلاثين يوماً من تاريخ تقديمه","ستين يوماً من تاريخ تقديمه","سنة من تاريخ تقديمه"],"a":0},{"q":"يترتب على عدم دفع المكلف للضريبة والمبالغ المسلم بها عند الاعتراض:","o":["رد الاعتراض شكلاً","مضاعفة غرامة التأخير","تحويل الاعتراض إلى المحكمة","تأجيل النظر في الاعتراض"],"a":0}]},{"n":"34","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-مع مراعاة أحكام الفقرة (ب) من هذه المادة، يجوز للمدير أو المدقق خلال مدة لا تزيد على أربع سنوات من تاريخ تقديم الإقرار الضريبي أو من تاريخ تعديله حسب مقتضى الحال أو تاريخ إصدار قرار التقدير الإداري أو فرض الضريبة المقطوعة وفق أحكام المادة (٣٢) من هذا القانون أن يقرر إعادة النظر في قرار التدقيق أو قرار التقدير الإداري أو القرار الصادر عن هيئة الاعتراض أو في أي إجراءات تم اتخاذها من المدير أو المدقق أو هيئة الاعتراض، وبعد أن يتيح المدير أو المدقق للمكلف فرصة معقولة لسماع أقواله وبسط قضيته له إصدار قرار معدل لأي من هذه القرارات لزيادة الضريبة أو تخفيضها في أي من الحالتين التاليتين:\n١-وجود خطأ في تطبيق القانون.\n٢-إغفال القرار السابق لحقيقة أو واقعة أو لوجود مصدر دخل لم يعالج في حينه.\nب-على الرغم مما ورد في أي نص آخر يقع عبء الإثبات على عاتق المدير أو المدقق في حالة زيادة الضريبة.\nج-لا يجوز أن يتضمن القرار المعدل لقرار التدقيق أو قرار التقدير الإداري والقرار الصادر عن هيئة الاعتراض أيا من الوقائع التي فصلت فيها المحكمة بقرار قطعي عندما نظرت في الطعن المقدم بشأن ذلك القرار.\nد-تقوم الدائرة بتبليغ المكلف إشعاراً خطياً بنتيجة القرار المعدل الصادر بمقتضى أحكام هذه المادة ويكون هذا القرار قابلاً للطعن لدى المحكمة خلال ثلاثين يوماً من تاريخ تبليغ الإشعار للمكلف.","title":"إعادة النظر في القرارات","memo":"⭐ للمدير أو المدقق خلال أربع سنوات إعادة النظر في قرارات التدقيق والتقدير والاعتراض بزيادة أو تخفيض الضريبة عند الخطأ في تطبيق القانون أو إغفال حقيقة أو مصدر دخل\n⭐ عبء الإثبات على المدير أو المدقق عند زيادة الضريبة؛ ولا يتناول القرار المعدل وقائع فصلت فيها المحكمة بقرار قطعي\n⭐ القرار المعدل قابل للطعن لدى المحكمة خلال ثلاثين يوماً من التبليغ","qs":[{"q":"يجوز للمدير أو المدقق إعادة النظر في قرار التدقيق خلال مدة لا تزيد على:","o":["أربع سنوات من تاريخ تقديم الإقرار أو تعديله","سنتين من تاريخ تقديم الإقرار أو تعديله","خمس سنوات من تاريخ صدور القرار","ثلاثين يوماً من تاريخ تبليغ القرار"],"a":0},{"q":"في حالة إصدار قرار معدل بزيادة الضريبة يقع عبء الإثبات على:","o":["المدير أو المدقق","المكلف","هيئة الاعتراض","المحكمة"],"a":0},{"q":"يكون القرار المعدل الصادر وفق المادة (٣٤) قابلاً للطعن لدى المحكمة خلال:","o":["ثلاثين يوماً من تاريخ تبليغ الإشعار للمكلف","تسعين يوماً من تاريخ تبليغ الإشعار للمكلف","ستين يوماً من تاريخ صدوره","سنتين من تاريخ صدوره"],"a":0}]},{"n":"35","chapter":"","notes":[],"source":"للمدير وفق تعليمات يصدرها إخضاع قرارات التدقيق وقرارات التقدير الإداري والقرارات الصادرة عن هيئة الاعتراض بشأن أي منها والقرارات المعدلة لها وأي قرارات أخرى صادرة وفق أحكام هذا القانون لتدقيقه مباشرة أو لتدقيق أي من المدققين ولا يكون أي من هذه القرارات الخاضعة للتدقيق بمقتضى أحكام هذه المادة نهائياً وملزماً ولا ينتج أي أثر قبل تدقيقه، ويعتبر أي تبليغ له قبل تدقيقه باطلاً ويفصل المدير في أي مسألة أو خلاف ينشأ عن هذا التدقيق.","title":"تدقيق المدير للقرارات","memo":"⭐ للمدير إخضاع قرارات التدقيق والتقدير والاعتراض لتدقيقه أو تدقيق أي مدقق\n⭐ القرار الخاضع للتدقيق لا يكون نهائياً ولا ينتج أثراً قبل تدقيقه، وأي تبليغ له قبل ذلك باطل، والمدير يفصل في أي خلاف","qs":[{"q":"حالة عملية: تم تبليغ مكلف قراراً أخضعه المدير لتدقيقه قبل إتمام تدقيقه. يعتبر هذا التبليغ:","o":["باطلاً","صحيحاً ومنتجاً لأثره","قابلاً للإبطال بطلب من المكلف","صحيحاً بعد مرور ثلاثين يوماً"],"a":0},{"q":"يفصل في أي مسألة أو خلاف ينشأ عن تدقيق القرارات الخاضعة لتدقيق المدير:","o":["المدير","الوزير","هيئة الاعتراض","محكمة البداية الضريبية"],"a":0}]},{"n":"36","chapter":"","notes":[],"source":"أ-في حال عدم دفع الضريبة أو توريدها في المواعيد المحددة بموجب أحكام هذا القانون تستوفي الدائرة غرامة تأخير بنسبة أربعة بالألف من قيمة رصيد الضريبة المستحقة أو أي مبالغ يتوجب اقتطاعها أو توريدها وذلك عن كل أسبوع تأخير أو أي جزء منه.\nب-إذا قدم المكلف الإقرار الضريبي ودفع الضريبة المصرح بها في الموعد المحدد وتوجب عليه بعد ذلك دفع أي فرق ضريبي وفق أحكام هذا القانون فتفرض عليه غرامة التأخير عن مقدار الفرق الضريبي من تاريخ تبليغه إشعار قرار التدقيق إذا كان مقدار الفرق لا يزيد على خمسة آلاف دينار أما إذا زاد مقدار الفرق على ذلك فتطبق عليه أحكام الفقرة (أ) من هذه المادة.\nج-مع مراعاة ما ورد في الفقرتين (أ) و (ب) من هذه المادة لا يجوز أن تزيد الغرامات عن مقدار الضريبة.\nد-تحدد التعليمات التنفيذية طرق دفع الضريبة وتوريدها وأي إجراءات أخرى لازمة لذلك.","title":"غرامة التأخير","memo":"⭐ غرامة التأخير أربعة بالألف من رصيد الضريبة أو المبالغ الواجب اقتطاعها عن كل أسبوع تأخير أو جزء منه\n⭐ إذا قدم الإقرار ودفع في الموعد وظهر فرق لا يزيد على خمسة آلاف دينار تحتسب الغرامة من تاريخ تبليغ إشعار قرار التدقيق\n⭐ لا يجوز أن تزيد الغرامات عن مقدار الضريبة","qs":[{"q":"تستوفي الدائرة غرامة تأخير عن عدم دفع الضريبة في موعدها بنسبة:","o":["أربعة بالألف عن كل أسبوع تأخير أو أي جزء منه","أربعة بالألف عن كل شهر تأخير أو أي جزء منه","واحد بالمائة عن كل أسبوع تأخير","تسعة بالمائة سنوياً"],"a":0},{"q":"حالة عملية: قدّم مكلف إقراره ودفع الضريبة في الموعد، ثم ظهر فرق ضريبي مقداره (٣٠٠٠) دينار. تُفرض غرامة التأخير على هذا الفرق اعتباراً من:","o":["تاريخ تبليغه إشعار قرار التدقيق","الموعد المحدد لدفع الضريبة","تاريخ تقديم الإقرار","تاريخ اكتساب القرار الصفة القطعية"],"a":0},{"q":"لا يجوز أن تزيد الغرامات المفروضة على:","o":["مقدار الضريبة","ضعف مقدار الضريبة","نصف مقدار الضريبة","خمسة آلاف دينار"],"a":0}]},{"n":"37","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-للمدير ولأسباب مبررة تقسيط المبلغ المستحق على المكلف وفق الشروط والإجراءات التي تحددها التعليمات التنفيذية.\nب-يلزم المكلف بدفع مبلغ إضافي على المبلغ المقسط بنسبة (٩%) سنوياً.","title":"تقسيط الضريبة","memo":"⭐ للمدير لأسباب مبررة تقسيط المبلغ المستحق وفق التعليمات التنفيذية\n⭐ يدفع المكلف مبلغاً إضافياً على المبلغ المقسط بنسبة (٩%) سنوياً","qs":[{"q":"يملك صلاحية تقسيط المبلغ المستحق على المكلف لأسباب مبررة:","o":["المدير","الوزير","المدقق","مجلس الوزراء"],"a":0},{"q":"يلتزم المكلف بدفع مبلغ إضافي على المبلغ المقسط بنسبة:","o":["(٩%) سنوياً","(٤%) سنوياً","(٩%) شهرياً","(٥%) سنوياً"],"a":0}]},{"n":"38","chapter":"","notes":[],"source":"أ-إذا دفع المكلف مبلغاً يزيد على المبالغ المستحقة عليه فعلى الدائرة تحويل الرصيد الزائد لتسديد أي مبالغ أخرى مستحقة عليه للدائرة بمقتضى أحكام التشريعات النافذة، وإذا تبقى أي مبلغ من هذا الرصيد، تلزم الدائرة برده إلى المكلف خلال مدة لا تزيد على ثلاثين يوماً من تاريخ تسلمها طلباً خطياً بذلك.\nب-إذا لم ترد الدائرة الرصيد الزائد في الموعد المحدد في الفقرة (أ) من هذه المادة فتلتزم بدفع مبلغ إضافي بنسبة (٩%) سنوياً.","title":"رد الرصيد الزائد","memo":"⭐ الرصيد الزائد يحوّل أولاً لتسديد أي مبالغ أخرى مستحقة للدائرة، ثم يرد الباقي خلال ثلاثين يوماً من تسلم طلب خطي\n⭐ إذا تأخرت الدائرة في الرد تدفع مبلغاً إضافياً بنسبة (٩%) سنوياً","qs":[{"q":"إذا دفع المكلف مبلغاً يزيد على المستحق عليه، فعلى الدائرة أولاً:","o":["تحويل الرصيد الزائد لتسديد أي مبالغ أخرى مستحقة عليه للدائرة","رده نقداً إلى المكلف فوراً","تدويره دفعة مقدمة للسنة التالية فقط","إيداعه في حساب المساهمة الوطنية"],"a":0},{"q":"تلتزم الدائرة برد المبلغ المتبقي من الرصيد الزائد إلى المكلف خلال مدة لا تزيد على:","o":["ثلاثين يوماً من تاريخ تسلمها طلباً خطياً بذلك","تسعين يوماً من تاريخ تسلمها طلباً خطياً بذلك","ثلاثين يوماً من تاريخ الدفع","سنة من تاريخ تقديم الإقرار"],"a":0},{"q":"إذا لم ترد الدائرة الرصيد الزائد في الموعد المحدد فتلتزم بدفع مبلغ إضافي بنسبة:","o":["(٩%) سنوياً","(٤%) سنوياً","أربعة بالألف أسبوعياً","(١٠%) سنوياً"],"a":0}]},{"n":"39","chapter":"","notes":[],"source":"أ-إذا لم يتم دفع الضريبة أو المبالغ المستحقة للدائرة خلال المدد المنصوص عليها في هذا القانون فعلى الدائرة مطالبة المكلف بدفعها خلال ثلاثين يوماً من تاريخ التبليغ وإذا تخلف المكلف عن ذلك يتم تحصيلها وفق أحكام قانون تحصيل الأموال الأميرية، ويمارس المدير أو من يفوضه جميع الصلاحيات المخولة للحاكم الإداري وللجنة تحصيل الأموال الأميرية المنصوص عليها في ذلك القانون.\nب-يعتبر تبليغ المكلف بوجوب دفع الضريبة والمبالغ المستحقة عليه وفق أحكام الفقرة (أ) من هذه المادة كافياً لغايات مباشرة المدير أو من يفوضه إجراءات الحجز والتنفيذ وفق أحكام قانون تحصيل الأموال الأميرية وذلك دون حاجة لاتخاذ أي من إجراءات التبليغ أو النشر المنصوص عليها في القانون المذكور.","title":"تحصيل الضريبة","memo":"⭐ تطالب الدائرة المكلف بالدفع خلال ثلاثين يوماً من التبليغ، وإلا تحصل وفق قانون تحصيل الأموال الأميرية (العامة)\n⭐ يمارس المدير أو من يفوضه صلاحيات الحاكم الإداري ولجنة تحصيل الأموال الأميرية\n⭐ التبليغ بوجوب الدفع كاف لمباشرة الحجز والتنفيذ دون إجراءات تبليغ أو نشر أخرى","qs":[{"q":"إذا لم تدفع الضريبة في المدد القانونية، تطالب الدائرة المكلف بدفعها خلال:","o":["ثلاثين يوماً من تاريخ التبليغ","عشرة أيام من تاريخ التبليغ","تسعين يوماً من تاريخ التبليغ","سنة من تاريخ الاستحقاق"],"a":0},{"q":"يمارس المدير أو من يفوضه في تحصيل الضريبة جميع الصلاحيات المخولة لـ:","o":["الحاكم الإداري ولجنة تحصيل الأموال الأميرية","النيابة العامة الضريبية","محكمة البداية الضريبية","دائرة التنفيذ في المحاكم النظامية"],"a":0},{"q":"يُعتبر تبليغ المكلف بوجوب دفع الضريبة كافياً لمباشرة إجراءات الحجز والتنفيذ:","o":["دون حاجة لأي من إجراءات التبليغ أو النشر الأخرى","بعد نشر إعلان في صحيفتين يوميتين","بعد صدور حكم قضائي قطعي","بعد موافقة الوزير الخطية"],"a":0}]},{"n":"40","chapter":"","notes":["أصبح عنوان قانون تحصيل الأموال الأميرية هو قانون تحصيل الأموال العامة بموجب القانون المعدل لقانون تحصيل الأموال الأميرية رقم (١٢) لسنة ٢٠١٧ المنشور في عدد الجريدة الرسمية رقم ٥٤٥٨ تاريخ ٢٠١٧/٥/١."],"source":"على المدير اتخاذ ما يلزم لمراعاة ما يلي:\nأ-إذا كان المبلغ المحجوز نقداً فلا يجوز أن يتجاوز هذا المبلغ مقدار الضريبة والغرامات والمبالغ الأخرى المستحقة.\nب-إذا كان المبلغ المحجوز من غير النقود فيقوم المدير وبناء على طلب المكلف باتخاذ ما يلزم من إجراءات لتقدير قيمة المال المحجوز واقتصار الحجز على ما يعادل ضعف قيمة الضريبة والغرامات والمبالغ الأخرى المترتبة بمقتضى أحكام هذا القانون، وتكون مصاريف التقدير على نفقة المكلف.","title":"حدود الحجز","memo":"⭐ الحجز النقدي لا يتجاوز مقدار الضريبة والغرامات والمبالغ المستحقة\n⭐ الحجز غير النقدي يقتصر بناء على طلب المكلف على ما يعادل ضعف قيمة الضريبة والمبالغ المترتبة، ومصاريف التقدير على نفقة المكلف","qs":[{"q":"إذا كان المال المحجوز من غير النقود، يقتصر الحجز بناءً على طلب المكلف على ما يعادل:","o":["ضعف قيمة الضريبة والغرامات والمبالغ الأخرى المترتبة","قيمة الضريبة والغرامات فقط","ثلاثة أضعاف قيمة الضريبة","نصف قيمة الضريبة والغرامات"],"a":0},{"q":"تكون مصاريف تقدير قيمة المال المحجوز من غير النقود على نفقة:","o":["المكلف","الدائرة","المدير","الخزينة العامة"],"a":0}]},{"n":"41","chapter":"","notes":[],"source":"لأي من أعضاء النيابة العامة الضريبية بناء على طلب المدير أن يطلب من المحكمة إصدار قرار بإلقاء الحجز التحفظي على الأموال المنقولة وغير المنقولة العائدة لأي مكلف أو أن يطلب منع المكلف من السفر حال توافر أدلة تشير إلى وجود حالات تهرب ضريبي أو إذا كانت الدائرة تطالبه بدفع الضريبة أو أي مبالغ أخرى تزيد على ألفي دينار ترتبت بموجب أحكام هذا القانون أو أنه قد يقوم بتهريب أمواله أو التصرف فيها بقصد منع التنفيذ عليها بأي شكل من الأشكال.","title":"الحجز التحفظي ومنع السفر","memo":"⭐ لعضو النيابة العامة الضريبية بناء على طلب المدير أن يطلب من المحكمة الحجز التحفظي على أموال المكلف أو منعه من السفر\n⭐ الحالات: أدلة تهرب ضريبي، أو مطالبة بمبالغ تزيد على ألفي دينار، أو احتمال تهريب أمواله أو التصرف فيها لمنع التنفيذ","qs":[{"q":"يطلب من المحكمة إصدار قرار بإلقاء الحجز التحفظي على أموال المكلف أو منعه من السفر:","o":["أحد أعضاء النيابة العامة الضريبية بناءً على طلب المدير","المدير مباشرة بناءً على طلب المدقق","الوزير بناءً على تنسيب المدير","هيئة الاعتراض بناءً على طلب الدائرة"],"a":0},{"q":"يجوز طلب منع المكلف من السفر إذا كانت الدائرة تطالبه بدفع ضريبة أو مبالغ أخرى تزيد على:","o":["ألفي دينار","ألف دينار","خمسة آلاف دينار","عشرة آلاف دينار"],"a":0},{"q":"أي مما يلي لا يُعد من الحالات التي تجيز طلب الحجز التحفظي على أموال المكلف؟","o":["تأخر المكلف في تقديم إقراره أسبوعاً واحداً","توافر أدلة على وجود تهرب ضريبي","احتمال قيامه بتهريب أمواله","التصرف في أمواله بقصد منع التنفيذ عليها"],"a":0}]},{"n":"42","chapter":"","notes":[],"source":"أ-تنشأ محكمة بداية تسمى (محكمة البداية الضريبية) تؤلف من رئيس وعدد من القضاة يعينهم المجلس القضائي وتختص بالنظر في جميع الدعاوى الناشئة عن تطبيق أحكام هذا القانون والأنظمة والتعليمات التنفيذية والتعليمات الصادرة بمقتضاه مهما كانت قيمتها وبغض النظر عن طبيعتها جزائية أم مدنية، وسواء كانت المطالبة موضوع الدعوى متعلقة بالضريبة أو بغرامة التأخير أو بأي مبالغ أخرى يتعين دفعها أو اقتطاعها أو توريدها أو ردها بمقتضى أحكام هذا القانون بما في ذلك ما يلي:\n١-الدعاوى المقامة للطعن في القرارات الصادرة عن هيئة الاعتراض وفق أحكام الفقرة (و) والبند (٢) من الفقرة (ز) من المادة (٣٣) من هذا القانون.\n٢-القرارات المعدلة لقرارات التدقيق أو لقرارات التقدير الإداري أو للقرارات الصادرة عن هيئة الاعتراض والقابلة للطعن وفق أحكام هذا القانون.\n٣-الجرائم التي ترتكب خلافاً لأحكام هذا القانون.\n٤-طلبات الحجز التحفظي والمنع من السفر.\nب-تنشأ محكمة استئناف تسمى (محكمة الاستئناف الضريبية) تؤلف من رئيس وعدد من القضاة لا تقل درجتهم عن الرابعة يعينهم المجلس القضائي.\nج-\n١-تنعقد محكمة البداية الضريبية من قاض منفرد.\n٢-تنعقد محكمة الاستئناف الضريبية من هيئة مؤلفة من ثلاثة قضاة على الأقل وتصدر قراراتها وأحكامها بالإجماع أو بالأكثرية.\n٣-تعقد كل من محكمة البداية الضريبية ومحكمة الاستئناف الضريبية جلساتها في مدينة عمان أو في أي مكان آخر تحدده داخل المملكة.\nد-\n١-تنظر المحكمة بالطعون المقدمة إليها في الدعاوى الجزائية تدقيقاً إلا إذا رأت المحكمة خلاف ذلك.\n٢-تنظر المحكمة تدقيقاً في الطعون المقدمة إليها في الدعوى الحقوقية التي لا تزيد القيمة الإجمالية للدعوى عن ثلاثين ألف دينار إلا إذا قررت رؤيتها مرافعة من تلقاء ذاتها أو بناءً على طلب أحد الخصوم.\n٣-تنظر المحكمة في الطعون الحقوقية المرفوعة إليها في الدعاوى التي تزيد قيمتها عن ثلاثين ألف دينار مرافعة.\n٤-تنظر المحكمة في الطلبات المقدمة إليها أو المطعون بها إليها تدقيقاً إلا إذا قررت رؤيتها من تلقاء ذاتها مرافعة.\nهـ-تجري المحاكمة لدى المحكمة بصورة علنية إلا إذا أمرت المحكمة خلاف ذلك، وتعطى الدعاوى والطلبات المنظورة أمامها صفة الاستعجال.\nو-يستوفى الرسم المقرر للدعوى عن قيمة الضريبة المختلف عليها والغرامات المتعلقة بها عن كل فترة ضريبية.","title":"المحاكم الضريبية واختصاصها","memo":"⭐ محكمة البداية الضريبية: رئيس وعدد من القضاة يعينهم المجلس القضائي، تنعقد من قاض منفرد، وتختص بجميع الدعاوى مهما كانت قيمتها جزائية أم مدنية (ومنها طلبات الحجز التحفظي والمنع من السفر)\n⭐ محكمة الاستئناف الضريبية: قضاة لا تقل درجتهم عن الرابعة، تنعقد من ثلاثة قضاة على الأقل وتصدر أحكامها بالإجماع أو بالأكثرية\n⭐ الطعون الحقوقية التي لا تزيد قيمتها عن ثلاثين ألف دينار تنظر تدقيقاً، وما يزيد عن ثلاثين ألف دينار مرافعة؛ والطعون الجزائية تدقيقاً\n⭐ المحاكمة علنية وتعطى الدعاوى صفة الاستعجال، والرسم عن كل فترة ضريبية","qs":[{"q":"وفقاً لقانون ضريبة الدخل، تنعقد محكمة البداية الضريبية من:","o":["قاض منفرد","هيئة من قاضيين","هيئة من ثلاثة قضاة على الأقل","هيئة من خمسة قضاة"],"a":0},{"q":"لا تقل درجة القضاة في محكمة الاستئناف الضريبية عن الدرجة:","o":["الرابعة","الثالثة","الخامسة","الثانية"],"a":0},{"q":"طعن حقوقي أمام المحكمة في دعوى قيمتها الإجمالية (٢٥) ألف دينار، فإن الأصل أن تنظر فيه المحكمة:","o":["تدقيقاً إلا إذا قررت رؤيته مرافعة من تلقاء ذاتها أو بناءً على طلب أحد الخصوم","مرافعة وجوباً","تدقيقاً ولا يجوز رؤيته مرافعة","مرافعة إلا إذا اتفق الخصوم على التدقيق"],"a":0},{"q":"جميع ما يلي يدخل في اختصاص محكمة البداية الضريبية باستثناء:","o":["الطعن في أحكام محكمة الاستئناف الضريبية","طلبات الحجز التحفظي والمنع من السفر","الجرائم التي ترتكب خلافاً لأحكام قانون ضريبة الدخل","الطعن في القرارات الصادرة عن هيئة الاعتراض"],"a":0}]},{"n":"43","chapter":"","notes":[],"source":"أ-يجب أن تشتمل لائحة الدعوى المقامة لدى محكمة البداية الضريبية على البيانات التالية:\n١-اسم المحكمة.\n٢-اسم المدعي بالكامل سواء كان الدائرة أو من يمثلها أو اسم المدعي الصادر بحقه القرار المطعون فيه ووكيله.\n٣-اسم المدعى عليه بالكامل ومن يمثله، وعنوان كل منهما للتبليغ، وفي حال كان المدعى عليه هو مصدر القرار المطعون فيه بصفته الوظيفية يمثله المدعي العام الضريبي.\n٤-الرقم الضريبي للمدعي أو المدعى عليه حسب مقتضى الحال والفترة الضريبية التي يقدم الطعن بشأنها.\n٥-تاريخ تبلغ الإشعار الخطي بالقرار المطعون فيه وطريقة التبليغ في حال كان المدعي هو المكلف أو من يمثله قانوناً.\n٦-مبلغ الضريبة وأي مبالغ أخرى مطالب بها في القرار المطعون فيه.\n٧-وقائع الدعوى وأسانيدها وأسباب الطعن بصورة موجزة وفي بنود مستقلة ومرقمة وخالية من الجدل وطلبات المدعي.\n٨-توقيع ممثل المدعي أو وكيله حسب مقتضى الحال وتاريخ تحرير الدعوى.\nب-على المكلف أن يبين في لائحة دعواه المبلغ الذي يسلم به وأن يقدم إلى المحكمة مع لائحة دعواه إيصالاً بدفعه، وترد الدعوى إذا لم يدفع المبلغ المحدد في هذه الفقرة على ذلك الوجه.\nج-تقدم لائحة الدعوى خلال مدة ثلاثين يوماً من اليوم التالي من تاريخ تبليغ القرار القابل للطعن وفق أحكام هذا القانون أو أي قانون آخر ذي علاقة لدى محكمة البداية الضريبية.","title":"بيانات لائحة الدعوى وميعادها","memo":"⭐ تقدم لائحة الدعوى لدى محكمة البداية الضريبية خلال ثلاثين يوماً من اليوم التالي لتاريخ تبليغ القرار القابل للطعن\n⭐ على المكلف أن يبين في لائحة دعواه المبلغ الذي يسلم به ويرفق إيصالاً بدفعه، وإلا ترد الدعوى\n⭐ إذا كان المدعى عليه مصدر القرار بصفته الوظيفية يمثله المدعي العام الضريبي","qs":[{"q":"تقدم لائحة الدعوى لدى محكمة البداية الضريبية خلال مدة:","o":["ثلاثين يوماً من اليوم التالي لتاريخ تبليغ القرار القابل للطعن","خمسة عشر يوماً من تاريخ صدور القرار","ستين يوماً من اليوم التالي لتاريخ التبليغ","عشرة أيام من تاريخ التبليغ"],"a":0},{"q":"أقام مكلف دعوى طعن دون أن يبين المبلغ الذي يسلم به ويقدم إيصالاً بدفعه، فإن الأثر القانوني هو:","o":["رد الدعوى","وقف الدعوى لحين الدفع","إمهاله ثلاثين يوماً للدفع","قبول الدعوى وفرض غرامة تأخير"],"a":0},{"q":"إذا كان المدعى عليه في الدعوى هو مصدر القرار المطعون فيه بصفته الوظيفية، فيمثله:","o":["المدعي العام الضريبي","المدير","محامي الدائرة المعين من الوزير","النائب العام لدى محكمة التمييز"],"a":0}]},{"n":"44","chapter":"","notes":[],"source":"تقدم لائحة الدعوى إلى محكمة البداية الضريبية أو بوساطة رئيس محكمة البداية التي يقيم المكلف في منطقة اختصاصها وفي هذه الحالة تدفع الرسوم إلى صندوق المحكمة التي قدمت لائحة الدعوى بوساطة رئيسها، وترسل هذه المحكمة اللائحة ومرفقاتها إلى محكمة البداية الضريبية خلال عشرة أيام من تاريخ تقديمها.","title":"تقديم لائحة الدعوى بوساطة محكمة البداية","memo":"⭐ يجوز تقديم لائحة الدعوى إلى محكمة البداية الضريبية أو بوساطة رئيس محكمة البداية التي يقيم المكلف في منطقة اختصاصها\n⭐ تدفع الرسوم إلى صندوق المحكمة التي قدمت إليها اللائحة، وترسلها إلى محكمة البداية الضريبية خلال عشرة أيام من تقديمها","qs":[{"q":"إذا قدم المكلف لائحة دعواه بوساطة رئيس محكمة البداية التي يقيم في منطقة اختصاصها، فعلى هذه المحكمة إرسال اللائحة إلى محكمة البداية الضريبية خلال:","o":["عشرة أيام من تاريخ تقديمها","ثلاثين يوماً من تاريخ تقديمها","خمسة عشر يوماً من تاريخ تقديمها","سبعة أيام من تاريخ تقديمها"],"a":0},{"q":"عند تقديم لائحة الدعوى بوساطة رئيس محكمة البداية التي يقيم المكلف في منطقة اختصاصها، تدفع الرسوم إلى:","o":["صندوق المحكمة التي قدمت لائحة الدعوى بوساطة رئيسها","صندوق محكمة البداية الضريبية","صندوق الدائرة","صندوق محكمة الاستئناف الضريبية"],"a":0}]},{"n":"45","chapter":"","notes":[],"source":"أ-يجوز لمحكمة البداية الضريبية بعد قبول الدعوى شكلاً تأجيلها باتفاق الطرفين لمرة واحدة أو أكثر لإتاحة الفرصة لحلها مصالحة على أن لا يزيد مجموع مدد التأجيل في جميع الحالات على ستين يوماً.\nب-إذا لم يتفق الطرفان على تأجيل الدعوى لغايات المصالحة أو لم يتم إجراء المصالحة خلال المدة المحددة في الفقرة (أ) من هذه المادة يقدم المدعي العام الضريبي الملف الخاص بالقرار المطعون فيه أو صورة مصدقة عنه، ويعتبر هذا الملف عند تقديمه بينة للمدعي العام الضريبي.\nج-يقدم المدعي خلال ثلاثين يوماً من تاريخ تقديم الملف الضريبي حافظة بجميع مستنداته وقائمة بيناته الخطية الموجودة تحت يد الغير وقائمة بأسماء شهوده وعناوينهم الكاملة والوقائع التي يرغب في إثباتها بالبينة الشخصية لكل شاهد على حدة وأي بينة أخرى يجيزها القانون.\nد-بعد ختم المدعي بيناته، يقدم المدعى عليه أي بينات لازمة للرد على بينات المدعي وذلك خلال ثلاثين يوماً من تاريخ ختم المدعي بيناته حافظة مستنداته وقائمة بالبينات الموجودة تحت يد الغير وقائمة بأسماء الشهود والوقائع التي يرغب في إثباتها بالبينة الشخصية لكل شاهد على حده وأي بينة أخرى يجيزها القانون.\nهـ-يكون ميعاد الثلاثين يوماً المنصوص عليه في كل من الفقرتين (ج) و(د) من هذه المادة قابلاً للتمديد حسب ما تراه المحكمة.","title":"التأجيل للمصالحة وتقديم البينات","memo":"⭐ يجوز تأجيل الدعوى باتفاق الطرفين للمصالحة على ألا يزيد مجموع مدد التأجيل على ستين يوماً\n⭐ يقدم المدعي العام الضريبي ملف القرار المطعون فيه ويعتبر بينة له\n⭐ يقدم المدعي بيناته خلال ثلاثين يوماً من تقديم الملف، والمدعى عليه خلال ثلاثين يوماً من ختم المدعي بيناته، والمدة قابلة للتمديد حسب ما تراه المحكمة","qs":[{"q":"لا يجوز أن يزيد مجموع مدد تأجيل الدعوى لغايات المصالحة في جميع الحالات على:","o":["ستين يوماً","ثلاثين يوماً","تسعين يوماً","مائة وعشرين يوماً"],"a":0},{"q":"يقدم المدعي حافظة مستنداته وقائمة بيناته خلال ثلاثين يوماً من تاريخ:","o":["تقديم الملف الضريبي","قبول الدعوى شكلاً","تبليغ القرار المطعون فيه","انتهاء مدة التأجيل للمصالحة"],"a":0},{"q":"ميعاد الثلاثين يوماً المحدد لتقديم بينات المدعي والمدعى عليه:","o":["قابل للتمديد حسب ما تراه المحكمة","غير قابل للتمديد مطلقاً","قابل للتمديد باتفاق الطرفين فقط","قابل للتمديد بقرار من المدير"],"a":0}]},{"n":"46","chapter":"","notes":[],"source":"أ-يقع على المكلف إقامة الدليل على أن المبالغ التي حددها القرار المطعون فيه باهظة ويجوز له تقديم المستندات التي لم يقدمها إلى هيئة الاعتراض.\nب-للمحكمة أن تؤيد ما ورد في القرار المطعون فيه أو أن تخفض أو تلغي الضريبة والمبالغ الأخرى المقررة بموجبه كما لها أن تعيد القضية الى مصدر القرار المطعون فيه لإعادة النظر فيه.\nج-إذا تم إسقاط الدعوى بسبب الغياب أو لأي سبب آخر، ولم يتم تجديدها يعتبر القرار المطعون فيه قطعياً بعد مرور ثلاثين يوماً من تاريخ تبليغ المحكمة قرار الإسقاط للمكلف أو وكيله وفي جميع الأحوال لا يجوز تجديد الدعوى المسقطة للسبب نفسه لأكثر من مرتين وبسبب مبرر.\nد-توقف الدعوى لوفاة المكلف أو إفلاسه أو تصفيته أثناء النظر فيها من المحكمة، ويتوجب على الورثة أو وكيل التفليسة أو المصفي متابعة السير في الدعوى خلال ستة أشهر على الأكثر من تاريخ تبليغهم من المحكمة وفق قانون أصول المحاكمات المدنية، وفي حال عدم متابعة السير فيها يكتسب القرار المطعون فيه الدرجة القطعية.\nهـ-تختص محكمة البداية الضريبية بالنظر في جميع الدعاوى التي كانت تدخل قبل ٢٠١٠/١/١ ضمن اختصاص محكمة استئناف قضايا ضريبة الدخل بمقتضى أحكام قانون ضريبة الدخل رقم (٥٧) لسنة ١٩٨٥ وتعديلاته أو قانون منطقة العقبة الاقتصادية الخاصة.","title":"عبء الإثبات وصلاحيات المحكمة","memo":"⭐ يقع على المكلف إقامة الدليل على أن المبالغ في القرار المطعون فيه باهظة، وله تقديم مستندات لم يقدمها لهيئة الاعتراض\n⭐ للمحكمة تأييد القرار أو تخفيض أو إلغاء الضريبة أو إعادة القضية لمصدر القرار\n⭐ الدعوى المسقطة غير المجددة: يصبح القرار قطعياً بعد ثلاثين يوماً من تبليغ قرار الإسقاط، ولا تجدد للسبب نفسه أكثر من مرتين\n⭐ توقف الدعوى بالوفاة أو الإفلاس أو التصفية، وعلى الورثة/الوكيل/المصفي المتابعة خلال ستة أشهر وإلا اكتسب القرار الدرجة القطعية","qs":[{"q":"يقع عبء إثبات أن المبالغ التي حددها القرار المطعون فيه باهظة على:","o":["المكلف","الدائرة","المدعي العام الضريبي","هيئة الاعتراض"],"a":0},{"q":"إذا أسقطت الدعوى بسبب الغياب ولم تجدد، يعتبر القرار المطعون فيه قطعياً بعد مرور:","o":["ثلاثين يوماً من تاريخ تبليغ المحكمة قرار الإسقاط للمكلف أو وكيله","ستين يوماً من تاريخ قرار الإسقاط","ستة أشهر من تاريخ قرار الإسقاط","خمسة عشر يوماً من تاريخ قرار الإسقاط"],"a":0},{"q":"توفي مكلف أثناء نظر دعواه، فيتوجب على الورثة متابعة السير في الدعوى خلال مدة أقصاها:","o":["ستة أشهر من تاريخ تبليغهم من المحكمة","ثلاثون يوماً من تاريخ الوفاة","سنة من تاريخ الوفاة","ثلاثة أشهر من تاريخ تبليغهم من المحكمة"],"a":0},{"q":"لا يجوز تجديد الدعوى المسقطة للسبب نفسه لأكثر من:","o":["مرتين وبسبب مبرر","مرة واحدة","ثلاث مرات","أربع مرات"],"a":0}]},{"n":"47","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-يقدم الاستئناف خلال ثلاثين يوماً من اليوم التالي لتاريخ صدور الحكم إذا كان وجاهياً أو من اليوم التالي لتاريخ تبليغ المحكمة للمدعي بالقرار الصادر عن محكمة البداية الضريبية إذا لم يكن ذلك الحكم وجاهياً.\nب-يجب أن تشتمل لائحة الاستئناف على البيانات التالية:\n١-المستأنف ومن يمثله وعنوان كل منهما للتبليغ.\n٢-المستأنف عليه ومن يمثله وعنوان كل منهما للتبليغ.\n٣-المحكمة التي أصدرت الحكم المستأنف وتاريخه ورقم الدعوى التي صدر فيها.\n٤-تاريخ تبلغ المستأنف بالقرار المستأنف وفق أحكام الفقرة (أ) من هذه المادة إن لم يكن الحكم الصادر وجاهياً.\n٥-بيان جميع أسباب الاستئناف بصورة موجزة وفي بنود مستقلة ومرقمة.\n٦-طلبات المستأنف.\n٧-توقيع وكيل المستأنف أو من يمثله وتاريخ تحرير الاستئناف.\n٨-لكل من المستأنف والمستأنف عليه أن يرفقا بلائحتي استئنافهما مذكرة توضيحية.\nج-تقدم لائحة الاستئناف إلى محكمة البداية الضريبية أو محكمة الاستئناف التي يقيم المكلف في منطقة اختصاصها، وفي هذه الحالة تدفع الرسوم إلى صندوق المحكمة التي قدمت لائحة الاستئناف إليها، وترسل هذه المحكمة اللائحة ومرفقاتها إلى محكمة البداية الضريبية خلال عشرة أيام من تاريخ تقديمها.","title":"ميعاد الاستئناف وبيانات لائحته","memo":"⭐ يقدم الاستئناف خلال ثلاثين يوماً من اليوم التالي لصدور الحكم إن كان وجاهياً، أو من اليوم التالي لتبليغه إن لم يكن وجاهياً\n⭐ تقدم لائحة الاستئناف إلى محكمة البداية الضريبية أو محكمة الاستئناف التي يقيم المكلف في منطقة اختصاصها، وترسل خلال عشرة أيام\n⭐ يجوز لكل من المستأنف والمستأنف عليه إرفاق مذكرة توضيحية","qs":[{"q":"يقدم الاستئناف على حكم وجاهي صادر عن محكمة البداية الضريبية خلال:","o":["ثلاثين يوماً من اليوم التالي لتاريخ صدور الحكم","خمسة عشر يوماً من تاريخ صدور الحكم","ستين يوماً من اليوم التالي لتاريخ صدور الحكم","عشرة أيام من تاريخ صدور الحكم"],"a":0},{"q":"تقدم لائحة الاستئناف إلى:","o":["محكمة البداية الضريبية أو محكمة الاستئناف التي يقيم المكلف في منطقة اختصاصها","محكمة التمييز مباشرة","هيئة الاعتراض","المدعي العام الضريبي"],"a":0},{"q":"جميع ما يلي من البيانات الواجب اشتمال لائحة الاستئناف عليها باستثناء:","o":["المبلغ الذي يسلم به المستأنف مع إيصال بدفعه","طلبات المستأنف","المحكمة التي أصدرت الحكم المستأنف وتاريخه ورقم الدعوى","بيان أسباب الاستئناف في بنود مستقلة ومرقمة"],"a":0}]},{"n":"48","chapter":"","notes":[],"source":"أ-يقدم التمييز خلال ثلاثين يوماً من اليوم التالي لتاريخ صدور الحكم إذا كان وجاهياً أو من اليوم التالي لتاريخ تبليغ المستأنف أو المستأنف عليه بالقرار الصادر عن محكمة الاستئناف الضريبية إذا لم يكن ذلك الحكم وجاهياً.\nب-يجب أن تشتمل لائحة التمييز على البيانات التالية:\n١-المميز ومن يمثله وعنوان كل منهما.\n٢-المميز ضده ومن يمثله وعنوان كل منهما.\n٣-المحكمة التي أصدرت الحكم المميز وتاريخه ورقم الدعوى التي صدر فيها.\n٤-تاريخ تبلغ المميز للقرار وفق أحكام الفقرة (أ) من هذه المادة إن لم يكن ذلك الحكم وجاهياً.\n٥-أسباب الطعن بالتمييز بصورة واضحة، وفي بنود مستقلة ومرقمة وعلى المميز أن يبين طلباته، وله أن يرفق بلائحة التمييز مذكرة توضيحية مطبوعة تتعلق بأسباب الطعن.\nج-تقدم لائحة التمييز إلى محكمة الاستئناف الضريبية أو محكمة الاستئناف التي يقيم المكلف في منطقة اختصاصها، وفي هذه الحالة تدفع الرسوم إلى صندوق المحكمة التي قدمت لائحة التمييز إليها، وترسل هذه المحكمة اللائحة ومرفقاتها إلى محكمة الاستئناف الضريبية خلال عشرة أيام من تاريخ تقديمها.","title":"ميعاد التمييز وبيانات لائحته","memo":"⭐ يقدم التمييز خلال ثلاثين يوماً من اليوم التالي لصدور الحكم إن كان وجاهياً أو من اليوم التالي للتبليغ إن لم يكن وجاهياً\n⭐ تقدم لائحة التمييز إلى محكمة الاستئناف الضريبية أو محكمة الاستئناف التي يقيم المكلف في منطقة اختصاصها، وترسل إلى محكمة الاستئناف الضريبية خلال عشرة أيام\n⭐ للمميز أن يرفق مذكرة توضيحية مطبوعة تتعلق بأسباب الطعن","qs":[{"q":"يقدم الطعن بالتمييز في حكم وجاهي صادر عن محكمة الاستئناف الضريبية خلال:","o":["ثلاثين يوماً من اليوم التالي لتاريخ صدور الحكم","عشرين يوماً من تاريخ صدور الحكم","ستين يوماً من تاريخ صدور الحكم","خمسة عشر يوماً من اليوم التالي لتاريخ صدور الحكم"],"a":0},{"q":"تقدم لائحة التمييز إلى:","o":["محكمة الاستئناف الضريبية أو محكمة الاستئناف التي يقيم المكلف في منطقة اختصاصها","محكمة البداية الضريبية فقط","المجلس القضائي","هيئة الاعتراض"],"a":0},{"q":"إذا قدمت لائحة التمييز إلى محكمة الاستئناف التي يقيم المكلف في منطقة اختصاصها، فترسلها إلى محكمة الاستئناف الضريبية خلال:","o":["عشرة أيام من تاريخ تقديمها","ثلاثين يوماً من تاريخ تقديمها","خمسة عشر يوماً من تاريخ تقديمها","سبعة أيام من تاريخ تقديمها"],"a":0}]},{"n":"49","chapter":"","notes":[],"source":"أ-يستوفى عن الدعوى رسم بنسبة (٣%) من الفرق بين مقدار الضريبة أو المطالبة والمقدار الذي يسلم به المدعي من تلك الضريبة أو المطالبة على أن لا يقل هذا الرسم عن ثلاثين ديناراً بما في ذلك حالة عدم وجود ضريبة أو مطالبة لوقوع المدعي في خسارة وأن لا يزيد على ثلاثمائة دينار وذلك لكل فترة ضريبية عن كل درجة من درجات التقاضي.\nب-لا يترتب على النيابة العامة الضريبية أي رسوم.\nج-يدفع المدعي نصف الرسم المقرر إذا قام بتجديد الدعوى التي أسقطت لأول مرة ويدفع الرسم كاملاً إذا قام بتجديدها بعد إسقاطها مرة ثانية.","title":"رسوم الدعوى الضريبية","memo":"⭐ الرسم (٣%) من الفرق بين الضريبة أو المطالبة والمقدار الذي يسلم به المدعي\n⭐ حد أدنى ثلاثون ديناراً (حتى في حالة الخسارة) وحد أعلى ثلاثمائة دينار، لكل فترة ضريبية عن كل درجة تقاضي\n⭐ لا يترتب على النيابة العامة الضريبية أي رسوم\n⭐ تجديد الدعوى المسقطة لأول مرة: نصف الرسم؛ بعد إسقاطها مرة ثانية: الرسم كاملاً","qs":[{"q":"يستوفى عن الدعوى الضريبية رسم بنسبة:","o":["(٣%) من الفرق بين مقدار الضريبة أو المطالبة والمقدار الذي يسلم به المدعي","(٣%) من كامل مبلغ الضريبة","(٥%) من الفرق المتنازع عليه","(١%) من الفرق المتنازع عليه"],"a":0},{"q":"الحدان الأدنى والأعلى لرسم الدعوى عن كل فترة ضريبية وعن كل درجة تقاضي هما:","o":["ثلاثون ديناراً وثلاثمائة دينار","خمسون ديناراً وخمسمائة دينار","عشرون ديناراً ومائتا دينار","مائة دينار وألف دينار"],"a":0},{"q":"مكلف أسقطت دعواه لأول مرة ثم قام بتجديدها، فإنه يدفع:","o":["نصف الرسم المقرر","الرسم كاملاً","ربع الرسم المقرر","لا يدفع أي رسم"],"a":0}]},{"n":"50","chapter":"","notes":[],"source":"أ-للمدير بناء على تنسيب أي من أعضاء النيابة العامة الضريبية إجراء المصالحة في أي قضية لدى المحكمة وذلك قبل صدور الحكم بها من محكمتي البداية والاستئناف الضريبيتين وعلى المحكمة في أي مرحلة كانت تصديق هذه المصالحة واعتبارها حكماً قطعياً صادراً عنها.\nب-إذا تمت المصالحة وفق أحكام هذا القانون يجوز لطرفي الدعوى أن يطلبا من المحكمة في أي حالة تكون عليها الدعوى إثبات ما اتفقا عليه في محضر الجلسة ويوقع عليه وكيل الطاعن وعضو النيابة العامة الضريبية المختص وعلى المحكمة تصديق هذه المصالحة واعتبارها حكماً قطعياً صادراً عنها.","title":"المصالحة في القضايا أمام المحكمة","memo":"⭐ للمدير بناءً على تنسيب أي من أعضاء النيابة العامة الضريبية إجراء المصالحة في أي قضية قبل صدور الحكم من محكمتي البداية والاستئناف الضريبيتين\n⭐ على المحكمة تصديق المصالحة واعتبارها حكماً قطعياً صادراً عنها\n⭐ يوقع محضر المصالحة وكيل الطاعن وعضو النيابة العامة الضريبية المختص","qs":[{"q":"يملك صلاحية إجراء المصالحة في أي قضية ضريبية لدى المحكمة:","o":["المدير بناءً على تنسيب أي من أعضاء النيابة العامة الضريبية","الوزير بناءً على تنسيب المدير","مجلس الوزراء بناءً على تنسيب الوزير","رئيس محكمة البداية الضريبية"],"a":0},{"q":"إذا تمت المصالحة وفق أحكام القانون، فعلى المحكمة:","o":["تصديقها واعتبارها حكماً قطعياً صادراً عنها","إحالتها إلى المدير لاعتمادها","إحالتها إلى محكمة الاستئناف الضريبية للمصادقة","تصديقها واعتبارها قابلة للطعن خلال ثلاثين يوماً"],"a":0},{"q":"يوقع على محضر الجلسة المتضمن إثبات المصالحة:","o":["وكيل الطاعن وعضو النيابة العامة الضريبية المختص","المكلف والمدير","وكيل الطاعن ورئيس المحكمة","المدقق والمكلف"],"a":0}]},{"n":"51","chapter":"","notes":[],"source":"أ-لا يجوز للمحامي أن ينسحب من الدعوى إلا بإذن من المحكمة وبحضور المدعي أو من يمثله.\nب-لا يجوز للمدعي عزل المحامي إلا بحضور المدعي أو من يمثله للإعلان عن العزل أمام المحكمة.\nج-إذا تم الانسحاب أو العزل على الوجه المبين في الفقرة (أ) أو الفقرة (ب) من هذه المادة فتعطي المحكمة المدعي مهلة خمسة عشر يوماً لتوكيل محام آخر تحت طائلة إسقاط الدعوى.","title":"انسحاب المحامي وعزله","memo":"⭐ لا ينسحب المحامي إلا بإذن المحكمة وبحضور المدعي أو من يمثله\n⭐ لا يعزل المدعي المحامي إلا بحضوره أو من يمثله للإعلان عن العزل أمام المحكمة\n⭐ تمنح المحكمة المدعي مهلة خمسة عشر يوماً لتوكيل محام آخر تحت طائلة إسقاط الدعوى","qs":[{"q":"إذا تم انسحاب المحامي من الدعوى وفق الأصول، تعطي المحكمة المدعي مهلة لتوكيل محام آخر مقدارها:","o":["خمسة عشر يوماً","ثلاثون يوماً","عشرة أيام","سبعة أيام"],"a":0},{"q":"الأثر المترتب على عدم توكيل المدعي محامياً آخر خلال المهلة الممنوحة بعد عزل محاميه:","o":["إسقاط الدعوى","رد الدعوى شكلاً","وقف الدعوى لمدة ستة أشهر","السير في الدعوى بحق المدعي بصفته الشخصية"],"a":0},{"q":"لا يجوز للمحامي أن ينسحب من الدعوى الضريبية إلا:","o":["بإذن من المحكمة وبحضور المدعي أو من يمثله","بموافقة النيابة العامة الضريبية","بإشعار خطي للمدعي قبل خمسة عشر يوماً","بموافقة نقابة المحامين"],"a":0}]},{"n":"52","chapter":"","notes":[],"source":"تحكم المحكمة وحسب مقتضى الحال بالرسوم والمصاريف وأتعاب المحاماة وفقاً لقانون أصول المحاكمات المدنية وقانون نقابة المحامين النظاميين.","title":"الرسوم والمصاريف وأتعاب المحاماة","memo":"⭐ تحكم المحكمة بالرسوم والمصاريف وأتعاب المحاماة وفقاً لقانون أصول المحاكمات المدنية وقانون نقابة المحامين النظاميين","qs":[{"q":"تحكم المحكمة الضريبية بالرسوم والمصاريف وأتعاب المحاماة وفقاً لـ:","o":["قانون أصول المحاكمات المدنية وقانون نقابة المحامين النظاميين","قانون أصول المحاكمات الجزائية فقط","تعليمات يصدرها المدير","نظام يصدره مجلس الوزراء"],"a":0}]},{"n":"53","chapter":"","notes":[],"source":"أ-يتم التبليغ المتعلق بالدعاوى الضريبية وفقا لأحكام قانون أصول المحاكمات المدنية.\nب-تتولى الدائرة تبليغ المكلف خطياً بمقدار الضريبة والمبالغ الأخرى المستحقة عليه وفق قرار المحكمة.","title":"التبليغ في الدعاوى الضريبية","memo":"⭐ التبليغ المتعلق بالدعاوى الضريبية وفقاً لقانون أصول المحاكمات المدنية\n⭐ تتولى الدائرة تبليغ المكلف خطياً بمقدار الضريبة والمبالغ المستحقة وفق قرار المحكمة","qs":[{"q":"يتم التبليغ المتعلق بالدعاوى الضريبية وفقاً لأحكام:","o":["قانون أصول المحاكمات المدنية","قانون أصول المحاكمات الجزائية","قانون المعاملات الإلكترونية","قانون الضريبة العامة على المبيعات"],"a":0},{"q":"الجهة التي تتولى تبليغ المكلف خطياً بمقدار الضريبة والمبالغ الأخرى المستحقة عليه وفق قرار المحكمة هي:","o":["الدائرة","المحكمة","النيابة العامة الضريبية","هيئة الاعتراض"],"a":0}]},{"n":"54","chapter":"","notes":[],"source":"تطبق محكمة البداية الضريبية ومحكمة الاستئناف الضريبية الأصول المنصوص عليها في قانون أصول المحاكمات الجزائية بالقدر الذي لا تتعارض فيه مع أحكام هذا القانون كما تطبق الأصول المنصوص عليها في قانون أصول المحاكمات المدنية بالقدر الذي لا تتعارض فيه مع أحكام هذا القانون.","title":"الأصول الإجرائية الواجبة التطبيق","memo":"⭐ تطبق المحكمتان الضريبيتان أصول المحاكمات الجزائية وأصول المحاكمات المدنية بالقدر الذي لا يتعارض مع أحكام قانون ضريبة الدخل","qs":[{"q":"تطبق محكمة البداية الضريبية ومحكمة الاستئناف الضريبية الأصول المنصوص عليها في قانوني أصول المحاكمات الجزائية والمدنية:","o":["بالقدر الذي لا تتعارض فيه مع أحكام قانون ضريبة الدخل","بشكل مطلق ولو تعارضت مع أحكام قانون ضريبة الدخل","في القضايا الجزائية فقط","في حال عدم وجود تعليمات صادرة عن المدير"],"a":0},{"q":"في حال تعارض حكم في قانون أصول المحاكمات المدنية مع حكم في قانون ضريبة الدخل أمام المحكمة الضريبية، يطبق:","o":["حكم قانون ضريبة الدخل","حكم قانون أصول المحاكمات المدنية","ما تقرره النيابة العامة الضريبية","حكم قانون أصول المحاكمات الجزائية"],"a":0}]},{"n":"55","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-1\n١-تشكل نيابة عامة ضريبية تتبع لرئيس النيابة العامة تتألف من نائب عام ومساعدين له ومدعين عامين وموظفين حسب الحاجة.\n٢-تشكل في الدائرة مديرية القضايا لضريبة الدخل وضريبة المبيعات وأي مبالغ أخرى متعلقة بهما تتبع للمدير تتألف من ممثلي الدائرة الحقوقيين وموظفين حسب الحاجة.\nب-يعين أعضاء النيابة العامة الضريبية بقرار من المجلس القضائي.\nج-على الرغم مما ورد في هذا القانون وقانون الضريبة العامة على المبيعات، يتولى تمثيل الدائرة في قضايا ضريبة الدخل وضريبة المبيعات الحقوقية التي تكون الدائرة طرفاً فيها أمام محكمة البداية الضريبية ومحكمة الاستئناف الضريبية وأي محكمة أخرى مرافعةً ومدافعة وتقديم اللوائح والطلبات والتنسيب للمدير بإجراء المصالحات من يعين خطياً من قبل الوزير من المدققين الحقوقيين الحاصلين على الدرجة الجامعية الأولى في الحقوق حداً أدنى والذين مضى على خدمتهم في الدائرة بعد الحصول على هذا المؤهل مدة لا تقل عن ثلاث سنوات منها مدة لا تقل عن سنة واحدة مدققاً.\nد-لا يشترط لصحة الطعن المقدم لدى محكمة التمييز من النائب العام الضريبي أو من يقوم مقامه أن يبدي رئيس النيابة العامة لدى محكمة التمييز مطالعته بخصوص ذلك الطعن.\nهـ-للمجلس القضائي أن ينتدب أياً من أعضاء النيابة العامة الضريبية المسمين قبل نفاذ أحكام هذا القانون المعدل لممارسة صلاحيات النائب العام الضريبي أو مساعديه أو المدعي العام الضريبي بموجب أحكام هذا القانون مع احتفاظهم بكافة الحقوق والامتيازات المالية المستحقة من الدائرة.\nو-تمارس النيابة العامة الضريبية الصلاحيات المقررة للنيابة العامة وفق أحكام هذا القانون وقانون أصول المحاكمات الجزائية أو الصلاحيات المخولة للمحامي العام المدني.\nز-تقام الدعاوى في الجرائم المنصوص عليها في هذا القانون بناءً على طلب المدير أو بقرار من النائب العام الضريبي.\nح-5\n١-على الرغم مما ورد في أي قانون آخر، تعتبر خدمة الموظف المنصوص عليها في الفقرة (ج) من هذه المادة مدة لا تقل عن خمس سنوات خدمة مقبولة لغايات الإعفاء من شرط التدريب وامتحان القبول المنصوص عليهما في قانون نقابة المحامين النظاميين.\n٢-تعتبر خدمة كل من أشغل إحدى وظائف النيابة العامة الضريبية قبل نفاذ أحكام هذا القانون المعدل وقانون الضريبة العامة على المبيعات رقم (٦) لسنة ١٩٩٤ وتعديلاته وقانون ضريبة الدخل المؤقت رقم (٢٨) لسنة ٢٠٠٩ وخدمة المقدر الحقوقي خلال ممارسته صلاحية مساعد المحامي العام المدني بمقتضى قانون ضريبة الدخل رقم (٥٧) لسنة ١٩٨٥ وتعديلاته وخدمة المدعي العام في القضايا المتعلقة بضريبة المبيعات أمام محكمة الجمارك البدائية ومحكمة الجمارك الاستئنافية من ضمن خدمة الموظف الواردة في البند (١) من هذه الفقرة.","title":"النيابة العامة الضريبية وتمثيل الدائرة","memo":"⭐ تشكل نيابة عامة ضريبية تتبع لرئيس النيابة العامة، ويعين أعضاؤها بقرار من المجلس القضائي\n⭐ مديرية القضايا في الدائرة تتبع للمدير\n⭐ يمثل الدائرة في القضايا الحقوقية من يعينه الوزير خطياً من المدققين الحقوقيين: بكالوريوس حقوق حداً أدنى وخدمة لا تقل عن ثلاث سنوات بعد المؤهل منها سنة واحدة مدققاً\n⭐ تقام دعاوى الجرائم بناءً على طلب المدير أو بقرار من النائب العام الضريبي؛ خدمة لا تقل عن خمس سنوات تعفي من التدريب وامتحان القبول في نقابة المحامين","qs":[{"q":"يعين أعضاء النيابة العامة الضريبية بقرار من:","o":["المجلس القضائي","الوزير","المدير","رئيس النيابة العامة"],"a":0},{"q":"من شروط المدقق الحقوقي الذي يعينه الوزير لتمثيل الدائرة في القضايا الحقوقية أن يكون قد مضى على خدمته في الدائرة بعد حصوله على الدرجة الجامعية الأولى في الحقوق مدة لا تقل عن:","o":["ثلاث سنوات منها سنة واحدة على الأقل مدققاً","خمس سنوات منها سنتان مدققاً","سنتين منها سنة واحدة مدققاً","أربع سنوات منها ثلاث سنوات مدققاً"],"a":0},{"q":"تقام الدعاوى في الجرائم المنصوص عليها في قانون ضريبة الدخل:","o":["بناءً على طلب المدير أو بقرار من النائب العام الضريبي","بقرار من الوزير فقط","بناءً على طلب هيئة الاعتراض","بقرار من مجلس الوزراء"],"a":0},{"q":"تعتبر خدمة الموظف الذي يمثل الدائرة في القضايا الحقوقية خدمة مقبولة لغايات الإعفاء من شرط التدريب وامتحان القبول في نقابة المحامين إذا كانت مدتها لا تقل عن:","o":["خمس سنوات","ثلاث سنوات","سنتين","عشر سنوات"],"a":0}]},{"n":"56","chapter":"","notes":[],"source":"يجوز للمكلف المثول بشخصه أمام المحكمة وتوقيع اللوائح والاستدعاءات المقدمة إليها إذا كان قاضياً عاملاً أو قاضياً سابقاً أو محامياً مزاولاً أو غير مزاول وغيرهم من الأشخاص المعفيين من التدريب بموجب قانون نقابة المحامين النظاميين.","title":"مثول المكلف بشخصه أمام المحكمة","memo":"⭐ يجوز للمكلف المثول بشخصه وتوقيع اللوائح إذا كان قاضياً عاملاً أو سابقاً أو محامياً مزاولاً أو غير مزاول أو من المعفيين من التدريب بموجب قانون نقابة المحامين","qs":[{"q":"يجوز للمكلف المثول بشخصه أمام المحكمة الضريبية وتوقيع اللوائح إذا كان:","o":["محامياً مزاولاً أو غير مزاول","محاسباً قانونياً","مدققاً سابقاً في الدائرة","حاصلاً على شهادة في المحاسبة"],"a":0},{"q":"أي من الأشخاص التالين لا يجيز له النص المثول بشخصه أمام المحكمة الضريبية وتوقيع اللوائح لمجرد صفته؟","o":["المحاسب القانوني","القاضي العامل","القاضي السابق","المعفى من التدريب بموجب قانون نقابة المحامين النظاميين"],"a":0}]},{"n":"57","chapter":"","notes":[],"source":"تعتبر أي من إجراءات المحاكمة التي تمت بموجب أحكام نظام أصول المحاكمات في القضايا الضريبية الحقوقية رقم (٣) لسنة ٢٠١٠ ونظام أصول المحاكمات الضريبية في استئناف وتمييز قضايا ضريبة الدخل رقم (٨) لسنة ٢٠٠٣ صحيحة.","title":"صحة الإجراءات السابقة","memo":"⭐ تعتبر إجراءات المحاكمة التي تمت بموجب نظام أصول المحاكمات في القضايا الضريبية الحقوقية رقم (٣) لسنة ٢٠١٠ ونظام رقم (٨) لسنة ٢٠٠٣ صحيحة","qs":[{"q":"الإجراءات التي تمت بموجب نظام أصول المحاكمات في القضايا الضريبية الحقوقية رقم (٣) لسنة ٢٠١٠ تعتبر:","o":["صحيحة","باطلة","قابلة للإبطال بطلب من المكلف","موقوفة لحين إعادة النظر فيها"],"a":0},{"q":"من الأنظمة التي اعتبر القانون إجراءات المحاكمة التي تمت بموجبها صحيحة:","o":["نظام أصول المحاكمات الضريبية في استئناف وتمييز قضايا ضريبة الدخل رقم (٨) لسنة ٢٠٠٣","نظام الحوافز الضريبية","نظام تبادل المعلومات تنفيذاً للاتفاقيات الدولية","نظام مكافآت موظفي الدائرة"],"a":0}]},{"n":"58","chapter":"","notes":[],"source":"أ-يعتمد عنوان المكلف المسجل الوارد في طلب تسجيله أو في آخر إقرار ضريبي مقدم للدائرة لغايات تبليغه وفق أحكام هذا القانون، ولا يعتد بأي تغيير يطرأ على هذا العنوان ما لم يقم المكلف المسجل بتبليغ الدائرة خلال ثلاثين يوماً من تاريخ هذا التغيير وذلك بموجب كتاب خطي مؤشر عليه من الدائرة.\nب-في حال لم يكن المكلف مسجلاً لدى الدائرة يعتمد عنوانه لممارسة نشاطه والثابت لدى الدائرة لغايات تبليغه وفق أحكام هذا القانون.","title":"عنوان المكلف المعتمد للتبليغ","memo":"⭐ يعتمد عنوان المكلف المسجل الوارد في طلب التسجيل أو في آخر إقرار ضريبي\n⭐ لا يعتد بتغيير العنوان ما لم يبلغ المكلف الدائرة خلال ثلاثين يوماً بكتاب خطي مؤشر عليه من الدائرة\n⭐ المكلف غير المسجل: يعتمد عنوانه لممارسة نشاطه والثابت لدى الدائرة","qs":[{"q":"لا يعتد بأي تغيير يطرأ على عنوان المكلف المسجل ما لم يبلغ الدائرة بذلك خلال:","o":["ثلاثين يوماً من تاريخ التغيير بموجب كتاب خطي مؤشر عليه من الدائرة","خمسة عشر يوماً من تاريخ التغيير","ستين يوماً من تاريخ التغيير","عشرة أيام من تاريخ التغيير"],"a":0},{"q":"يعتمد لغايات تبليغ المكلف المسجل عنوانه الوارد في:","o":["طلب تسجيله أو آخر إقرار ضريبي مقدم للدائرة","أول إقرار ضريبي قدمه للدائرة","سجل الأحوال المدنية","سجل الشركات لدى وزارة الصناعة والتجارة"],"a":0},{"q":"مكلف غير مسجل لدى الدائرة، يعتمد لغايات تبليغه:","o":["عنوانه لممارسة نشاطه والثابت لدى الدائرة","عنوان سكنه الوارد في هويته الشخصية","عنوان وكيله القانوني","لا يجوز تبليغه إلا بالنشر"],"a":0}]},{"n":"59","chapter":"","notes":[],"source":"أ-\n١-تتولى الدائرة تبليغ المكلف بأي مطالبة أو إشعار أو قرار أو مذكرة أو كتاب صادر عنها وفق أحكام هذا القانون بإرساله بالبريد الالكتروني أو بالبريد المسجل أو بوساطة الشركة المرخصة المعتمدة وذلك على العنوان المعتمد لدى الدائرة وفق أحكام المادة (٥٨) من هذا القانون.\n٢-في حال قيام الدائرة بتبليغ المكلف بواسطة البريد الالكتروني تطبق الإجراءات والأحكام المنصوص عليها في قانون المعاملات الالكترونية لهذه الغاية.\n٣-إذا تعذر التبليغ وفقاً لأحكام البند (١) من هذه الفقرة، فيتم إجراء التبليغ بالنشر لمرتين في صحيفتين يوميتين محليتين على أن لا تقل المدة بين النشر الأول والثاني عن عشرة أيام ويعتبر التبليغ في هذه الحالة قانونياً منتجاً لجميع آثاره.\nب-إذا لم يتوافر لدى الدائرة عنوان للمكلف وفق أحكام المادة (٥٨) من هذا القانون فللمدير إجراء التبليغ بالنشر لمرة واحدة على الأقل في صحيفتين يوميتين محليتين.\nج-في جميع الأحوال يجوز للدائرة تبليغ المكلف بالذات أو بوساطة شخص مفوض عنه.\nد-يعتبر التبليغ قانونياً بعد مرور خمسة عشر يوماً على إرساله بالبريد المسجل أو بوساطة الشركة المرخصة المعتمدة إذا كان المكلف مقيماً داخل المملكة أو بعد مرور ثلاثين يوماً على إرساله في البريد المسجل أو بوساطة الشركة المرخصة المعتمدة إذا كان مقيماً خارجها ويكفي لإثبات التبليغ تقديم الدليل على أن الرسالة المحتوية على المادة المراد تبليغها قد عنونت وأرسلت بالبريد المسجل أو بوساطة الشركة المرخصة المعتمدة على العنوان الوارد في المادة (٥٨) من هذا القانون.\nهـ-لا يحتسب اليوم الذي تم فيه التبليغ لغايات احتساب المدد المنصوص عليها في هذا القانون.\nو-لهيئة الاعتراض أو المحكمة بناءً على طلب المكلف المستند إلى أسباب مبررة عدم اعتبار النشر أو تعذر التبليغ بمثابة تبليغ له، وفي هذه الحالة يسري ميعاد جديد اعتباراً من تاريخ تبليغ المكلف قرار المدقق أو الهيئة بقبول الطلب.","title":"طرق التبليغ ومواعيده","memo":"⭐ التبليغ بالبريد الإلكتروني أو المسجل أو الشركة المرخصة على العنوان المعتمد؛ وإذا تعذر فبالنشر مرتين في صحيفتين يوميتين محليتين بفاصل لا يقل عن عشرة أيام\n⭐ إذا لم يتوافر عنوان: للمدير التبليغ بالنشر لمرة واحدة على الأقل في صحيفتين يوميتين محليتين\n⭐ يعتبر التبليغ قانونياً بعد خمسة عشر يوماً للمقيم داخل المملكة وثلاثين يوماً للمقيم خارجها\n⭐ لا يحتسب يوم التبليغ ضمن المدد","qs":[{"q":"يعتبر التبليغ المرسل بالبريد المسجل قانونياً للمكلف المقيم داخل المملكة بعد مرور:","o":["خمسة عشر يوماً على إرساله","ثلاثين يوماً على إرساله","عشرة أيام على إرساله","سبعة أيام على إرساله"],"a":0},{"q":"إذا تعذر تبليغ المكلف بالبريد على العنوان المعتمد، يتم التبليغ بالنشر:","o":["لمرتين في صحيفتين يوميتين محليتين على ألا تقل المدة بين النشرين عن عشرة أيام","لمرة واحدة في صحيفة يومية محلية","لمرتين في صحيفة واحدة بفاصل خمسة عشر يوماً","لثلاث مرات في صحيفتين يوميتين محليتين"],"a":0},{"q":"مكلف مقيم خارج المملكة أرسل إليه إشعار بوساطة شركة مرخصة معتمدة، فيعتبر التبليغ قانونياً بعد مرور:","o":["ثلاثين يوماً على إرساله","خمسة عشر يوماً على إرساله","ستين يوماً على إرساله","تسعين يوماً على إرساله"],"a":0},{"q":"يجوز عدم اعتبار النشر أو تعذر التبليغ بمثابة تبليغ للمكلف بناءً على طلبه المستند إلى أسباب مبررة، بقرار من:","o":["هيئة الاعتراض أو المحكمة","الوزير","مجلس الوزراء","المدعي العام الضريبي"],"a":0}]},{"n":"60","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-على كل مصفٍ لأي شركة أو تركة أو وكيل تفليسة أو أي شخص مسؤول عن أي تصفية مشابهة أو تسوية من أي نوع أن يبلغ المدير خطياً ببدء إجراءات التصفية أو بشهر الإفلاس أو أي إجراءات أخرى حسب مقتضى الحال لبيان المبالغ المستحقة للدائرة وتثبيتها وفي حال التخلف عن ذلك يعتبر كل من أولئك الأشخاص مسؤولاً مسؤولية مباشرة وشخصية عن دفع تلك المبالغ وفق أحكام هذا القانون على أن لا يعفي هذا الحكم الورثة من دفع تلك المبالغ من أي أموال منقولة أو غير منقولة آلت إليهم من التركة.\nب-1\n١-على كل شخص اعتباري الحصول على براءة ذمة من الدائرة قبل بيع أو التنازل عن حصصه أو أسهمه أو أي جزء منها داخل المملكة ويستثنى من ذلك الأسهم المتداولة في السوق المالي المعرف بموجب قانون الأوراق المالية.\n٢-تسري أحكام البند (١) من هذه الفقرة على الشخص غير الأردني.","title":"التزامات المصفين وبراءة الذمة","memo":"⭐ على المصفي ووكيل التفليسة إبلاغ المدير خطياً ببدء التصفية أو شهر الإفلاس، وإلا أصبح مسؤولاً مسؤولية مباشرة وشخصية عن دفع المبالغ\n⭐ لا يعفي ذلك الورثة من الدفع مما آل إليهم من التركة\n⭐ على الشخص الاعتباري الحصول على براءة ذمة قبل بيع أو التنازل عن حصصه أو أسهمه، باستثناء الأسهم المتداولة في السوق المالي، ويسري ذلك على غير الأردني","qs":[{"q":"الأثر المترتب على تخلف مصفي الشركة عن تبليغ المدير خطياً ببدء إجراءات التصفية:","o":["يصبح مسؤولاً مسؤولية مباشرة وشخصية عن دفع المبالغ المستحقة للدائرة","يعاقب بالحبس مدة لا تقل عن سنة","تبطل إجراءات التصفية حكماً","تفرض عليه ضريبة مضافة مقدارها مائة دينار"],"a":0},{"q":"يستثنى من وجوب حصول الشخص الاعتباري على براءة ذمة قبل بيع حصصه أو أسهمه:","o":["الأسهم المتداولة في السوق المالي","الحصص المملوكة لشخص غير أردني","الأسهم المبيعة داخل المملكة","حصص الشركات ذات المسؤولية المحدودة"],"a":0},{"q":"تسري أحكام وجوب الحصول على براءة ذمة قبل بيع الحصص أو الأسهم على الشخص غير الأردني:","o":["نعم، تسري عليه","لا تسري عليه مطلقاً","تسري عليه إذا كان مقيماً فقط","تسري عليه بقرار من الوزير"],"a":0}]},{"n":"61","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-للمدير أو لأي موظف يفوضه خطياً طلب المعلومات الضرورية لتنفيذ أحكام هذا القانون من أي شخص أو جهة كانت ويشترط في ذلك أن لا يلزم موظفو الحكومة والمؤسسات الرسمية العامة والمؤسسات العامة والبلديات بإفشاء أي تفاصيل يكونون ملزمين بحكم القانون بالمحافظة عليها وكتمانها كما يشترط عدم المساس بسرية العمليات المصرفية ويعتبر كل من يمتنع عن إعطاء هذه المعلومات أنه ارتكب جرماً يعاقب عليه بالعقوبات المنصوص عليها في المادة (٦٦) من هذا القانون.\nب-\n١-يعتبر المدير والمدقق وموظفو الدائرة المفوضون خطياً منه بأي من الصلاحيات الواردة في هذا القانون أثناء قيامهم بأعمالهم من رجال الضابطة العدلية في حدود اختصاصهم ولهم الحق في الدخول إلى أي مكان يجري مزاولة عمل فيه وفحص البضائع المخزونة والنقد والآلات والماكنات والدفاتر والقيود والمستندات الأخرى المتعلقة بذلك العمل كما يجوز لهم في الحالات التي تستدعي ذلك ضبط هذه الدفاتر والسجلات والحسابات والمستندات والاحتفاظ بها لمدة لا تزيد على (١٨٠) يوماً من تاريخ ضبطها لتنفيذ أحكام هذا القانون كما يحق لهم أن يقوموا بالكشف على وسائط النقل والبضائع وعلى الدائرة تسليم المكلف بناءً على طلبه خلال مهلة أقصاها (١٥) يوماً من تاريخ الضبط صورة طبق الأصل عن كافة المضبوطات الورقية ونسخ عن أي برامج على الحاسوب تلزم لتسيير عمله وفي حالة رفض الدائرة تسليم المكلف ما ورد بالبينة أعلاه، للمكلف اللجوء إلى المحكمة بطلب مستعجل لإلزام الدائرة بتسليم الصور والنسخ المطلوبة أو تسليم المضبوطات وفق مقتضى الحال.\n٢-على السلطات الرسمية أن تقدم لموظفي الدائرة المساعدة اللازمة لتمكينهم من القيام بأعمالهم.\nج-لا يجوز تفتيش بيوت السكن إلا وفق الإجراءات المنصوص عليها في قانون أصول المحاكمات الجزائية.\nد-على الدائرة توكيل محام للدفاع عن أي من موظفيها المكلفين بتنفيذ أحكام هذا القانون في الدعاوى التي تقام عليهم بسبب قيامهم بمهامهم على أن يدفع الموظف المبالغ التي تكبدتها الدائرة في حال إدانته.\nهـ-مع مراعاة أحكام الفقرة (ز) من هذه المادة وعلى الرغم مما ورد في هذا القانون أو أي تشريع آخر، للمدير أو من يفوضه خطياً الطلب من أي جهة من القطاعين العام والخاص تزويد الدائرة بشكل إلكتروني أو غير إلكتروني بأي معلومات يتطلبها عمل الدائرة على أن تلتزم هذه الجهات بالربط مع الدائرة على قواعد البيانات الإلكترونية التابعة لكل منها ويشترط في ذلك عدم المساس بسرية العمليات المصرفية.\nو-يتم تحديد أحكام وشروط وإجراءات تبادل المعلومات والإفصاح في التقارير المتبادلة تنفيذاً للاتفاقيات الدولية التي صادقت عليها المملكة بمقتضى نظام يصدر لهذه الغاية.\nز-على الرغم مما ورد في هذا القانون أو أي تشريع آخر، للمدعي العام الضريبي بقرار من المدير أن يطلب من أي جهة كانت أي معلومات ضرورية لتنفيذ أحكام هذا القانون إذا توافرت لديه قرائن على وجود تهرب ضريبي، أو لغايات تنفيذ اتفاقات تجنب الازدواج الضريبي ومنع التهرب من الضرائب أو الاتفاقيات الدولية.\nح-على الرغم مما ورد في الفقرات (هـ) و(و) و(ز) من هذه المادة، تتم المحافظة على السرية المصرفية المنصوص عليها في قانون البنوك ولا يتم المساس بها إلا بقرار قضائي.","title":"طلب المعلومات وصلاحيات الضابطة العدلية","memo":"⭐ للمدير أو الموظف المفوض خطياً طلب المعلومات من أي جهة مع عدم المساس بسرية العمليات المصرفية؛ والممتنع يعاقب بعقوبة المادة (٦٦)\n⭐ المدير والمدقق والموظفون المفوضون من رجال الضابطة العدلية، ولهم ضبط الدفاتر والاحتفاظ بها مدة لا تزيد على (١٨٠) يوماً، وتسليم المكلف صوراً خلال (١٥) يوماً\n⭐ لا يجوز تفتيش بيوت السكن إلا وفق قانون أصول المحاكمات الجزائية\n⭐ السرية المصرفية لا يتم المساس بها إلا بقرار قضائي","qs":[{"q":"يجوز لموظفي الدائرة المفوضين ضبط الدفاتر والسجلات والاحتفاظ بها لمدة لا تزيد على:","o":["(١٨٠) يوماً من تاريخ ضبطها","(٩٠) يوماً من تاريخ ضبطها","(٣٦٥) يوماً من تاريخ ضبطها","(٦٠) يوماً من تاريخ ضبطها"],"a":0},{"q":"على الدائرة تسليم المكلف بناءً على طلبه صورة طبق الأصل عن المضبوطات الورقية خلال مهلة أقصاها:","o":["(١٥) يوماً من تاريخ الضبط","(٣٠) يوماً من تاريخ الضبط","(١٠) أيام من تاريخ الضبط","(٧) أيام من تاريخ الضبط"],"a":0},{"q":"لا يتم المساس بالسرية المصرفية المنصوص عليها في قانون البنوك إلا:","o":["بقرار قضائي","بقرار من المدير","بقرار من المدعي العام الضريبي","بقرار من الوزير"],"a":0},{"q":"يجوز تفتيش بيوت السكن من قبل موظفي الدائرة:","o":["وفق الإجراءات المنصوص عليها في قانون أصول المحاكمات الجزائية","في أي وقت بصفتهم من رجال الضابطة العدلية","بإذن خطي من المدير","بموافقة المدقق المختص"],"a":0}]},{"n":"62","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-يترتب على كل من يضطلع بواجب رسمي لتنفيذ أحكام هذا القانون:\n١-أن يعتبر المستندات والسجلات والمعلومات والإقرارات الضريبية وقرارات التدقيق والتقدير ونسخها التي يطلع عليها المتعلقة بدخل أي شخص أو مفردات أي دخل أنها سرية ومكتومة.\n٢-أن يقدم تصريحاً ويوقع عليه للمحافظة على الأسرار حسب الصيغة التي يضعها المدير.\n٣-أن يقدم إلى المدير عند تعيينه كشفاً بأمواله المنقولة وغير المنقولة ومصادر دخله وأموال زوجه وأولاده القاصرين كما يترتب عليه في مطلع كل سنة لاحقة أن يبين أي زيادة طرأت على تلك الأموال.\nب-لا يكلف الشخص المضطلع بتنفيذ أي من أحكام هذا القانون بأن يبرز أي مستند أو إقرار ضريبي أو قرار تقدير أو قرار تدقيق أو أي نسخ منها في أي محكمة غير المحكمة المختصة أو بأن يفشي أمام أي محكمة أو بأن يبلغها أي أمر أو شيء مما يكون قد اطلع عليه في سياق اضطلاعه بواجباته بمقتضى هذا القانون إلا ما كان ضرورياً لتنفيذ أحكامه حسبما يقرره المدير في كل حالة تنشأ بمقتضى هذه الفقرة أو من أجل تعقب أي جرم.\nج-يعاقب بغرامة لا تقل عن (١٠٠٠) ألف دينار ولا تزيد على (٥٠٠٠) خمسة آلاف دينار أو بالحبس مدة لا تقل عن أربعة أشهر ولا تزيد على سنة أو بكلتا هاتين العقوبتين كل من وجدت في حيازته أو تحت رقابته أي مستندات أو إقرارات ضريبية أو قرارات تقدير أو قرار تدقيق أو نسخها تتعلق بدخل أي شخص أو مفردات هذا الدخل وبلغ أو حاول تبليغ تلك المعلومات أو أي شيء ورد في أي منها في أي وقت لأي شخص غير الشخص الذي يخوله القانون تبليغها إليه أو لأي غاية أخرى خلاف الغايات الواردة في هذا القانون.","title":"سرية المعلومات الضريبية","memo":"⭐ على كل من يضطلع بواجب رسمي اعتبار المعلومات سرية، وتقديم تصريح بالمحافظة على الأسرار، وكشف بأمواله وأموال زوجه وأولاده القاصرين عند تعيينه ومطلع كل سنة\n⭐ إفشاء المعلومات: غرامة من (١٠٠٠) إلى (٥٠٠٠) دينار أو الحبس من أربعة أشهر إلى سنة أو كلتاهما","qs":[{"q":"عقوبة من بلغ معلومات تتعلق بدخل أي شخص من الإقرارات أو قرارات التقدير لشخص غير مخول قانوناً:","o":["غرامة لا تقل عن (١٠٠٠) دينار ولا تزيد على (٥٠٠٠) دينار أو الحبس من أربعة أشهر إلى سنة أو كلتاهما","غرامة لا تقل عن (٢٠٠) دينار ولا تزيد على (٥٠٠) دينار","الحبس من سنة إلى سنتين فقط","غرامة تعويضية تعادل مثل الفرق الضريبي"],"a":0},{"q":"يترتب على من يضطلع بواجب رسمي لتنفيذ قانون ضريبة الدخل أن يقدم إلى المدير عند تعيينه كشفاً بأمواله المنقولة وغير المنقولة، وأن يبين أي زيادة تطرأ عليها:","o":["في مطلع كل سنة لاحقة","كل خمس سنوات","عند انتهاء خدمته فقط","كل ثلاث سنوات"],"a":0},{"q":"جميع ما يلي من التزامات من يضطلع بواجب رسمي لتنفيذ القانون باستثناء:","o":["تقديم كشف بأموال والديه وإخوته","اعتبار الإقرارات وقرارات التدقيق والتقدير سرية ومكتومة","تقديم تصريح موقع للمحافظة على الأسرار حسب صيغة المدير","تقديم كشف بأموال زوجه وأولاده القاصرين"],"a":0}]},{"n":"63","chapter":"","notes":[],"source":"تفرض على المكلف الذي يتأخر عن تقديم الإقرار بموجب أحكام هذا القانون غرامة وبحد أقصى مقدارها مائة دينار للشخص الطبيعي وثلاثمائة دينار للشخص الاعتباري باستثناء الشركات المساهمة العامة والخاصة وألف دينار للشركات المساهمة العامة والخاصة.","title":"غرامة التأخر عن تقديم الإقرار","memo":"⭐ غرامة بحد أقصى: مائة دينار للشخص الطبيعي، ثلاثمائة دينار للشخص الاعتباري (باستثناء الشركات المساهمة)، ألف دينار للشركات المساهمة العامة والخاصة","qs":[{"q":"الحد الأقصى لغرامة تأخر الشخص الطبيعي عن تقديم الإقرار الضريبي:","o":["مائة دينار","ثلاثمائة دينار","ألف دينار","خمسمائة دينار"],"a":0},{"q":"شركة مساهمة خاصة تأخرت عن تقديم إقرارها الضريبي، فإن الحد الأقصى للغرامة المفروضة عليها:","o":["ألف دينار","ثلاثمائة دينار","مائة دينار","خمسمائة دينار"],"a":0},{"q":"شركة ذات مسؤولية محدودة تأخرت عن تقديم إقرارها الضريبي، فإن الحد الأقصى للغرامة:","o":["ثلاثمائة دينار","مائة دينار","ألف دينار","مائتا دينار"],"a":0}]},{"n":"64","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-تفرض ضريبة مضافة لا تقل عن مائتي دينار ولا تزيد على خمسمائة دينار في أي من الحالات التالية:\n١-إذا تخلف المكلف عن مسك السجلات أو المستندات وفق أحكام هذا القانون.\n٢-إذا تخلف المكلف عن التسجيل لدى الدائرة وفق أحكام هذا القانون.\n٣-عدم قيام المحاسب القانوني بتزويد الدائرة ببيان بأسماء عملائه وعناوينهم وفق أحكام المادة (٢٥) من هذا القانون.\n٤-عدم إعلام الدائرة بأي تغيرات طرأت على البيانات الواردة في طلب التسجيل خلال الموعد المحدد لذلك.\n٥-التخلف عن اقتطاع الضريبة وتوريدها للدائرة وفق أحكام هذا القانون.\n٦-الامتناع عن تقديم السجلات والمستندات التي يتوجب الاحتفاظ بها وفق أحكام هذا القانون.\n٧-الامتناع عن إصدار فاتورة أو مستند عند طلبها من قبل المستفيد.\n٨-إذا ثبت وجود نقص في الإقرار الضريبي أو زيادة في مبلغ تقاص أو خصم ضريبة مدفوعة على الحساب وفقاً للإقرار الضريبي المقدم من المكلف إذا كانت نسبة الفرق لا تقل عن (٢٥%) من الضريبة المستحقة أو مبلغ التقاص المسموح به حسب مقتضى الحال.\nب-تضاعف المبالغ المنصوص عليها في الفقرة (أ) من هذه المادة في حال التكرار.","title":"الضريبة المضافة على المخالفات","memo":"⭐ ضريبة مضافة لا تقل عن مائتي دينار ولا تزيد على خمسمائة دينار\n⭐ حالاتها: عدم مسك السجلات، عدم التسجيل، عدم تزويد المحاسب القانوني الدائرة بأسماء عملائه، عدم الإعلام بالتغيرات، عدم الاقتطاع والتوريد، الامتناع عن تقديم السجلات أو إصدار الفاتورة\n⭐ النقص في الإقرار إذا كانت نسبة الفرق لا تقل عن (٢٥%) من الضريبة المستحقة\n⭐ تضاعف المبالغ في حال التكرار","qs":[{"q":"تفرض في حالة تخلف المكلف عن مسك السجلات وفق أحكام القانون ضريبة مضافة:","o":["لا تقل عن مائتي دينار ولا تزيد على خمسمائة دينار","لا تقل عن مائة دينار ولا تزيد على ثلاثمائة دينار","لا تقل عن ألف دينار ولا تزيد على خمسة آلاف دينار","تعادل مثل الفرق الضريبي"],"a":0},{"q":"تفرض الضريبة المضافة في حال ثبوت نقص في الإقرار الضريبي إذا كانت نسبة الفرق لا تقل عن:","o":["(٢٥%) من الضريبة المستحقة","(١٠%) من الضريبة المستحقة","(٥٠%) من الضريبة المستحقة","(٢٠%) من الضريبة المستحقة"],"a":0},{"q":"مكلف فرضت عليه ضريبة مضافة لامتناعه عن إصدار فاتورة، ثم كرر المخالفة، فإن المبلغ:","o":["يضاعف","يبقى كما هو","يزاد بنسبة (٢٥%)","يستبدل بعقوبة الحبس"],"a":0},{"q":"جميع ما يلي من حالات فرض الضريبة المضافة باستثناء:","o":["إتلاف السجلات قصداً قبل انقضاء مدة الاحتفاظ بها","التخلف عن التسجيل لدى الدائرة","عدم قيام المحاسب القانوني بتزويد الدائرة ببيان بأسماء عملائه","الامتناع عن إصدار فاتورة عند طلبها من المستفيد"],"a":0}]},{"n":"65","chapter":"","notes":[],"source":"أ-على المكلف دفع المبالغ المفروضة عليه بمقتضى أحكام المادتين (٦٣) و(٦٤) من هذا القانون، خلال ثلاثين يوماً من تاريخ تبليغه ويجوز له الاعتراض لدى الوزير خلال هذه المدة، والذي له تثبيت المبلغ أو تخفيضه أو إلغاؤه إذا تبين له ما يبرر ذلك.\nب-يكون قرار الوزير الصادر بمقتضى أحكام الفقرة (أ) من هذه المادة قابلاً للطعن لدى المحكمة خلال ثلاثين يوماً من تاريخ تبليغه وللمحكمة أن تثبت المبلغ أو تعدله أو تلغيه.","title":"دفع الغرامات والاعتراض عليها","memo":"⭐ على المكلف دفع مبالغ المادتين (٦٣) و(٦٤) خلال ثلاثين يوماً من تبليغه، وله الاعتراض لدى الوزير خلال المدة نفسها\n⭐ للوزير تثبيت المبلغ أو تخفيضه أو إلغاؤه، وقراره قابل للطعن لدى المحكمة خلال ثلاثين يوماً","qs":[{"q":"يعترض المكلف على الغرامة المفروضة بسبب التأخر عن تقديم الإقرار لدى:","o":["الوزير","المدير","هيئة الاعتراض","محكمة الاستئناف الضريبية"],"a":0},{"q":"يكون قرار الوزير في الاعتراض على الضريبة المضافة قابلاً للطعن لدى المحكمة خلال:","o":["ثلاثين يوماً من تاريخ تبليغه","خمسة عشر يوماً من تاريخ تبليغه","ستين يوماً من تاريخ صدوره","عشرة أيام من تاريخ تبليغه"],"a":0},{"q":"على المكلف دفع المبالغ المفروضة عليه بموجب المادتين (٦٣) و(٦٤) خلال:","o":["ثلاثين يوماً من تاريخ تبليغه","ستين يوماً من تاريخ تبليغه","خمسة عشر يوماً من تاريخ تبليغه","تسعين يوماً من تاريخ تبليغه"],"a":0}]},{"n":"66","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-يعاقب بغرامة تعويضية تعادل مثل الفرق الضريبي كل من قام بالتهرب الضريبي أو حاول التهرب أو ساعد أو حرض غيره على التهرب من الضريبة بأن أتى أي فعل من الأفعال التالية:\n١-قدم الإقرار الضريبي بالاستناد إلى سجلات أو مستندات مصطنعة أو ضمّنه بيانات تخالف ما هو ثابت في السجلات أو المستندات التي أخفاها مع علمه بذلك.\n٢-قدم الإقرار الضريبي على أساس عدم وجود سجلات أو مستندات وضمّنه بيانات تخالف ما هو ثابت لديه من سجلات أو مستندات أخفاها.\n٣-أتلف قصداً السجلات أو المستندات ذات الصلة بالضريبة قبل انقضاء المدة المحددة للاحتفاظ بها وفق أحكام هذا القانون.\n٤-اصطنع أو غيّر فواتير الشراء أو البيع أو غيرها من المستندات لإيهام الدائرة بقلة الأرباح أو زيادة الخسائر.\n٥-أخفى نشاطاً أو جزءً منه مما يخضع للضريبة.\n٦-اقتطع مقدار الضريبة وفق أحكام هذا القانون ولم يوردها للدائرة خلال ثلاثين يوماً من تاريخ دفعها.\n٧-لم يصدر فاتورة أصولية.\nب-إضافة إلى الغرامة المنصوص عليها في الفقرة (أ) من هذه المادة، تكون العقوبة في حال تكرار ارتكاب أي من الجرائم المنصوص عليها فيها على النحو التالي:\n١-الحبس مدة لا تقل عن أربعة أشهر ولا تزيد على سنة واحدة في حال ارتكاب أي من الجرائم للمرة الثانية.\n٢-الحبس مدة لا تقل عن سنة واحدة ولا تزيد على سنتين في حال ارتكاب أي من الجرائم للمرة الثالثة.\n٣-الحبس مدة لا تقل عن سنتين ولا تزيد على ثلاث سنوات في حال ارتكاب أي من الجرائم للمرة الرابعة وما يليها.\nج-لا يجوز للمحكمة الأخذ بالأسباب المخففة التقديرية فيما يتعلق بالعقوبات المنصوص عليها في البندين (٢) و(٣) من الفقرة (ب) من هذه المادة.\nد-على الرغم مما ورد في أي تشريع آخر:\n١-على الدائرة نشر الأحكام القضائية المكتسبة الدرجة القطعية والصادرة في قضايا التهرب الضريبي بالصحف ووسائل الإعلام بما في ذلك النشر في الوسائل الإلكترونية المتاحة.\n٢-تكون مدة التقادم للجرائم المرتكبة خلافاً لأحكام هذا القانون والعقوبات المفروضة بموجبه ثلاث سنوات.","title":"جرائم التهرب الضريبي وعقوباتها","memo":"⭐ التهرب أو محاولته أو المساعدة أو التحريض عليه: غرامة تعويضية تعادل مثل الفرق الضريبي\n⭐ التكرار: المرة الثانية حبس ٤ أشهر–سنة، الثالثة سنة–سنتان، الرابعة وما يليها سنتان–ثلاث سنوات؛ ولا أسباب مخففة في الثالثة والرابعة\n⭐ من صوره: اقتطاع الضريبة وعدم توريدها خلال ثلاثين يوماً من دفعها، وعدم إصدار فاتورة أصولية\n⭐ تنشر الأحكام القطعية في قضايا التهرب، ومدة التقادم ثلاث سنوات","qs":[{"q":"يعاقب من قام بالتهرب الضريبي لأول مرة بغرامة تعويضية تعادل:","o":["مثل الفرق الضريبي","مثلي الفرق الضريبي","نصف الفرق الضريبي","ثلاثة أمثال الفرق الضريبي"],"a":0},{"q":"مكلف ارتكب جريمة تهرب ضريبي للمرة الثالثة، فإن عقوبته إضافة إلى الغرامة:","o":["الحبس مدة لا تقل عن سنة واحدة ولا تزيد على سنتين","الحبس مدة لا تقل عن أربعة أشهر ولا تزيد على سنة","الحبس مدة لا تقل عن سنتين ولا تزيد على ثلاث سنوات","الحبس مدة لا تقل عن ثلاث سنوات ولا تزيد على خمس سنوات"],"a":0},{"q":"مدة التقادم للجرائم المرتكبة خلافاً لأحكام قانون ضريبة الدخل والعقوبات المفروضة بموجبه:","o":["ثلاث سنوات","خمس سنوات","أربع سنوات","سنتان"],"a":0},{"q":"يعد مرتكباً لجريمة التهرب الضريبي من اقتطع مقدار الضريبة ولم يوردها للدائرة خلال:","o":["ثلاثين يوماً من تاريخ دفعها","خمسة عشر يوماً من تاريخ دفعها","ستين يوماً من تاريخ دفعها","تسعين يوماً من تاريخ دفعها"],"a":0}]},{"n":"67","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨.","عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-يتحمل المحاسب القانوني المسؤولية عن المصادقة على بيانات مالية غير مطابقة للواقع بشكل جوهري أو تخالف أحكام هذا القانون أو معايير المحاسبة الدولية والقوانين والأنظمة النافذة المفعول سواءً كان ذلك ناجماً عن خطأ متعمد أو عن عمل جرمي أو عن إهمال جسيم وفي هذه الحالة يعتبر المحاسب القانوني مرتكباً لجرم ويعاقب بالعقوبة المنصوص عليها في المادة (٦٦) من هذا القانون.\nب-يتحمل المسؤولية أي شخص قام عمداً بتصميم أو إعداد برنامج أو نظام محاسبي لأي مكلف أو لأي شخص أو مكنه منه بحيث يكون معداً لغرض تنظيم السجلات والدفاتر والبيانات والمعلومات المالية غير المطابقة للواقع بشكل جوهري وفي هذه الحال يعتبر الشخص مرتكباً لجرم ويعاقب بالعقوبة المنصوص عليها في المادة (٦٦) من هذا القانون، ويعاقب كل من ساعد أو حرض غيره على ارتكاب هذا الفعل بعقوبة الفاعل الأصلي.","title":"مسؤولية المحاسب القانوني ومصمم البرامج","memo":"⭐ يسأل المحاسب القانوني عن المصادقة على بيانات مالية غير مطابقة للواقع بشكل جوهري سواء عن خطأ متعمد أو عمل جرمي أو إهمال جسيم، ويعاقب بعقوبة المادة (٦٦)\n⭐ من صمم عمداً برنامجاً أو نظاماً محاسبياً لتنظيم سجلات غير مطابقة للواقع يعاقب بعقوبة المادة (٦٦)، والمساعد أو المحرض بعقوبة الفاعل الأصلي","qs":[{"q":"يعاقب المحاسب القانوني الذي صادق على بيانات مالية غير مطابقة للواقع بشكل جوهري نتيجة إهمال جسيم بـ:","o":["العقوبة المنصوص عليها في المادة (٦٦) من القانون","الضريبة المضافة المنصوص عليها في المادة (٦٤)","الغرامة المنصوص عليها في المادة (٦٣)","المنع من مراجعة الدائرة فقط"],"a":0},{"q":"من ساعد أو حرض غيره على تصميم نظام محاسبي معد لتنظيم سجلات غير مطابقة للواقع بشكل جوهري يعاقب بـ:","o":["عقوبة الفاعل الأصلي","نصف عقوبة الفاعل الأصلي","غرامة لا تزيد على خمسمائة دينار","لا يعاقب ما لم يكن هو المصمم"],"a":0},{"q":"لا تتحقق مسؤولية المحاسب القانوني الجزائية وفق المادة (٦٧) عن المصادقة على بيانات غير مطابقة للواقع إذا كانت ناجمة عن:","o":["خطأ يسير غير جسيم","خطأ متعمد","عمل جرمي","إهمال جسيم"],"a":0}]},{"n":"68","chapter":"","notes":[],"source":"لا يحول تطبيق أحكام هذا القانون دون تطبيق أي عقوبة أشد ورد النص عليها في أي تشريع آخر.","title":"تطبيق العقوبة الأشد","memo":"⭐ لا يحول تطبيق قانون ضريبة الدخل دون تطبيق أي عقوبة أشد واردة في أي تشريع آخر","qs":[{"q":"إذا نص تشريع آخر على عقوبة أشد من العقوبة الواردة في قانون ضريبة الدخل عن الفعل نفسه، فإن:","o":["تطبيق قانون ضريبة الدخل لا يحول دون تطبيق العقوبة الأشد","تطبق عقوبة قانون ضريبة الدخل حصراً","تطبق العقوبة الأخف","يعود تحديد العقوبة إلى المدير"],"a":0}]},{"n":"69","chapter":"","notes":[],"source":"إن فرض أي عقوبة أو غرامة بمقتضى أحكام هذا القانون لا يعفي أي شخص من مسؤولية دفع الضريبة والمبالغ والغرامات المترتبة عليه وفق أحكام هذا القانون.","title":"العقوبة لا تعفي من الضريبة","memo":"⭐ فرض أي عقوبة أو غرامة لا يعفي من مسؤولية دفع الضريبة والمبالغ والغرامات المترتبة","qs":[{"q":"مكلف فرضت عليه عقوبة بسبب مخالفة أحكام قانون ضريبة الدخل، فإن ذلك:","o":["لا يعفيه من مسؤولية دفع الضريبة والمبالغ والغرامات المترتبة عليه","يعفيه من دفع الضريبة","يعفيه من الغرامات دون الضريبة","يعفيه من نصف الضريبة المستحقة"],"a":0},{"q":"صدر حكم بحبس مكلف بسبب تكرار التهرب الضريبي، فإن الضريبة والغرامات المترتبة عليه:","o":["تبقى مستحقة الدفع ولا يعفيه الحكم منها","تسقط بتنفيذ عقوبة الحبس","تسقط بعد مرور ثلاث سنوات على الحكم","يخفض نصفها بقوة القانون"],"a":0}]},{"n":"70","chapter":"","notes":[],"source":"أ-للوزير بتنسيب من المدير بناءً على توصية لجنة مشكلة لهذه الغاية من الدائرة وديوان المحاسبة منع أي شخص طبيعي من مراجعة الدائرة في أي قضية أو عمل خلاف قضيته الشخصية إذا ثبت أنه خلال مراجعاته وتعامله مع الدائرة ارتكب ما من شأنه تعطيل سير العمل وفق الأصول أو التحايل على هذا القانون، وله أن يقرر عدم قبول الدائرة للحسابات التي يعدها أو يدققها ذلك الشخص إذا كان محاسباً أو محاسباً قانونياً وذلك لمدة لا تزيد على ثلاث سنوات.\nب-يحظر على المدقق الذي انتهت خدمته في الدائرة مراجعة الدائرة وإبداء رأي أو مشورة في أي قضية سبق له تدقيقها أو تقديرها.\nج-\n١-على الرغم مما ورد في أي قانون آخر للمكلف أن ينيب عنه شخصاً آخر لتمثيله لدى الدائرة في أي إجراء من إجراءات تدقيق الضريبة على دخله وتقديرها وتحصيلها بما فيها تقديم الإقرار الضريبي وإجراءات التبلغ والتبليغ.\n٢-يصدر الوزير بتنسيب من المدير التعليمات التنفيذية لتحديد أحكام الإنابة والتمثيل لدى الدائرة والشروط والإجراءات الخاصة بذلك.","title":"منع المراجعة والإنابة لدى الدائرة","memo":"⭐ للوزير بتنسيب المدير بناءً على توصية لجنة من الدائرة وديوان المحاسبة منع شخص طبيعي من المراجعة وعدم قبول حساباته لمدة لا تزيد على ثلاث سنوات\n⭐ يحظر على المدقق بعد انتهاء خدمته مراجعة الدائرة في قضية سبق له تدقيقها أو تقديرها\n⭐ للمكلف إنابة غيره لتمثيله لدى الدائرة، ويصدر الوزير بتنسيب المدير التعليمات التنفيذية للإنابة","qs":[{"q":"يملك صلاحية منع شخص طبيعي من مراجعة الدائرة لتعطيله سير العمل أو التحايل على القانون:","o":["الوزير بتنسيب من المدير بناءً على توصية لجنة من الدائرة وديوان المحاسبة","المدير بناءً على توصية المدقق","مجلس الوزراء بتنسيب الوزير","المحكمة الضريبية بناءً على طلب الدائرة"],"a":0},{"q":"الحد الأقصى لمدة عدم قبول الدائرة للحسابات التي يعدها أو يدققها محاسب قانوني ثبت تحايله على القانون:","o":["ثلاث سنوات","سنتان","خمس سنوات","سنة واحدة"],"a":0},{"q":"مدقق انتهت خدمته في الدائرة، فإنه يحظر عليه:","o":["مراجعة الدائرة وإبداء رأي أو مشورة في أي قضية سبق له تدقيقها أو تقديرها","العمل محاسباً قانونياً لمدة ثلاث سنوات","مراجعة الدائرة في أي قضية مطلقاً","تمثيل أي مكلف أمام المحاكم الضريبية"],"a":0}]},{"n":"71","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-\n١-على الرغم مما ورد في هذا القانون، للمدير بناء على طلب المكلف إجراء المصالحة بقضايا ضريبة الدخل وضريبة المبيعات والمبالغ الأخرى المسجلة لدى القضاء قبل تاريخ ٢٠١٨/١٢/٣١، باستثناء جرائم التهرب الضريبي ويترتب على إجراء هذه المصالحة إنهاء القضية، وعلى المحكمة المصادقة على المصالحة واعتبارها حكماً نهائياً.\n٢-يجب أن لا تقل نسبة المصالحة المشار إليها في البند (١) من هذه الفقرة عن (٢٥%) من المبلغ المتنازع عليه.\nب-يكون الإعفاء من الضريبة والغرامات والفوائد بقرار من مجلس الوزراء بناء على تنسيب الوزير ووفقاً للأسس التالية:\n١-إعفاء كل شخص لم يقدم الإقرار الضريبي أو لم يتم التقدير والتدقيق عليه قبل نفاذ أحكام هذا القانون المعدل وكانت الضريبة المستحقة في تلك الفترات تقل عن مليون دينار من كامل الغرامات المتحققة على دخله عن الفترات الضريبية السابقة على تاريخ نفاذ أحكام هذا القانون وذلك في حال التصريح عن هذا الدخل شريطة قيامه بتقديم إقرارات ضريبية عن عام ٢٠١٨ وعن الفترات الضريبية اللاحقة خلال المدة القانونية.\n٢-إعفاء كل مكلف استحقت عليه ضرائب قطعية تقل عن مليون دينار عن الفترات الضريبية السابقة لتاريخ نفاذ هذا القانون المعدل بما نسبته (٩٠%) من الغرامات والفوائد شريطة التقدم بطلب لتسوية الأرصدة الضريبية المستحقة عليه خلال (١٨٠) يوماً من سريان أحكام هذا القانون.\n٣-إعفاء كل شخص لم يتم اكتشافه من الدائرة من الملاحقة الجزائية والغرامات والفوائد في حال أعلم الدائرة طوعياً عن دخله الصحيح الذي سيتقدم به للفترات الضريبية اللاحقة شريطة دفع الأرصدة الضريبية حسب الإقرار السابق خلال (١٨٠) يوماً من تاريخ سريان أحكام هذا القانون المعدل.","title":"المصالحة والإعفاء من الغرامات (تسوية ٢٠١٨)","memo":"⭐ للمدير بطلب من المكلف المصالحة في القضايا المسجلة لدى القضاء قبل ٢٠١٨/١٢/٣١ باستثناء جرائم التهرب، بنسبة لا تقل عن (٢٥%) من المبلغ المتنازع عليه\n⭐ الإعفاء بقرار من مجلس الوزراء بتنسيب الوزير\n⭐ من لم يقدم إقراراً وضريبته أقل من مليون دينار: إعفاء من كامل الغرامات إن صرح وقدم إقرارات ٢٠١٨ وما بعدها\n⭐ ضرائب قطعية أقل من مليون دينار: إعفاء (٩٠%) من الغرامات والفوائد إن قدم طلب التسوية خلال (١٨٠) يوماً","qs":[{"q":"يجب ألا تقل نسبة المصالحة في قضايا ضريبة الدخل والمبيعات المسجلة لدى القضاء قبل ٢٠١٨/١٢/٣١ عن:","o":["(٢٥%) من المبلغ المتنازع عليه","(٥٠%) من المبلغ المتنازع عليه","(١٠%) من المبلغ المتنازع عليه","(٩٠%) من المبلغ المتنازع عليه"],"a":0},{"q":"يكون الإعفاء من الضريبة والغرامات والفوائد وفق المادة (٧١) بقرار من:","o":["مجلس الوزراء بناءً على تنسيب الوزير","الوزير بناءً على تنسيب المدير","المدير بناءً على طلب المكلف","المحكمة الضريبية"],"a":0},{"q":"مكلف استحقت عليه ضرائب قطعية تقل عن مليون دينار عن فترات سابقة لنفاذ القانون المعدل وتقدم بطلب تسوية خلال المدة المحددة، فيعفى من الغرامات والفوائد بنسبة:","o":["(٩٠%)","(١٠٠%)","(٧٥%)","(٥٠%)"],"a":0},{"q":"تستثنى من المصالحة في القضايا المسجلة لدى القضاء قبل ٢٠١٨/١٢/٣١:","o":["جرائم التهرب الضريبي","قضايا ضريبة المبيعات","القضايا المتعلقة بالمبالغ الأخرى","القضايا المنظورة أمام محكمة الاستئناف الضريبية"],"a":0}]},{"n":"72","chapter":"","notes":[],"source":"يجوز للمدير أو الموظف المفوض منه أو المدقق حسب مقتضى الحال وفي أي وقت أن يصحح من تلقاء ذاته أو بناءً على طلب المكلف الأخطاء الكتابية والحسابية التي تقع في القرارات والإشعارات والمذكرات عن طريق السهو العرضي ولا تكون إجراءات التصحيح خاضعة للطعن.","title":"تصحيح الأخطاء الكتابية والحسابية","memo":"⭐ للمدير أو الموظف المفوض أو المدقق في أي وقت تصحيح الأخطاء الكتابية والحسابية الواقعة سهواً من تلقاء ذاته أو بطلب المكلف\n⭐ عبارة (ولا تكون إجراءات التصحيح خاضعة للطعن) قضت المحكمة الدستورية بعدم دستوريتها بقرارها رقم (٧) لسنة ٢٠١٨","qs":[{"q":"يجوز تصحيح الأخطاء الكتابية والحسابية التي تقع في القرارات والإشعارات عن طريق السهو العرضي:","o":["في أي وقت من تلقاء ذات المدير أو المفوض أو المدقق أو بناءً على طلب المكلف","خلال ثلاثين يوماً من صدور القرار فقط","بقرار من المحكمة الضريبية فقط","بناءً على طلب المكلف فقط خلال ستين يوماً"],"a":0},{"q":"الأخطاء التي يجوز تصحيحها وفق المادة (٧٢) هي:","o":["الأخطاء الكتابية والحسابية الواقعة عن طريق السهو العرضي","الأخطاء في تقدير الدخل الخاضع للضريبة","الأخطاء في تطبيق نصوص القانون","الأخطاء الناتجة عن إخفاء المكلف لمستنداته"],"a":0}]},{"n":"73","chapter":"","notes":[],"source":"أ-باستثناء صلاحية إصدار التعليمات التنفيذية والتعليمات وفقاً لأحكام هذا القانون:\n١-للوزير أن يفوض أياً من صلاحياته المنصوص عليها في هذا القانون للمدير.\n1 صدر قرار المحكمة الدستورية رقم (٧) لسنة ٢٠١٨ المنشور في عدد الجريدة الرسمية ٥٥٤٩ تاريخ ٢٠١٨/١٢/٣ المتضمن عدم دستورية الجزء الأخير من المادة (٧٢) ((ولا تكون إجراءات التصحيح خاضعة للطعن)).\n٢-للمدير أن يفوض أياً من صلاحياته المنصوص عليها في هذا القانون إلى أي موظف في الدائرة.\nب-مع مراعاة أحكام المادة (٢١) من هذا القانون، يجب أن يكون التفويض المنصوص عليه في الفقرة (أ) من هذه المادة خطياً ومحدداً.","title":"تفويض الصلاحيات","memo":"⭐ للوزير تفويض أي من صلاحياته للمدير، وللمدير تفويض أي من صلاحياته لأي موظف في الدائرة\n⭐ يستثنى من التفويض صلاحية إصدار التعليمات التنفيذية والتعليمات\n⭐ يجب أن يكون التفويض خطياً ومحدداً","qs":[{"q":"أي من الصلاحيات التالية لا يجوز للوزير تفويضها للمدير؟","o":["إصدار التعليمات التنفيذية والتعليمات","البت في الاعتراض على الغرامات","تعيين ممثلي الدائرة في القضايا الحقوقية","منع شخص من مراجعة الدائرة"],"a":0},{"q":"يشترط في تفويض الصلاحيات المنصوص عليه في المادة (٧٣) أن يكون:","o":["خطياً ومحدداً","شفهياً أو خطياً","منشوراً في الجريدة الرسمية","مصادقاً عليه من مجلس الوزراء"],"a":0},{"q":"يجوز للمدير أن يفوض أياً من صلاحياته المنصوص عليها في القانون إلى:","o":["أي موظف في الدائرة","الوزير","أي محاسب قانوني","أعضاء النيابة العامة الضريبية فقط"],"a":0}]},{"n":"74","chapter":"","notes":[],"source":"يستمر الأشخاص الذين يتمتعون بمعاملة ضريبية تفضيلية بموجب أحكام أي تشريع نافذ قبل ٢٠١٠/١/١ في الخضوع للضريبة وفقاً لتلك المعاملة حتى نهاية المدة المحددة بمقتضى أحكام تلك التشريعات.","title":"استمرار المعاملة الضريبية التفضيلية","memo":"⭐ من يتمتع بمعاملة ضريبية تفضيلية بموجب تشريع نافذ قبل ٢٠١٠/١/١ يستمر خضوعه لها حتى نهاية المدة المحددة في تلك التشريعات","qs":[{"q":"الأشخاص الذين يتمتعون بمعاملة ضريبية تفضيلية بموجب تشريع نافذ قبل ٢٠١٠/١/١:","o":["يستمرون في الخضوع للضريبة وفقاً لتلك المعاملة حتى نهاية المدة المحددة في تلك التشريعات","تلغى معاملتهم التفضيلية فوراً","يستمرون بها لمدة خمس سنوات فقط","يستمرون بها بقرار من مجلس الوزراء"],"a":0},{"q":"التاريخ الذي يشترط أن يكون التشريع المانح للمعاملة الضريبية التفضيلية نافذاً قبله لاستمرارها:","o":["٢٠١٠/١/١","٢٠١٥/١/١","٢٠١٨/١٢/٣١","٢٠٠٩/١/١"],"a":0}]},{"n":"75","chapter":"","notes":[],"source":"ما لم ينص هذا القانون على خلاف ذلك تُحسب المواعيد المعينة بالشهر أو السنة بالتقويم الميلادي وفي حال صادف آخر الميعاد عطلة رسمية امتد إلى أول يوم عمل بعدها.","title":"حساب المواعيد","memo":"⭐ تحسب المواعيد بالشهر أو السنة بالتقويم الميلادي ما لم ينص القانون على خلاف ذلك\n⭐ إذا صادف آخر الميعاد عطلة رسمية امتد إلى أول يوم عمل بعدها","qs":[{"q":"تحسب المواعيد المعينة بالشهر أو السنة في قانون ضريبة الدخل ما لم ينص على خلاف ذلك:","o":["بالتقويم الميلادي","بالتقويم الهجري","بالسنة المالية للمكلف","بأيام العمل الرسمية"],"a":0},{"q":"انتهى ميعاد تقديم الطعن في يوم عطلة رسمية، فإن الميعاد:","o":["يمتد إلى أول يوم عمل بعدها","ينتهي في يوم العطلة","يمتد سبعة أيام","يعتبر منتهياً في آخر يوم عمل قبل العطلة"],"a":0}]},{"n":"76","chapter":"","notes":[],"source":"للوزير بناء على تنسيب المدير منح موظفي الدائرة المكافآت والحوافز ويحدد مقدارها وأسس منحها بموجب نظام يصدر لهذه الغاية على أن يخصص ذلك سنوياً ضمن الموازنة العامة للدولة.","title":"مكافآت وحوافز موظفي الدائرة","memo":"⭐ للوزير بتنسيب المدير منح موظفي الدائرة المكافآت والحوافز، ويحدد مقدارها وأسس منحها بنظام، وتخصص سنوياً ضمن الموازنة العامة","qs":[{"q":"يملك صلاحية منح موظفي الدائرة المكافآت والحوافز:","o":["الوزير بناءً على تنسيب المدير","المدير بناءً على تنسيب لجنة","مجلس الوزراء بناءً على تنسيب الوزير","ديوان المحاسبة"],"a":0},{"q":"يحدد مقدار المكافآت والحوافز لموظفي الدائرة وأسس منحها بموجب:","o":["نظام يصدر لهذه الغاية","تعليمات يصدرها المدير","قرار من الوزير","قرار من ديوان الخدمة المدنية"],"a":0}]},{"n":"77","chapter":"","notes":[],"source":"أ-يصدر مجلس الوزراء الأنظمة اللازمة لتنفيذ أحكام هذا القانون.\nب-يصدر الوزير بتنسيب من المدير التعليمات التنفيذية اللازمة لتنفيذ أحكام هذا القانون على أن يتم نشرها في الجريدة الرسمية.\nج-يستمر العمل بالأنظمة والتعليمات التنفيذية والتعليمات الصادرة قبل نفاذ أحكام هذا القانون إلى المدى الذي لا تتعارض فيه مع أحكامه إلى أن تعدل أو تلغى أو يستبدل غيرها بها وفقاً لأحكام هذا القانون.","title":"الأنظمة والتعليمات التنفيذية","memo":"⭐ يصدر مجلس الوزراء الأنظمة اللازمة لتنفيذ القانون\n⭐ يصدر الوزير بتنسيب المدير التعليمات التنفيذية وتنشر في الجريدة الرسمية\n⭐ تستمر الأنظمة والتعليمات السابقة بما لا يتعارض مع القانون إلى أن تعدل أو تلغى","qs":[{"q":"الجهة المختصة بإصدار الأنظمة اللازمة لتنفيذ أحكام قانون ضريبة الدخل:","o":["مجلس الوزراء","الوزير","المدير","مجلس الأمة"],"a":0},{"q":"تصدر التعليمات التنفيذية اللازمة لتنفيذ أحكام قانون ضريبة الدخل من:","o":["الوزير بتنسيب من المدير على أن تنشر في الجريدة الرسمية","المدير دون حاجة لنشرها","مجلس الوزراء بتنسيب الوزير","الوزير دون حاجة لنشرها"],"a":0},{"q":"الأنظمة والتعليمات الصادرة قبل نفاذ قانون ضريبة الدخل:","o":["يستمر العمل بها إلى المدى الذي لا تتعارض فيه مع أحكامه إلى أن تعدل أو تلغى","تلغى حكماً من تاريخ نفاذه","يستمر العمل بها لمدة سنة واحدة فقط","يستمر العمل بها حتى لو تعارضت مع أحكامه"],"a":0}]},{"n":"78","chapter":"","notes":[],"source":"أ-مع مراعاة أحكام الفقرة (ب) من هذه المادة، لا تطبق أي أحكام وردت في أي تشريع آخر تتعلق بفرض الضريبة أو الإعفاء منها كلياً أو جزئياً باستثناء ما ورد النص عليه بمقتضى أحكام كل من القوانين التالية:\n١-قانون صندوق الزكاة رقم (٨) لسنة ١٩٨٨.\n٢-قانون مؤسسة الحسين للسرطان رقم (٧) لسنة ١٩٩٨ وتعديلاته.\n٣-قانون مؤسسة الملك الحسين بن طلال رقم (٢٢) لسنة ١٩٩٩.\n٤-قانون الهيئة الوطنية لإزالة الألغام وإعادة التأهيل رقم (٣٤) لسنة ٢٠٠٠.\n٥-قانون المجلس الوطني لشؤون الأسرة رقم (٢٧) لسنة ٢٠٠١.\n٦-قانون مؤسسة نهر الأردن رقم (٣٣) لسنة ٢٠٠١.\n٧-قانون صندوق الملك عبد الله الثاني للتنمية رقم (٣٧) لسنة ٢٠٠٤.\n٨-قانون الإعفاء من الأموال العامة رقم (٢٨) لسنة ٢٠٠٦.\n٩-قانون الصندوق الهاشمي لإعمار المسجد الأقصى المبارك وقبة الصخرة المشرفة رقم (١٥) لسنة ٢٠٠٧.\n١٠-قانون مؤسسة آل البيت الملكية للفكر الإسلامي رقم (٣٢) لسنة ٢٠٠٧.\n١١-قانون الصندوق الأردني الهاشمي للتنمية البشرية رقم (٣٧) لسنة ١٩٨٥.\n١٢-القوانين الخاصة بالتصديق على اتفاقيات الامتياز.\nب-تطبق الأحكام الواردة في كل من قانون منطقة العقبة الاقتصادية الخاصة وقانون الاستثمار فيما يتعلق بفرض الضريبة والإعفاء منها.\nج-على الرغم مما ورد في البند (٨) من الفقرة (أ) من هذه المادة، لا يجوز الإعفاء من أي ضريبة تستحق بعد نفاذ أحكام هذا القانون المعدل.","title":"حصر الإعفاءات في التشريعات الأخرى","memo":"⭐ لا تطبق أحكام فرض الضريبة أو الإعفاء منها الواردة في تشريعات أخرى إلا ما ورد في القوانين المعددة (كصندوق الزكاة ومؤسسة الحسين للسرطان والقوانين الخاصة بالتصديق على اتفاقيات الامتياز)\n⭐ تطبق أحكام قانون منطقة العقبة الاقتصادية الخاصة وقانون الاستثمار في فرض الضريبة والإعفاء منها\n⭐ رغم قانون الإعفاء من الأموال العامة لا يجوز الإعفاء من أي ضريبة تستحق بعد نفاذ القانون المعدل","qs":[{"q":"من القوانين التي تطبق أحكامها فيما يتعلق بفرض الضريبة والإعفاء منها وفق الفقرة (ب) من المادة (٧٨):","o":["قانون منطقة العقبة الاقتصادية الخاصة وقانون الاستثمار","قانون الشركات وقانون البنوك","قانون الجمارك وقانون الضريبة العامة على المبيعات","قانون العمل وقانون الضمان الاجتماعي"],"a":0},{"q":"أي من القوانين التالية لم يرد ضمن القوانين المستثناة التي تطبق أحكامها في الإعفاء من الضريبة؟","o":["قانون الشركات","قانون صندوق الزكاة","قانون مؤسسة الحسين للسرطان","القوانين الخاصة بالتصديق على اتفاقيات الامتياز"],"a":0},{"q":"على الرغم مما ورد في قانون الإعفاء من الأموال العامة، فإنه لا يجوز الإعفاء من:","o":["أي ضريبة تستحق بعد نفاذ أحكام القانون المعدل","الغرامات المترتبة قبل نفاذ القانون","الضرائب المستحقة قبل عام ٢٠١٠","فوائد التأخير فقط"],"a":0}]},{"n":"79","chapter":"","notes":["أضيف النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"أ-يلغى قانون ضريبة الدخل المؤقت رقم (٢٨) لسنة ٢٠٠٩ على أن يتم فرض الضريبة والضريبة المضافة ومنح الخصم التشجيعي عن:\n١-كل سنة ضريبية قبل سنة ١٩٨٢ وفق قانون ضريبة الدخل رقم (٢٥) لسنة ١٩٦٤ وتعديلاته.\n٢-الدخول المتحققة في السنوات ١٩٨٢ و١٩٨٣ و١٩٨٤ وفق قانون ضريبة الدخل المؤقت رقم (٣٤) لسنة ١٩٨٢.\n٣-الدخول المتحققة في كل من السنوات من ١٩٨٥ ولغاية سنة ٢٠٠٩ وفق قانون ضريبة الدخل رقم (٥٧) لسنة ١٩٨٥ وتعديلاته.\n٤-الدخول المتحققة في السنوات ٢٠١٠ و٢٠١١ و٢٠١٢ و٢٠١٣ و٢٠١٤ وفق قانون ضريبة الدخل المؤقت رقم (٢٨) لسنة ٢٠٠٩.\nب-تعتبر كشوف التقدير الذاتي المقدمة قبل ٢٠١٠/١/١ والمقدمة بعد هذا التاريخ عن السنوات السابقة لسنة ٢٠١٠ والإقرارات المقدمة عن السنوات ٢٠١٠ و٢٠١١ و٢٠١٢ و٢٠١٣ و٢٠١٤ إقرارات ضريبية بالمعنى المقصود في هذا القانون وتسري عليها الأحكام الإجرائية الواردة فيه.\nج-مع مراعاة أحكام الفقرة (د) من هذه المادة، تلغى التشريعات التالية اعتباراً من تاريخ نفاذ أحكام هذا القانون:\n١-قانون ضريبة الخدمات الاجتماعية رقم (٨٩) لسنة ١٩٥٣ وما طرأ عليه من تعديل.\n٢-المادة (٨/أ/١) من قانون مجلس التشغيل والتدريب والتعليم المهني والتقني رقم (٤٦) لسنة ٢٠٠٨.\nد-يتم تحصيل الضرائب والرسوم وأي مبالغ أخرى مقررة بمقتضى أحكام التشريعات المبينة في الفقرة (ج) عن الفترة السابقة لتاريخ سريان أحكام قانون ضريبة الدخل المؤقت رقم (٢٨) لسنة ٢٠٠٩ وفق الأحكام والإجراءات المقررة في تلك التشريعات.\nهـ-يلغى قانون الرسوم الإضافية للجامعات الأردنية رقم (٤) لسنة ١٩٨٥ وما طرأ عليه من تعديل اعتباراً من ٢٠١١/١/١.","title":"الإلغاءات والأحكام الانتقالية","memo":"⭐ يلغى قانون ضريبة الدخل المؤقت رقم (٢٨) لسنة ٢٠٠٩ مع فرض الضريبة عن كل فترة وفق القانون النافذ فيها\n⭐ قبل ١٩٨٢ وفق القانون (٢٥) لسنة ١٩٦٤؛ ١٩٨٢–١٩٨٤ وفق (٣٤) لسنة ١٩٨٢؛ ١٩٨٥–٢٠٠٩ وفق (٥٧) لسنة ١٩٨٥؛ ٢٠١٠–٢٠١٤ وفق (٢٨) لسنة ٢٠٠٩\n⭐ تلغى ضريبة الخدمات الاجتماعية رقم (٨٩) لسنة ١٩٥٣ والمادة (٨/أ/١) من قانون مجلس التشغيل\n⭐ يلغى قانون الرسوم الإضافية للجامعات الأردنية رقم (٤) لسنة ١٩٨٥ اعتباراً من ٢٠١١/١/١","qs":[{"q":"تفرض الضريبة على الدخول المتحققة في السنوات من ١٩٨٥ ولغاية ٢٠٠٩ وفق:","o":["قانون ضريبة الدخل رقم (٥٧) لسنة ١٩٨٥ وتعديلاته","قانون ضريبة الدخل المؤقت رقم (٢٨) لسنة ٢٠٠٩","قانون ضريبة الدخل رقم (٢٥) لسنة ١٩٦٤","قانون ضريبة الدخل المؤقت رقم (٣٤) لسنة ١٩٨٢"],"a":0},{"q":"يلغى قانون الرسوم الإضافية للجامعات الأردنية رقم (٤) لسنة ١٩٨٥ اعتباراً من:","o":["٢٠١١/١/١","٢٠١٠/١/١","٢٠١٥/١/١","٢٠١٩/١/١"],"a":0},{"q":"تفرض الضريبة على الدخول المتحققة في السنوات ٢٠١٠ إلى ٢٠١٤ وفق:","o":["قانون ضريبة الدخل المؤقت رقم (٢٨) لسنة ٢٠٠٩","قانون ضريبة الدخل رقم (٣٤) لسنة ٢٠١٤","قانون ضريبة الدخل رقم (٥٧) لسنة ١٩٨٥","القانون المعدل رقم (٣٨) لسنة ٢٠١٨"],"a":0}]},{"n":"80","chapter":"","notes":[],"source":"يستمر تحصيل الضرائب والرسوم وأي مبالغ أخرى مقررة بمقتضى أحكام أي تشريعات نافذة قبل ٢٠١٠/١/١ وفق الأحكام والإجراءات المقررة في تلك التشريعات.","title":"تحصيل الضرائب وفق التشريعات السابقة","memo":"⭐ يستمر تحصيل الضرائب والرسوم المقررة بتشريعات نافذة قبل ٢٠١٠/١/١ وفق الأحكام والإجراءات المقررة في تلك التشريعات","qs":[{"q":"الضرائب والرسوم المقررة بمقتضى تشريعات نافذة قبل ٢٠١٠/١/١ يستمر تحصيلها وفق:","o":["الأحكام والإجراءات المقررة في تلك التشريعات","أحكام وإجراءات قانون ضريبة الدخل رقم (٣٤) لسنة ٢٠١٤","تعليمات يصدرها المدير","قرار من مجلس الوزراء"],"a":0}]},{"n":"81","chapter":"","notes":[],"source":"يجوز منح حوافز ضريبية لقطاعات محددة وفقا لمقتضيات المصلحة الاقتصادية ويتم تحديد جميع الشؤون المتعلقة بهذه الحوافز بما في ذلك كلفها ومددها الزمنية بمقتضى نظام يصدر لهذه الغاية.","title":"الحوافز الضريبية للقطاعات","memo":"⭐ يجوز منح حوافز ضريبية لقطاعات محددة وفق مقتضيات المصلحة الاقتصادية، وتحدد شؤونها (كلفها ومددها الزمنية) بنظام","qs":[{"q":"يتم تحديد جميع الشؤون المتعلقة بالحوافز الضريبية للقطاعات المحددة بما في ذلك كلفها ومددها الزمنية بمقتضى:","o":["نظام يصدر لهذه الغاية","تعليمات تنفيذية يصدرها الوزير","قرار من المدير","قانون خاص"],"a":0},{"q":"يجوز منح الحوافز الضريبية لقطاعات محددة وفقاً لـ:","o":["مقتضيات المصلحة الاقتصادية","طلب المكلفين في القطاع","توصية ديوان المحاسبة","حجم الضريبة المدفوعة من القطاع"],"a":0}]},{"n":"82","chapter":"","notes":["عدل النص بموجب القانون المعدل رقم (٣٨) لسنة ٢٠١٨."],"source":"رئيس الوزراء والوزراء مكلفون بتنفيذ أحكام هذا القانون.","title":"تنفيذ القانون","memo":"⭐ رئيس الوزراء والوزراء مكلفون بتنفيذ أحكام هذا القانون","qs":[]}]};
